fn rebar_complete_spans_portable_build_limits() -> fre::BuildLimits {
    let mut limits = fre::BuildLimits::default();
    let rebar_limits = RunLimits::default();
    // Rebar's generated dictionary alternations legitimately exceed the
    // portable facade's conservative standalone 262,144-state default. Keep
    // this adapter-specific allowance finite and mutually consistent: at
    // most four million validated states, eight million edges, and the existing
    // 128 MiB automaton-storage ceiling. Construction work is separately
    // bounded by the syntax safety envelope's 64-million-unit ceiling.
    limits.lowering.max_work = 64_000_000;
    limits.lowering.automata.max_states = 4_194_304;
    limits.lowering.automata.max_edges = 8_388_608;
    limits.lowering.automata.max_validation_work = 16_777_216;
    limits.max_planner_work = 64_000_000;
    // Portable reverse-inner derives its source-range quota from this shared
    // class-range field. Match the already-authenticated Rebar aggregate
    // policy instead of retaining the portable facade's standalone 256-range
    // default.
    limits.literal_class_run_literal.max_class_ranges =
        rebar_limits.fre_unicode_scalar_build_source_ranges;
    limits
}

fn rebar_complete_spans_portable_visit_limits(
    haystack_len: usize,
    limits: &RunLimits,
) -> Result<PortableSpanVisitLimits, CompareError> {
    let max_match_events = usize::try_from(limits.reducer_steps)
        .map_err(|_| CompareError::new("FRE complete-spans reducer limit does not fit usize"))?
        .min(haystack_len.saturating_add(1));
    let max_span_sum = u64::try_from(haystack_len)
        .map_err(|_| CompareError::new("FRE complete-spans span bound does not fit u64"))?;
    let direct_work = u64::try_from(limits.fre_aggregate_operation_work)
        .map_err(|_| CompareError::new("FRE complete-spans direct work limit does not fit u64"))?;
    Ok(PortableSpanVisitLimits {
        exact_literal: LiteralSpanVisitLimits {
            max_input_bytes: haystack_len,
            max_linear_terms: usize::try_from(limits.fre_aggregate_operation_work)
                .unwrap_or(usize::MAX),
            max_finder_calls: haystack_len.saturating_add(1),
            max_match_events,
            max_span_sum,
            max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
            max_persistent_bytes: limits.fre_literal_build_persistent_bytes,
            max_peak_bytes: limits.fre_aggregate_peak_bytes,
        },
        literal_class_run_literal: LiteralClassRunLiteralReduceLimits {
            max_input_bytes: haystack_len,
            max_source_reads: limits.fre_aggregate_random_access_bytes,
            max_work: limits.fre_aggregate_operation_work,
            max_run_events: haystack_len,
            max_match_events,
            max_count: max_span_sum.min(limits.reducer_steps),
            max_span_sum,
            max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
            max_persistent_bytes: limits.fre_literal_build_persistent_bytes,
            max_peak_bytes: limits.fre_aggregate_peak_bytes,
        },
        prefix_class_alternation: PrefixClassAlternationReduceLimits {
            max_work: limits.fre_aggregate_operation_work,
            max_match_events,
            max_count: max_span_sum.min(limits.reducer_steps),
            max_span_sum,
            max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
            max_peak_bytes: limits.fre_aggregate_peak_bytes,
        },
        lazy_delimited_repeat: LazyDelimitedRepeatSpanVisitLimits {
            max_input_bytes: haystack_len,
            max_source_reads: u64::try_from(limits.fre_aggregate_random_access_bytes)
                .unwrap_or(u64::MAX),
            max_work: u64::try_from(limits.fre_aggregate_operation_work).unwrap_or(u64::MAX),
            max_finder_calls: haystack_len.saturating_add(1),
            max_pair_candidates: haystack_len,
            max_event_visits: haystack_len,
            max_match_events,
            max_count: max_span_sum.min(limits.reducer_steps),
            max_span_sum,
            max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
            max_persistent_bytes: limits.fre_literal_build_persistent_bytes,
            max_peak_bytes: limits.fre_aggregate_peak_bytes,
        },
        k0_casefold_prefix_class: K0CasefoldPrefixClassSpanVisitLimits {
            max_input_bytes: haystack_len,
            max_source_reads: u64::try_from(limits.fre_aggregate_random_access_bytes)
                .unwrap_or(u64::MAX),
            max_work: direct_work,
            max_candidate_starts: haystack_len.saturating_mul(8),
            max_prefix_byte_checks: haystack_len.saturating_mul(64),
            max_class_byte_checks: haystack_len.saturating_mul(12),
            max_match_events,
            max_span_sum,
        },
        greedy_class_literal_tail: GreedyClassLiteralTailSpanVisitLimits {
            max_input_bytes: haystack_len,
            max_source_reads: u64::try_from(limits.fre_aggregate_random_access_bytes)
                .unwrap_or(u64::MAX),
            max_work: u64::try_from(limits.fre_aggregate_operation_work).unwrap_or(u64::MAX),
            max_finder_calls: haystack_len.saturating_mul(2).saturating_add(1),
            max_class_probes: limits.fre_aggregate_random_access_bytes,
            max_match_events,
            max_count: max_span_sum.min(limits.reducer_steps),
            max_span_sum,
            max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
            max_persistent_bytes: limits.fre_literal_build_persistent_bytes,
            max_peak_bytes: limits.fre_aggregate_peak_bytes,
        },
        greedy_delimited_corridor: GreedyDelimitedCorridorSpanVisitLimits {
            max_input_bytes: haystack_len,
            max_source_reads: u64::try_from(limits.fre_aggregate_random_access_bytes)
                .unwrap_or(u64::MAX),
            max_work: u64::try_from(limits.fre_aggregate_operation_work).unwrap_or(u64::MAX),
            max_finder_calls: haystack_len.saturating_add(2),
            max_anchor_events: haystack_len,
            max_region_events: haystack_len.saturating_add(1) / 2,
            max_query_probes: limits.fre_aggregate_operation_work,
            max_match_events,
            max_count: max_span_sum.min(limits.reducer_steps),
            max_span_sum,
            max_scratch_allocations: 4,
            max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
            max_persistent_bytes: limits.fre_literal_build_persistent_bytes,
            max_peak_bytes: limits.fre_aggregate_peak_bytes,
        },
        unicode_token_phrase: UnicodeTokenPhraseSpanVisitLimits {
            max_input_bytes: haystack_len,
            max_source_reads: u64::try_from(limits.fre_aggregate_random_access_bytes)
                .unwrap_or(u64::MAX),
            max_work: u64::try_from(limits.fre_aggregate_operation_work).unwrap_or(u64::MAX),
            max_finder_calls: haystack_len.saturating_add(1),
            max_anchor_candidates: haystack_len,
            max_decode_attempts: haystack_len.saturating_mul(16),
            max_match_events,
            max_count: max_span_sum.min(limits.reducer_steps),
            max_span_sum,
            max_scratch_bytes: 0,
            max_persistent_bytes: 0,
            max_peak_bytes: 0,
        },
    })
}

fn rebar_complete_spans_fixed_predicate_visit_limits(
    haystack_len: usize,
    limits: &RunLimits,
) -> Result<FixedPredicateWord64ReduceLimits, CompareError> {
    let max_match_events = usize::try_from(limits.reducer_steps)
        .map_err(|_| CompareError::new("FRE complete-spans reducer limit does not fit usize"))?
        .min(haystack_len.saturating_add(1));
    let max_span_sum = u64::try_from(haystack_len)
        .map_err(|_| CompareError::new("FRE complete-spans span bound does not fit u64"))?;
    Ok(FixedPredicateWord64ReduceLimits {
        max_input_bytes: haystack_len,
        max_transitions: haystack_len,
        max_match_events,
        max_count: max_span_sum.min(limits.reducer_steps),
        max_span_sum,
        max_reducer_steps: usize::try_from(limits.reducer_steps).unwrap_or(usize::MAX),
        max_work: u64::try_from(limits.fre_aggregate_operation_work).unwrap_or(u64::MAX),
        max_scratch_bytes: limits.fre_aggregate_scratch_bytes,
        max_persistent_bytes: limits.fre_literal_build_persistent_bytes,
        max_peak_bytes: limits.fre_aggregate_peak_bytes,
    })
}

fn portable_plan_kind_label(plan: PlanKind) -> &'static str {
    match plan {
        PlanKind::ExactLiteral => "exact-literal",
        PlanKind::PackedLiteralSet => "packed-literal-set",
        PlanKind::LiteralSetDfa => "literal-set-dfa",
        PlanKind::RequiredLiteral => "required-literal",
        PlanKind::LiteralClassRunLiteral => "literal-class-run-literal",
        PlanKind::ReverseInner => "reverse-inner",
        PlanKind::PrefixClassAlternation => "prefix-class-alternation",
        PlanKind::PureByteClassRepeat => "pure-byte-class-repeat",
        PlanKind::BoundedByteClassSequence => "bounded-byte-class-sequence",
        PlanKind::ForwardAnchored => "forward-anchored",
        PlanKind::K0 => "k0",
        PlanKind::UnicodeFoldedLiteral => "unicode-folded-literal",
        PlanKind::UnicodeWordRun => "unicode-word-run",
        PlanKind::FixedPredicateWord64 => "fixed-predicate-word64",
        PlanKind::UnicodeScalarRun => "unicode-scalar-run",
        PlanKind::LineDomainByteAtoms => "line-domain-byte-atoms",
    }
}

/// One immutable, single-pattern matcher for Rebar's complete-span reducer.
///
/// This owner is deliberately separate from [`CurrentFreCompleteSpansSession`]
/// so the latter can borrow the matcher and retain its K0 workspace without a
/// self-referential allocation. Construction and session preparation both
/// happen before either first or steady public-operation timing begins.
pub struct CurrentFreCompleteSpansRegex {
    inner: CurrentFreCompleteSpansRegexInner,
    plan: String,
    runtime_implementation_id: &'static str,
}

enum CurrentFreCompleteSpansRegexInner {
    Aggregate(AggregateSpanVisitorRegex),
    Portable(PortableRegex),
}

impl fmt::Debug for CurrentFreCompleteSpansRegex {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut debug = formatter.debug_struct("CurrentFreCompleteSpansRegex");
        match &self.inner {
            CurrentFreCompleteSpansRegexInner::Aggregate(regex) => {
                debug
                    .field("selected_plan", &regex.build_report().plan)
                    .field("runtime_implementation_id", &self.runtime_implementation_id);
            }
            CurrentFreCompleteSpansRegexInner::Portable(regex) => {
                debug
                    .field("pattern", &regex.as_str())
                    .field("profile", regex.profile())
                    .field("selected_plan", &regex.build_report().plan)
                    .field("runtime_implementation_id", &self.runtime_implementation_id);
            }
        }
        debug.field("plan", &self.plan).finish()
    }
}

impl CurrentFreCompleteSpansRegex {
    /// Exact authenticated construction-selected plan label.
    #[must_use]
    pub fn plan(&self) -> &str {
        &self.plan
    }

    /// Stable selected runtime identity of the immutable matcher.
    #[must_use]
    pub const fn runtime_implementation_id(&self) -> &'static str {
        self.runtime_implementation_id
    }

    /// Prepare the caller-owned session used by both first and steady
    /// complete-span public operations.
    ///
    /// # Errors
    ///
    /// Returns an error for a haystack-length policy refusal, checked iterator
    /// bound overflow, workspace refusal, or an impossible matcher/session
    /// identity mismatch.
    pub fn session(
        &self,
        haystack_len: usize,
    ) -> Result<CurrentFreCompleteSpansSession<'_>, CompareError> {
        self.session_with_limits(haystack_len, &RunLimits::default())
    }

    fn session_with_limits<'r>(
        &'r self,
        haystack_len: usize,
        limits: &RunLimits,
    ) -> Result<CurrentFreCompleteSpansSession<'r>, CompareError> {
        if haystack_len > limits.haystack_bytes {
            return Err(CompareError::new(format!(
                "FRE portable complete-spans haystack requires {haystack_len} bytes, limit is {}",
                limits.haystack_bytes
            )));
        }
        // Every selected non-overlapping byte match either advances the end
        // cursor or emits one empty match at a new byte boundary. Thus at most
        // `len + 1` contextual searches can execute, including a final miss.
        let max_search_calls = haystack_len.checked_add(1).ok_or_else(|| {
            CompareError::new("FRE portable complete-spans search-call bound overflow")
        })?;
        let search_limits = SearchLimits {
            max_work: limits.fre_search_work,
            max_scratch_bytes: limits.fre_scratch_bytes,
        };
        let portable_limits = PortableFindIterRunLimits {
            search: search_limits,
            max_search_calls,
        };
        let span_visit_limits = rebar_complete_spans_portable_visit_limits(haystack_len, limits)?;
        let fixed_predicate_span_visit_limits =
            rebar_complete_spans_fixed_predicate_visit_limits(haystack_len, limits)?;
        match &self.inner {
            CurrentFreCompleteSpansRegexInner::Aggregate(regex) => {
                let aggregate_limits =
                    complete_spans_run_limits_with_policy(haystack_len, regex, limits)
                        .map_err(|error| CompareError::new(error.message))?;
                let aggregate_span_visit_workspace =
                    regex.prepare_span_visit_workspace(haystack_len, aggregate_limits);
                if self.runtime_implementation_id == fre::SPARSE_ORDERED_LITERAL_TRACE_ALGORITHM_ID
                    && aggregate_span_visit_workspace.is_none()
                {
                    return Err(CompareError::new(
                        "FRE sparse complete-spans trace workspace preparation refused",
                    ));
                }
                Ok(CurrentFreCompleteSpansSession {
                    search: None,
                    aggregate: Some(regex),
                    aggregate_limits: Some(aggregate_limits),
                    aggregate_span_visit_workspace,
                    fixed_absolute_value_success: regex.build_report().plan
                        == AggregatePlanKind::FixedAbsoluteDomain,
                    fixed_predicate_span_visit: false,
                    runtime_implementation_id: self.runtime_implementation_id(),
                    haystack_len,
                    limits: portable_limits,
                    span_visit_limits,
                    fixed_predicate_span_visit_limits,
                    reducer_steps: limits.reducer_steps,
                })
            }
            CurrentFreCompleteSpansRegexInner::Portable(regex) => {
                let retained_runtime_implementation_id = regex.runtime_implementation_id();
                let search = regex
                    .search_session(SearchSessionLimits {
                        max_setup_work: search_limits.max_work,
                        max_scratch_bytes: search_limits.max_scratch_bytes,
                    })
                    .map_err(|error| {
                        CompareError::new(format!(
                            "FRE portable complete-spans search-session build failed: {error}"
                        ))
                    })?;
                if search.runtime_implementation_id() != retained_runtime_implementation_id {
                    return Err(CompareError::new(
                        "FRE portable complete-spans matcher/session runtime identity mismatch",
                    ));
                }
                Ok(CurrentFreCompleteSpansSession {
                    search: Some(search),
                    aggregate: None,
                    aggregate_limits: None,
                    aggregate_span_visit_workspace: None,
                    fixed_absolute_value_success: false,
                    fixed_predicate_span_visit: self.runtime_implementation_id
                        == FIXED_PREDICATE_WORD64_SPAN_VISIT_OPERATION_ID,
                    runtime_implementation_id: self.runtime_implementation_id,
                    haystack_len,
                    limits: portable_limits,
                    span_visit_limits,
                    fixed_predicate_span_visit_limits,
                    reducer_steps: limits.reducer_steps,
                })
            }
        }
    }
}

/// Reusable single-pattern Rebar complete-span operation session.
///
/// Each operation asks the retained semantic matcher for every complete
/// `(start, end)` pair and checked-sums `end - start`. Direct visitors may use
/// preflighted bounded scratch indexes; no span collection or continuation row
/// log is materialized.
#[derive(Debug)]
pub struct CurrentFreCompleteSpansSession<'r> {
    search: Option<PortableSearchSession<'r>>,
    aggregate: Option<&'r AggregateSpanVisitorRegex>,
    aggregate_limits: Option<AggregateRunLimits>,
    aggregate_span_visit_workspace: Option<AggregateSpanVisitWorkspace>,
    fixed_absolute_value_success: bool,
    fixed_predicate_span_visit: bool,
    runtime_implementation_id: &'static str,
    haystack_len: usize,
    limits: PortableFindIterRunLimits,
    span_visit_limits: PortableSpanVisitLimits,
    fixed_predicate_span_visit_limits: FixedPredicateWord64ReduceLimits,
    reducer_steps: u64,
}

#[derive(Debug)]
struct CompleteSpansReducer {
    matches: u64,
    sum: u64,
    max_matches: u64,
    failure: Option<CompareError>,
}

impl CompleteSpansReducer {
    const fn new(max_matches: u64) -> Self {
        Self {
            matches: 0,
            sum: 0,
            max_matches,
            failure: None,
        }
    }

    fn observe(&mut self, matched: fre::Match) {
        if self.failure.is_some() {
            return;
        }
        self.matches = match self.matches.checked_add(1) {
            Some(matches) => matches,
            None => {
                self.failure = Some(CompareError::new("FRE complete-spans match count overflow"));
                return;
            }
        };
        if self.matches > self.max_matches {
            self.failure = Some(CompareError::new(format!(
                "FRE complete-spans requires {} reducer events, limit is {}",
                self.matches, self.max_matches
            )));
            return;
        }
        let Some(width) = matched.end().checked_sub(matched.start()) else {
            self.failure = Some(CompareError::new(
                "FRE complete-spans result contained reversed match endpoints",
            ));
            return;
        };
        let Ok(width) = u64::try_from(width) else {
            self.failure = Some(CompareError::new(
                "FRE complete-spans match width does not fit u64",
            ));
            return;
        };
        let Some(sum) = self.sum.checked_add(width) else {
            self.failure = Some(CompareError::new("FRE complete-spans byte sum overflow"));
            return;
        };
        self.sum = sum;
    }

    fn finish(self) -> Result<(u64, u64), CompareError> {
        self.failure.map_or(Ok((self.matches, self.sum)), Err)
    }
}

#[inline(never)]
fn execute_fixed_predicate_complete_spans(
    search: &mut PortableSearchSession<'_>,
    haystack: &[u8],
    limits: FixedPredicateWord64ReduceLimits,
    reducer_steps: u64,
) -> Result<u64, CompareError> {
    let mut reducer = CompleteSpansReducer::new(reducer_steps);
    let result = search
        .try_visit_fixed_predicate_spans(haystack, limits, |matched| {
            reducer.observe(matched);
        })
        .map_err(|error| {
            CompareError::new(format!(
                "FRE fixed-predicate complete-spans traversal failed: {error}"
            ))
        })?
        .ok_or_else(|| {
            CompareError::new("FRE fixed-predicate complete-spans plan became ineligible")
        })?;
    let (matches, sum) = reducer.finish()?;
    let reported_matches = u64::try_from(result.matches).map_err(|_| {
        CompareError::new("FRE fixed-predicate complete-spans match count does not fit u64")
    })?;
    let accounting = result.accounting;
    let authenticated = accounting.identity.plan_id == FIXED_PREDICATE_WORD64_PLAN_ID
        && accounting.identity.operation_id == FIXED_PREDICATE_WORD64_SPAN_VISIT_OPERATION_ID
        && accounting.identity.operation == FixedPredicateWord64Operation::SpanVisit
        && accounting.identity.semantics == FixedPredicateWord64MatchSemantics::FixedBytePredicates
        && accounting.identity.selection
            == FixedPredicateWord64MatchSelection::LeftmostFirstNonOverlapping
        && accounting.identity.width >= 3
        && accounting.identity.reducer == FixedPredicateWord64Reducer::TwoByteAnchor
        && accounting.upper_bounds.input_bytes == haystack.len()
        && accounting.actual.input_bytes == haystack.len()
        && accounting.actual.transitions <= accounting.upper_bounds.transitions
        && accounting.actual.match_events <= accounting.upper_bounds.match_events
        && accounting.actual.matched_bytes <= accounting.upper_bounds.span_sum
        && accounting.actual.scratch_bytes == 0
        && accounting.actual.match_events == result.matches
        && accounting.actual.matched_bytes == result.span_sum;
    if !authenticated || matches != reported_matches || sum != result.span_sum {
        return Err(CompareError::new(
            "FRE fixed-predicate complete-spans visitor failed identity/accounting authentication",
        ));
    }
    Ok(sum)
}

fn authenticates_url_complete_spans_visit(
    regex: &AggregateSpanVisitorRegex,
    limits: &AggregateRunLimits,
    haystack_len: usize,
    result: &fre::AggregateSpanVisit,
) -> bool {
    if !regex.build_report().authenticates_url_aggregate_identity()
        || result.report().cache_identity() != regex.cache_identity(limits)
    {
        return false;
    }
    let fre::AggregateExecutionDetails::Continuation {
        certificate,
        accounting,
    } = result.report().details()
    else {
        return false;
    };
    let sequential_bytes = accounting
        .sequential_bytes_written
        .checked_add(accounting.sequential_bytes_read);
    certificate.operation == fre::AggregateOperationAttemptKind::SpanVisit
        && certificate.physical_route == fre::AggregateOperationPhysicalRoute::UrlAggregate
        && certificate.range == (0..haystack_len)
        && certificate.authenticates_limits(limits.continuation)
        && certificate.actual_allocations <= certificate.prospective_allocations
        && result.len() <= certificate.output_matches
        && result.len() <= certificate.match_events
        && certificate.output_bytes == 0
        && result.span_sum() <= certificate.span_sum
        && accounting.work <= certificate.work_bound
        && sequential_bytes.is_some_and(|bytes| bytes <= certificate.sequential_bytes_bound)
        && accounting.successful_paths == result.len()
        && accounting.emitted_matches == result.len()
        && accounting.output_bytes == 0
        && accounting.random_access_peak_bytes <= certificate.random_access_bytes
        && accounting.scratch_peak_bytes <= certificate.scratch_bytes
        && accounting.peak_bytes <= certificate.peak_bytes
}

impl CurrentFreCompleteSpansSession<'_> {
    /// Stable selected runtime identity inherited from the immutable matcher.
    #[must_use]
    pub const fn runtime_implementation_id(&self) -> &'static str {
        self.runtime_implementation_id
    }

    /// Validate the fixed haystack property bound during session preparation.
    ///
    /// Benchmark runners call this before starting their operation timer and
    /// then pass the same immutable slice to [`Self::execute_prevalidated`].
    ///
    /// # Errors
    ///
    /// Returns an error when the byte length differs from the prepared input.
    pub fn validate_haystack(&self, haystack: &[u8]) -> Result<(), CompareError> {
        if haystack.len() != self.haystack_len {
            return Err(CompareError::new(format!(
                "portable complete-spans haystack length {} differs from prepared {}",
                haystack.len(),
                self.haystack_len
            )));
        }
        Ok(())
    }

    /// Execute one complete Rebar byte match iteration on the retained
    /// matcher/session pair.
    ///
    /// Calling this once is the first-operation boundary. Calling it once
    /// untimed and then again is the steady-operation boundary.
    ///
    /// # Errors
    ///
    /// Returns an error for input-length mismatch, a bounded portable-search
    /// refusal, reducer-event exhaustion, reversed endpoints, or sum overflow.
    pub fn execute(&mut self, haystack: &[u8]) -> Result<u64, CompareError> {
        self.validate_haystack(haystack)?;
        self.execute_prevalidated(haystack)
    }

    /// Execute after [`Self::validate_haystack`] has authenticated the fixed
    /// input outside the measured operation boundary.
    ///
    /// This method begins directly at bounded match traversal and streaming
    /// reduction. It is public so the separately compiled Rebar runner can
    /// preserve that boundary; ordinary callers should prefer [`Self::execute`].
    ///
    /// # Errors
    ///
    /// Returns an error for a bounded portable-search refusal,
    /// reducer-event exhaustion, reversed endpoints, or sum overflow.
    pub fn execute_prevalidated(&mut self, haystack: &[u8]) -> Result<u64, CompareError> {
        if let (Some(regex), Some(limits)) = (self.aggregate, self.aggregate_limits.as_ref()) {
            if self.fixed_absolute_value_success {
                if let Some(value) = regex.fixed_absolute_spans_value_success(haystack, limits) {
                    if let Some(span) = value.span() {
                        if self.reducer_steps != 0 {
                            let width = span.end().checked_sub(span.start()).ok_or_else(|| {
                                CompareError::new(
                                    "FRE fixed complete-span value contained reversed endpoints",
                                )
                            })?;
                            return u64::try_from(width).map_err(|_| {
                                CompareError::new("FRE fixed complete-span width does not fit u64")
                            });
                        }
                    } else {
                        return Ok(0);
                    }
                }
            }
            let mut reducer = CompleteSpansReducer::new(self.reducer_steps);
            let result = if let Some(workspace) = self.aggregate_span_visit_workspace.as_mut() {
                regex.visit_spans_with_workspace(haystack, limits, workspace, |matched| {
                    reducer.observe(matched);
                })
            } else {
                regex.visit_spans(haystack, limits, |matched| {
                    reducer.observe(matched);
                })
            }
            .map_err(aggregate_lifecycle_complete_spans_error)?;
            let (matches, sum) = reducer.finish()?;
            let reported_matches = u64::try_from(result.len()).map_err(|_| {
                CompareError::new("FRE aggregate complete-spans match count does not fit u64")
            })?;
            let reported_sum = u64::try_from(result.span_sum()).map_err(|_| {
                CompareError::new("FRE aggregate complete-spans byte sum does not fit u64")
            })?;
            if matches != reported_matches || sum != reported_sum {
                return Err(CompareError::new(
                    "FRE aggregate complete-spans callbacks diverged from its visit summary",
                ));
            }
            if self.runtime_implementation_id == fre::URL_AGGREGATE_SPAN_VISIT_OPERATION_ID
                && !authenticates_url_complete_spans_visit(regex, limits, haystack.len(), &result)
            {
                return Err(CompareError::new(
                    "FRE URL complete-spans visitor failed identity/accounting authentication",
                ));
            }
            return Ok(sum);
        }
        let search = self.search.as_mut().ok_or_else(|| {
            CompareError::new("FRE complete-spans session retained no execution engine")
        })?;
        if self.fixed_predicate_span_visit {
            return execute_fixed_predicate_complete_spans(
                search,
                haystack,
                self.fixed_predicate_span_visit_limits,
                self.reducer_steps,
            );
        }
        let mut reducer = CompleteSpansReducer::new(self.reducer_steps);
        match search.try_visit_spans(haystack, self.span_visit_limits, |matched| {
            reducer.observe(matched);
        }) {
            Ok(Some(result)) => {
                let (matches, sum) = reducer.finish()?;
                let reported_matches = u64::try_from(result.matches).map_err(|_| {
                    CompareError::new(
                        "FRE portable complete-spans visitor match count does not fit u64",
                    )
                })?;
                let accounting_authenticated = match result.accounting {
                    PortableSpanVisitAccounting::ExactLiteral(accounting) => {
                        accounting.identity.operation_id == LITERAL_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.byte_empty_progress
                            && accounting.identity.leftmost
                            && accounting.identity.non_overlapping
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.upper_bounds.literal_bytes
                                == accounting.identity.literal_bytes
                            && accounting.upper_bounds.scratch_bytes == 0
                            && accounting.upper_bounds.peak_bytes
                                >= accounting.upper_bounds.persistent_bytes
                            && accounting.actual.finder_calls
                                <= accounting.upper_bounds.finder_calls
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::LiteralClassRunLiteral(accounting) => {
                        accounting.identity.plan_id == LITERAL_CLASS_RUN_LITERAL_PLAN_ID
                            && accounting.identity.operation_id
                                == LITERAL_CLASS_RUN_LITERAL_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.greedy
                            && accounting.identity.non_overlapping
                            && !accounting.identity.unicode
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::PrefixClassAlternation(accounting) => {
                        matches!(
                            accounting.identity.plan_id,
                            PREFIX_CLASS_ALTERNATION_PLAN_ID
                                | DISPATCHED_PREFIX_CLASS_ALTERNATION_PLAN_ID
                        ) && accounting.identity.operation_id
                            == PREFIX_CLASS_ALTERNATION_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.alternatives == 2
                            && !accounting.identity.unicode
                            && accounting.identity.non_overlapping
                            && accounting.upper_bounds.haystack_bytes == haystack.len()
                            && accounting.upper_bounds.scratch_bytes == 0
                            && accounting.upper_bounds.peak_bytes
                                >= accounting.upper_bounds.persistent_bytes
                            && accounting.actual.prefix_candidates
                                <= accounting.upper_bounds.prefix_candidates
                            && accounting.actual.class_bytes <= accounting.upper_bounds.class_bytes
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && accounting.actual.count <= accounting.upper_bounds.count
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.matches == result.matches
                            && accounting.actual.count
                                == u64::try_from(result.matches).unwrap_or(u64::MAX)
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::LazyDelimitedRepeat(accounting) => {
                        accounting.identity.plan_id == LAZY_DELIMITED_REPEAT_PLAN_ID
                            && accounting.identity.operation_id
                                == LAZY_DELIMITED_REPEAT_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.repeat_count > 0
                            && accounting.identity.delimiter != accounting.identity.barrier
                            && accounting.identity.lazy
                            && accounting.identity.exact_repeat
                            && accounting.identity.non_overlapping
                            && !accounting.identity.unicode
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.upper_bounds.scratch_bytes == 0
                            && accounting.upper_bounds.peak_bytes
                                >= accounting.upper_bounds.persistent_bytes
                            && accounting.actual.source_reads
                                <= accounting.upper_bounds.source_reads
                            && accounting.actual.work <= accounting.upper_bounds.work
                            && accounting.actual.finder_calls
                                <= accounting.upper_bounds.finder_calls
                            && accounting.actual.finder_service_bytes
                                <= accounting.upper_bounds.finder_service_bytes
                            && accounting.actual.pair_candidates
                                <= accounting.upper_bounds.pair_candidates
                            && accounting.actual.event_scan_bytes
                                <= accounting.upper_bounds.event_scan_bytes
                            && accounting.actual.event_visits
                                <= accounting.upper_bounds.event_visits
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && u64::try_from(accounting.actual.matches)
                                .is_ok_and(|count| count <= accounting.upper_bounds.count)
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::K0CasefoldPrefixClass(accounting) => {
                        accounting.identity.plan_id == K0_CASEFOLD_PREFIX_CLASS_PLAN_ID
                            && accounting.identity.operation_id
                                == K0_CASEFOLD_PREFIX_CLASS_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.alternatives == 2
                            && accounting.identity.candidate_streams == 8
                            && accounting.identity.anchor_bytes == 2
                            && accounting.identity.unbordered_anchor
                            && !accounting.identity.unicode
                            && accounting.identity.case_insensitive
                            && accounting.identity.greedy
                            && accounting.identity.non_overlapping
                            && accounting
                                .identity
                                .prefix_lengths
                                .iter()
                                .all(|&length| (2..=8).contains(&length))
                            && accounting
                                .identity
                                .class_words
                                .iter()
                                .all(|words| *words != [0; 4])
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.upper_bounds.scratch_bytes == 0
                            && accounting.upper_bounds.persistent_bytes == 0
                            && accounting.upper_bounds.peak_bytes == 0
                            && accounting.actual.source_reads
                                <= accounting.upper_bounds.source_reads
                            && accounting.actual.work <= accounting.upper_bounds.work
                            && accounting.actual.candidate_starts
                                <= accounting.upper_bounds.candidate_starts
                            && accounting.actual.prefix_byte_checks
                                <= accounting.upper_bounds.prefix_byte_checks
                            && accounting.actual.class_byte_checks
                                <= accounting.upper_bounds.class_byte_checks
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::GreedyClassLiteralTail(accounting) => {
                        let class_probes = accounting
                            .actual
                            .prefix_class_probes
                            .checked_add(accounting.actual.tail_class_probes);
                        let topology_authenticated = match accounting.identity.topology {
                            GreedyClassLiteralTailTopology::ClassLiteralTail => {
                                accounting.identity.literal_bytes > 0
                                    && accounting.identity.greedy_tail
                            }
                            GreedyClassLiteralTailTopology::NestedPositiveClassTerminal => {
                                let prefix = accounting.identity.prefix_class_words;
                                let terminal = accounting.identity.tail_class_words;
                                accounting.identity.literal_bytes == 0
                                    && !accounting.identity.greedy_tail
                                    && prefix[0] & terminal[0] == 0
                                    && prefix[1] & terminal[1] == 0
                                    && prefix[2] & terminal[2] == 0
                                    && prefix[3] & terminal[3] == 0
                            }
                        };
                        accounting.identity.plan_id == GREEDY_CLASS_LITERAL_TAIL_PLAN_ID
                            && accounting.identity.operation_id
                                == GREEDY_CLASS_LITERAL_TAIL_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.prefix_class_ranges > 0
                            && accounting.identity.tail_class_ranges > 0
                            && topology_authenticated
                            && accounting.identity.greedy_prefix
                            && accounting.identity.non_overlapping
                            && !accounting.identity.unicode
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.upper_bounds.scratch_bytes == 0
                            && accounting.upper_bounds.peak_bytes
                                >= accounting.upper_bounds.persistent_bytes
                            && accounting.actual.source_reads
                                <= accounting.upper_bounds.source_reads
                            && accounting.actual.work <= accounting.upper_bounds.work
                            && accounting.actual.finder_calls
                                <= accounting.upper_bounds.finder_calls
                            && accounting.actual.finder_service_bytes
                                <= accounting.upper_bounds.finder_service_bytes
                            && class_probes.is_some_and(|probes| {
                                probes <= accounting.upper_bounds.class_probes
                            })
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && u64::try_from(accounting.actual.matches)
                                .is_ok_and(|count| count <= accounting.upper_bounds.count)
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::GreedyDelimitedCorridor(accounting) => {
                        accounting.identity.plan_id == GREEDY_DELIMITED_CORRIDOR_PLAN_ID
                            && accounting.identity.operation_id
                                == GREEDY_DELIMITED_CORRIDOR_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.left_literal_bytes > 0
                            && accounting.identity.right_literal_bytes > 0
                            && accounting.identity.greedy
                            && accounting.identity.symmetric
                            && accounting.identity.non_overlapping
                            && !accounting.identity.unicode
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.upper_bounds.scratch_allocations <= 4
                            && accounting
                                .upper_bounds
                                .persistent_bytes
                                .checked_add(accounting.upper_bounds.scratch_bytes)
                                .is_some_and(|bytes| accounting.upper_bounds.peak_bytes >= bytes)
                            && accounting.actual.source_reads
                                <= accounting.upper_bounds.source_reads
                            && accounting.actual.work <= accounting.upper_bounds.work
                            && accounting.actual.finder_calls
                                <= accounting.upper_bounds.finder_calls
                            && accounting.actual.finder_service_bytes
                                <= accounting.upper_bounds.finder_service_bytes
                            && accounting.actual.classification_bytes
                                <= accounting.upper_bounds.classification_bytes
                            && accounting.actual.anchor_events
                                <= accounting.upper_bounds.anchor_events
                            && accounting.actual.nonbarrier_regions
                                <= accounting.upper_bounds.region_events
                            && accounting.actual.forced_regions
                                <= accounting.upper_bounds.region_events
                            && accounting.actual.query_probes
                                <= accounting.upper_bounds.query_probes
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && u64::try_from(accounting.actual.matches)
                                .is_ok_and(|count| count <= accounting.upper_bounds.count)
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                    PortableSpanVisitAccounting::UnicodeTokenPhrase(accounting) => {
                        accounting.identity.plan_id == UNICODE_TOKEN_PHRASE_PLAN_ID
                            && accounting.identity.operation_id
                                == UNICODE_TOKEN_PHRASE_SPAN_VISIT_OPERATION_ID
                            && accounting.identity.operation_id == self.runtime_implementation_id
                            && accounting.identity.literal_bytes > 0
                            && accounting.identity.unicode
                            && accounting.identity.greedy
                            && accounting.identity.complete_word_boundaries
                            && accounting.identity.non_overlapping
                            && accounting.upper_bounds.input_bytes == haystack.len()
                            && accounting.upper_bounds.scratch_bytes == 0
                            && accounting.upper_bounds.persistent_bytes == 0
                            && accounting.upper_bounds.peak_bytes == 0
                            && accounting.actual.source_reads
                                <= accounting.upper_bounds.source_reads
                            && accounting.actual.work <= accounting.upper_bounds.work
                            && accounting.actual.finder_calls
                                <= accounting.upper_bounds.finder_calls
                            && accounting.actual.anchor_candidates
                                <= accounting.upper_bounds.anchor_candidates
                            && accounting.actual.decode_attempts
                                <= accounting.upper_bounds.decode_attempts
                            && accounting.actual.matches <= accounting.upper_bounds.match_events
                            && u64::try_from(accounting.actual.matches)
                                .is_ok_and(|count| count <= accounting.upper_bounds.count)
                            && accounting.actual.span_sum <= accounting.upper_bounds.span_sum
                            && accounting.actual.scratch_bytes == 0
                            && accounting.actual.matches == result.matches
                            && accounting.actual.span_sum == result.span_sum
                    }
                };
                if !accounting_authenticated
                    || matches != reported_matches
                    || sum != result.span_sum
                {
                    return Err(CompareError::new(
                        "FRE portable complete-spans visitor failed identity/accounting authentication",
                    ));
                }
                return Ok(sum);
            }
            Ok(None) => {
                if reducer.matches != 0 || reducer.sum != 0 || reducer.failure.is_some() {
                    return Err(CompareError::new(
                        "FRE portable complete-spans ineligible visitor invoked a callback",
                    ));
                }
            }
            Err(error) => {
                if reducer.matches != 0 || reducer.sum != 0 || reducer.failure.is_some() {
                    return Err(CompareError::new(
                        "FRE portable complete-spans visitor invoked a callback before refusal",
                    ));
                }
                return Err(CompareError::new(format!(
                    "FRE portable complete-spans direct traversal failed: {error}"
                )));
            }
        }
        let mut matches = 0_u64;
        let mut sum = 0_u64;
        for result in search.find_iter_value(haystack, self.limits) {
            let matched = result.map_err(|error| {
                CompareError::new(format!(
                    "FRE portable complete-spans iteration failed: {error}"
                ))
            })?;
            matches = matches.checked_add(1).ok_or_else(|| {
                CompareError::new("FRE portable complete-spans match count overflow")
            })?;
            if matches > self.reducer_steps {
                return Err(CompareError::new(format!(
                    "FRE portable complete-spans requires {matches} reducer events, limit is {}",
                    self.reducer_steps
                )));
            }
            let start = matched.start();
            let end = matched.end();
            let width = end.checked_sub(start).ok_or_else(|| {
                CompareError::new(
                    "FRE portable complete-spans result contained reversed match endpoints",
                )
            })?;
            let width = u64::try_from(width).map_err(|_| {
                CompareError::new("FRE portable complete-spans match width does not fit u64")
            })?;
            sum = sum.checked_add(width).ok_or_else(|| {
                CompareError::new("FRE portable complete-spans byte sum overflow")
            })?;
        }
        Ok(sum)
    }
}

/// Build the exact single-pattern matcher used by the authenticated
/// current-FRE Rebar complete-span lifecycle.
///
/// # Errors
///
/// Returns an error for portable construction refusal or an impossible
/// source/profile/report identity mismatch.
pub fn current_fre_rebar_complete_spans_regex(
    pattern: impl Into<String>,
    unicode: bool,
    case_insensitive: bool,
) -> Result<CurrentFreCompleteSpansRegex, CompareError> {
    let pattern = pattern.into();
    let mut profile = rebar_profile();
    profile.options.unicode = unicode;
    profile.options.case_insensitive = case_insensitive;
    let expected_profile = CompatibilityProfile::RustBytes(profile.clone());
    let regex = PortableBuilder::new(pattern.clone())
        .profile(profile)
        .limits(rebar_complete_spans_portable_build_limits())
        .build()
        .map_err(|error| {
            CompareError::new(format!(
                "FRE portable complete-spans lifecycle build failed: {error}"
            ))
        })?;
    if regex.as_str() != pattern
        || regex.profile() != &expected_profile
        || regex.build_report().profile != expected_profile
    {
        return Err(CompareError::new(
            "FRE portable complete-spans source/profile/report identity mismatch",
        ));
    }
    if matches!(
        regex.build_report().plan,
        PlanKind::K0 | PlanKind::ReverseInner
    ) {
        match current_fre_rebar_aggregate_builder(pattern, unicode, case_insensitive)
            .build_span_visitor()
        {
            Ok(aggregate)
                if matches!(
                    aggregate.build_report().plan,
                    AggregatePlanKind::FixedAbsoluteDomain
                        | AggregatePlanKind::LiteralAssertions
                        | AggregatePlanKind::BlockingDelimiter
                        | AggregatePlanKind::TokenPhrase
                        | AggregatePlanKind::ReverseInner
                        | AggregatePlanKind::DelimiterFieldSpans
                        | AggregatePlanKind::BoundedLiteralPair
                        | AggregatePlanKind::BoundedContext
                        | AggregatePlanKind::GuardedAsciiWordDictionary
                        | AggregatePlanKind::GuardedUnicodeWordLiteralSet
                ) || sparse_finite_complete_spans_identity_matches(
                    aggregate.build_report(),
                    unicode,
                    case_insensitive,
                ) || dense_finite_complete_spans_identity_matches(
                    aggregate.build_report(),
                    unicode,
                    case_insensitive,
                ) || url_complete_spans_identity_matches(aggregate.build_report()) =>
            {
                require_rebar_complete_spans_identity(
                    aggregate.build_report(),
                    unicode,
                    case_insensitive,
                )
                .map_err(|error| CompareError::new(error.message))?;
                let (plan_prefix, runtime_implementation_id) = if aggregate.build_report().plan
                    == AggregatePlanKind::FixedAbsoluteDomain
                {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_FIXED_ABSOLUTE_PLAN,
                        fre::FIXED_ABSOLUTE_DOMAIN_SPANS_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::LiteralAssertions {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_LITERAL_ASSERTIONS_PLAN,
                        LITERAL_ASSERTIONS_SPAN_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::BlockingDelimiter {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_BLOCKING_DELIMITER_PLAN,
                        fre::BLOCKING_DELIMITER_SPAN_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::TokenPhrase {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_TOKEN_PHRASE_PLAN,
                        TOKEN_PHRASE_SPAN_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::ReverseInner {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_REVERSE_INNER_PLAN,
                        REVERSE_INNER_SPAN_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::DelimiterFieldSpans {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_DELIMITER_FIELD_PLAN,
                        DELIMITER_FIELD_SPANS_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::BoundedLiteralPair {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_BOUNDED_LITERAL_PAIR_PLAN,
                        fre::BOUNDED_LITERAL_PAIR_SPAN_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan == AggregatePlanKind::BoundedContext {
                    let AggregatePlanIdentity::BoundedContext(identity) =
                        aggregate.build_report().plan_identity
                    else {
                        return Err(CompareError::new(
                            "FRE bounded-affix complete-spans identity mismatch",
                        ));
                    };
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_BOUNDED_AFFIX_PLAN,
                        identity.kernel.operation_id,
                    )
                } else if aggregate.build_report().plan
                    == AggregatePlanKind::GuardedAsciiWordDictionary
                {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_GUARDED_ASCII_WORD_PLAN,
                        guarded_ascii_word::SPAN_VISIT_OPERATION_ID,
                    )
                } else if aggregate.build_report().plan
                    == AggregatePlanKind::GuardedUnicodeWordLiteralSet
                {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_GUARDED_UNICODE_WORD_PLAN,
                        fre::guarded_unicode_word::SPAN_VISIT_OPERATION_ID,
                    )
                } else if dense_finite_complete_spans_identity_matches(
                    aggregate.build_report(),
                    unicode,
                    case_insensitive,
                ) {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_DENSE_FINITE_PLAN,
                        fre::ORDERED_LITERAL_SPANS_ALGORITHM_ID,
                    )
                } else if url_complete_spans_identity_matches(aggregate.build_report()) {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_URL_PLAN,
                        fre::URL_AGGREGATE_SPAN_VISIT_OPERATION_ID,
                    )
                } else {
                    (
                        CURRENT_FRE_REBAR_COMPLETE_SPANS_SPARSE_FINITE_PLAN,
                        fre::SPARSE_ORDERED_LITERAL_TRACE_ALGORITHM_ID,
                    )
                };
                let plan = format!("{plan_prefix}-{runtime_implementation_id}");
                return Ok(CurrentFreCompleteSpansRegex {
                    inner: CurrentFreCompleteSpansRegexInner::Aggregate(aggregate),
                    plan,
                    runtime_implementation_id,
                });
            }
            Ok(_) | Err(_) => {}
        }
    }
    let selected_plan_kind = regex.build_report().plan;
    let selected_plan = portable_plan_kind_label(selected_plan_kind);
    let span_visit_runtime_implementation_id =
        match regex.fixed_predicate_span_visit_operation_identity() {
            Some(identity)
                if identity.width >= 3
                    && identity.reducer == FixedPredicateWord64Reducer::TwoByteAnchor =>
            {
                Some(identity.operation_id)
            }
            Some(_) => None,
            None => regex.span_visit_runtime_implementation_id(),
        };
    let (plan_prefix, runtime_implementation_id) = span_visit_runtime_implementation_id
        .map_or_else(
            || {
                (
                    CURRENT_FRE_REBAR_COMPLETE_SPANS_PLAN_PREFIX,
                    regex.runtime_implementation_id(),
                )
            },
            |operation_id| {
                (
                    CURRENT_FRE_REBAR_COMPLETE_SPANS_PORTABLE_VISIT_PLAN_PREFIX,
                    operation_id,
                )
            },
        );
    let plan = format!("{plan_prefix}-{selected_plan}-{runtime_implementation_id}");
    Ok(CurrentFreCompleteSpansRegex {
        inner: CurrentFreCompleteSpansRegexInner::Portable(regex),
        plan,
        runtime_implementation_id,
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CurrentFreAggregateOperationModel {
    Count,
    SpanSum,
}

impl CurrentFreAggregateOperationModel {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Count => "count",
            Self::SpanSum => "count-spans",
        }
    }
}

/// One already-built aggregate artifact for first/steady public operations.
#[derive(Debug)]
pub struct CurrentFreAggregateOperationLifecycle {
    model: CurrentFreAggregateOperationModel,
    plan: &'static str,
    haystack_len: usize,
    inner: CurrentFreAggregateOperationInner,
}

#[derive(Debug)]
enum CurrentFreAggregateOperationInner {
    CountAsciiFolded(Box<ascii_folded_literal::AsciiFoldedLiteralCount>),
    CountCanonical(canonical_case_fold::CanonicalCountLifecycle),
    CountFixedUnicodeSequence(Box<fixed_unicode_sequence::FixedUnicodeSequenceCount>),
    CountTerminalByteFrontier(Box<terminal_byte_frontier::TerminalByteFrontierCount>),
    CountFolded(
        UnicodeFoldedLiteralCountRegex,
        UnicodeFoldedLiteralRunLimits,
    ),
    CountSingle(AggregateCountRegex, AggregateRunLimits),
    CountSinglePreparedWidthOneShiftAnd(
        AggregateCountRegex,
        AggregateRunLimits,
        AggregateFixedPredicateWidthOneShiftAndCountAdmission,
    ),
    CountSinglePreparedUnicodeScalar(
        AggregateCountRegex,
        AggregateRunLimits,
        AggregateUnicodeScalarCountAdmission,
    ),
    CountSingleDense(
        AggregateCountRegex,
        AggregateRunLimits,
        RefCell<AggregateCountWorkspace>,
    ),
    CountMany(AggregateManyCountRegex, AggregateManyRunLimits),
    CompleteMatchCountSingle(AggregateSpansRegex, AggregateRunLimits),
    CompleteMatchCountMany(AggregateManySpansRegex, AggregateManyRunLimits),
    #[cfg(test)]
    SpanSumSingleDense(
        AggregateSpanSumRegex,
        AggregateRunLimits,
        RefCell<AggregateSpanSumWorkspace>,
    ),
    CompleteSpansSingle(AggregateSpanVisitorRegex, AggregateRunLimits),
    StreamingSpansMany(
        AggregateManySpansRegex,
        AggregateManyRunLimits,
        RefCell<AggregateManySpansWorkspace>,
    ),
}

