fn rebar_sum_match_bounds(
    matches: impl IntoIterator<Item = fre::Match>,
) -> Result<u64, &'static str> {
    matches.into_iter().try_fold(0_u64, |sum, matched| {
        let width = matched
            .end()
            .checked_sub(matched.start())
            .ok_or("FRE complete-spans result contained reversed match endpoints")?;
        let width =
            u64::try_from(width).map_err(|_| "FRE complete-spans match width does not fit u64")?;
        sum.checked_add(width)
            .ok_or("FRE complete-spans byte sum overflow")
    })
}

fn rebar_count_match_bounds(
    matches: impl IntoIterator<Item = fre::Match>,
) -> Result<u64, &'static str> {
    matches.into_iter().try_fold(0_u64, |count, matched| {
        if matched.start() > matched.end() {
            return Err("FRE complete-match result contained reversed endpoints");
        }
        count
            .checked_add(1)
            .ok_or("FRE complete-match count overflow")
    })
}

fn rebar_streamed_single_span_accounting_closes(
    regex: &AggregateSpanVisitorRegex,
    haystack_len: usize,
    limits: &AggregateRunLimits,
    visited: &fre::AggregateSpanVisit,
) -> bool {
    let AggregatePlanIdentity::Continuation(identity) = regex.build_report().plan_identity else {
        return false;
    };
    let fre::AggregateExecutionDetails::Continuation {
        certificate,
        accounting,
    } = visited.report().details()
    else {
        return false;
    };
    let Some(sequential_bytes) = accounting
        .sequential_bytes_written
        .checked_add(accounting.sequential_bytes_read)
    else {
        return false;
    };
    let generic_complete_bounds_route = matches!(
        certificate.physical_route,
        fre::AggregateOperationPhysicalRoute::DenseRows
            | fre::AggregateOperationPhysicalRoute::RequiredSuffixRows
            | fre::AggregateOperationPhysicalRoute::TerminalFrontierRows
            | fre::AggregateOperationPhysicalRoute::CachedFrontier
    );
    let generic_fallback = matches!(
        certificate.prepublication_fallback,
        fre::AggregateOperationPrepublicationFallback::None
            | fre::AggregateOperationPrepublicationFallback::TerminalFrontierThenDense
            | fre::AggregateOperationPrepublicationFallback::DenseThenRequiredSuffix
            | fre::AggregateOperationPrepublicationFallback::DenseThenCachedFrontier
    );

    certificate.regex_plan_id == identity.program
        && certificate.authenticates_limits(limits.continuation)
        && certificate.strategy == AggregateStrategy::ReverseSequentialRows
        && certificate.operation == fre::AggregateOperationAttemptKind::SpanVisit
        && generic_complete_bounds_route
        && generic_fallback
        && certificate.algorithm_version == fre::AGGREGATE_CONTINUATION_ALGORITHM_VERSION
        && certificate.accounting_version == fre::AGGREGATE_CONTINUATION_ACCOUNTING_VERSION
        && certificate.range == (0..haystack_len)
        && certificate.actual_allocations <= certificate.prospective_allocations
        && certificate.output_bytes == 0
        && sequential_bytes <= certificate.sequential_bytes_bound
        && accounting.random_access_peak_bytes <= certificate.random_access_bytes
        && accounting.scratch_peak_bytes <= certificate.scratch_bytes
        && accounting.log_bytes <= certificate.log_bytes
        && accounting.output_bytes == 0
        && accounting.peak_bytes <= certificate.peak_bytes
        && accounting.work <= certificate.work_bound
        && accounting.successful_paths <= certificate.match_events
        && accounting.emitted_matches == visited.len()
        && visited.len() <= certificate.output_matches
        && visited.span_sum() <= certificate.span_sum
}

fn rebar_sum_streamed_single_match_bounds(
    regex: &AggregateSpanVisitorRegex,
    haystack: &[u8],
    limits: &AggregateRunLimits,
) -> Result<u64, CompareError> {
    let max_matches = u64::try_from(limits.continuation.max_output_matches)
        .map_err(|_| CompareError::new("FRE complete-spans output-match limit does not fit u64"))?;
    let mut reducer = CompleteSpansReducer::new(max_matches);
    let visited = regex
        .visit_spans(haystack, limits, |matched| reducer.observe(matched))
        .map_err(aggregate_lifecycle_complete_spans_error)?;
    let (matches, sum) = reducer.finish()?;
    let reported_matches = u64::try_from(visited.len())
        .map_err(|_| CompareError::new("FRE streamed single-span match count does not fit u64"))?;
    let reported_sum = u64::try_from(visited.span_sum())
        .map_err(|_| CompareError::new("FRE streamed single-span byte sum does not fit u64"))?;
    if !rebar_streamed_single_span_accounting_closes(regex, haystack.len(), limits, &visited)
        || matches != reported_matches
        || sum != reported_sum
    {
        return Err(CompareError::new(
            "Rebar streamed single-span reduction diverged from its authenticated receipt",
        ));
    }
    Ok(sum)
}

#[derive(Debug)]
enum RebarStreamedManySpanError {
    Execution(fre::AggregateManyExecutionError),
    Reduction(CompareError),
}

fn rebar_streamed_many_span_accounting_closes(
    regex: &AggregateManySpansRegex,
    haystack_len: usize,
    limits: AggregateManyRunLimits,
    visited: &fre::AggregateManySpanVisit,
) -> bool {
    let AggregateManyPlanIdentity::Continuation(plan_id) = regex.build_report().plan_identity
    else {
        return false;
    };
    if let fre::AggregateManyExecutionDetails::ContinuationSweep {
        plan_id: executed_plan_id,
        range,
        limits: executed_limits,
        matches,
        span_sum,
    } = visited.details()
    {
        return regex.build_report().ascii_word_shadow.is_some()
            && *executed_plan_id == plan_id
            && range.start == 0
            && range.end == haystack_len
            && *executed_limits == limits.continuation
            && *matches == visited.len()
            && *span_sum == visited.span_sum()
            && *matches <= limits.continuation.max_output_matches
            && *span_sum <= limits.continuation.max_span_sum;
    }
    let fre::AggregateManyExecutionDetails::Continuation {
        certificate,
        accounting,
    } = visited.details()
    else {
        return false;
    };
    let Some(sequential_bytes) = accounting
        .sequential_bytes_written
        .checked_add(accounting.sequential_bytes_read)
    else {
        return false;
    };
    let physical_route_is_complete_bounds = matches!(
        certificate.physical_route,
        fre::AggregateOperationPhysicalRoute::DenseRows
            | fre::AggregateOperationPhysicalRoute::RequiredSuffixRows
            | fre::AggregateOperationPhysicalRoute::TerminalFrontierRows
            | fre::AggregateOperationPhysicalRoute::CachedFrontier
    );
    let prepublication_fallback_is_generic = matches!(
        certificate.prepublication_fallback,
        fre::AggregateOperationPrepublicationFallback::None
            | fre::AggregateOperationPrepublicationFallback::TerminalFrontierThenDense
            | fre::AggregateOperationPrepublicationFallback::DenseThenRequiredSuffix
            | fre::AggregateOperationPrepublicationFallback::DenseThenCachedFrontier
    );

    certificate.regex_plan_id == plan_id
        && certificate.authenticates_limits(limits.continuation)
        && certificate.strategy == AggregateStrategy::ReverseSequentialRows
        && certificate.operation == fre::AggregateOperationAttemptKind::SpanVisit
        && physical_route_is_complete_bounds
        && certificate.algorithm_version == fre::AGGREGATE_CONTINUATION_ALGORITHM_VERSION
        && certificate.accounting_version == fre::AGGREGATE_CONTINUATION_ACCOUNTING_VERSION
        && prepublication_fallback_is_generic
        && certificate.range == (0..haystack_len)
        && certificate.actual_allocations <= certificate.prospective_allocations
        && certificate.output_bytes == 0
        && sequential_bytes <= certificate.sequential_bytes_bound
        && accounting.random_access_peak_bytes <= certificate.random_access_bytes
        && accounting.scratch_peak_bytes <= certificate.scratch_bytes
        && accounting.log_bytes <= certificate.log_bytes
        && accounting.output_bytes == 0
        && accounting.peak_bytes <= certificate.peak_bytes
        && accounting.work <= certificate.work_bound
        && accounting.successful_paths <= certificate.match_events
        && accounting.emitted_matches == visited.len()
        && visited.len() <= certificate.output_matches
        && visited.span_sum() <= certificate.span_sum
}

fn rebar_sum_streamed_many_match_bounds(
    regex: &AggregateManySpansRegex,
    haystack: &[u8],
    limits: AggregateManyRunLimits,
) -> Result<u64, RebarStreamedManySpanError> {
    let mut workspace = AggregateManySpansWorkspace::new();
    rebar_sum_streamed_many_match_bounds_with_workspace(regex, haystack, limits, &mut workspace)
}

fn rebar_sum_streamed_many_match_bounds_with_workspace(
    regex: &AggregateManySpansRegex,
    haystack: &[u8],
    limits: AggregateManyRunLimits,
    workspace: &mut AggregateManySpansWorkspace,
) -> Result<u64, RebarStreamedManySpanError> {
    let max_matches = u64::try_from(limits.continuation.max_output_matches).map_err(|_| {
        RebarStreamedManySpanError::Reduction(CompareError::new(
            "FRE complete-spans output-match limit does not fit u64",
        ))
    })?;
    let mut reducer = CompleteSpansReducer::new(max_matches);
    let visited = regex
        .visit_spans_with_workspace(haystack, limits, workspace, |matched| {
            reducer.observe(matched);
        })
        .map_err(RebarStreamedManySpanError::Execution)?;
    let (matches, sum) = reducer
        .finish()
        .map_err(RebarStreamedManySpanError::Reduction)?;
    let reported_matches = u64::try_from(visited.len()).map_err(|_| {
        RebarStreamedManySpanError::Reduction(CompareError::new(
            "FRE streamed multi-span match count does not fit u64",
        ))
    })?;
    let reported_sum = u64::try_from(visited.span_sum()).map_err(|_| {
        RebarStreamedManySpanError::Reduction(CompareError::new(
            "FRE streamed multi-span byte sum does not fit u64",
        ))
    })?;
    if !rebar_streamed_many_span_accounting_closes(regex, haystack.len(), limits, &visited)
        || matches != reported_matches
        || sum != reported_sum
    {
        return Err(RebarStreamedManySpanError::Reduction(CompareError::new(
            "Rebar streamed multi-span reduction diverged from its authenticated receipt",
        )));
    }
    Ok(sum)
}

/// Value produced by the reusable aggregate operation shell together with an
/// optional immutable continuation counter receipt.
///
/// This result intentionally carries no benchmark name, fixture identity,
/// expected value, result hash, or timing observation. Callers may attach
/// attribution only after this shell has finished its structurally selected
/// operation.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum CurrentFreAggregateCounterReceiptStatus {
    /// The single-pattern continuation route published a sealed hot-path
    /// certificate and structural counter projection.
    Continuation(Box<AggregateOperationHotCounterReceipt>),
    /// A single-pattern direct route completed without a continuation receipt.
    DirectSelectedPlan,
    /// The retained value operation may use the persistent continuation
    /// sweep, but this out-of-band diagnostic ran the incumbent
    /// counter-producing path. Its projection is not physical evidence for a
    /// sweep execution.
    IncumbentProjectionForUnreceiptedSweep,
    /// A multi-pattern route completed before its native counter receipt is
    /// implemented. This is deliberately not represented as zero counters.
    MissingMultiPlanReceipt,
}

/// Value produced by the reusable aggregate operation shell together with its
/// explicit native counter-receipt status.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CurrentFreAggregateOperationCounterResult {
    value: u64,
    receipt_status: CurrentFreAggregateCounterReceiptStatus,
}

impl CurrentFreAggregateOperationCounterResult {
    /// Value-only reducer output.
    #[must_use]
    pub const fn value(&self) -> u64 {
        self.value
    }

    /// Optional immutable structural receipt from a continuation operation.
    #[must_use]
    pub const fn continuation_receipt(&self) -> Option<&AggregateOperationHotCounterReceipt> {
        match &self.receipt_status {
            CurrentFreAggregateCounterReceiptStatus::Continuation(receipt) => Some(receipt),
            CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan
            | CurrentFreAggregateCounterReceiptStatus::IncumbentProjectionForUnreceiptedSweep
            | CurrentFreAggregateCounterReceiptStatus::MissingMultiPlanReceipt => None,
        }
    }

    /// Exact native evidence status after the operation completed.
    #[must_use]
    pub const fn receipt_status(&self) -> &CurrentFreAggregateCounterReceiptStatus {
        &self.receipt_status
    }
}

impl CurrentFreAggregateOperationLifecycle {
    /// Exact Rebar model retained by this artifact.
    #[must_use]
    pub const fn model(&self) -> &'static str {
        self.model.as_str()
    }

    /// Exact authenticated construction-selected plan label.
    #[must_use]
    pub const fn plan(&self) -> &'static str {
        self.plan
    }

    /// Execute one complete public operation on the same retained artifact.
    /// Calling this once is the first-operation boundary; an untimed call then
    /// another call is the steady-operation boundary.
    ///
    /// # Errors
    ///
    /// Returns an error for input-length mismatch or retained-plan refusal.
    pub fn execute(&self, haystack: &[u8]) -> Result<u64, CompareError> {
        if haystack.len() != self.haystack_len {
            return Err(aggregate_lifecycle_input_length_error(
                haystack.len(),
                self.haystack_len,
            ));
        }
        match &self.inner {
            CurrentFreAggregateOperationInner::CountAsciiFolded(plan) => plan
                .count(haystack)
                .map_err(|error| CompareError::new(error.message)),
            CurrentFreAggregateOperationInner::CountCanonical(lifecycle) => lifecycle
                .execute(haystack)
                .map_err(aggregate_lifecycle_canonical_count_error),
            CurrentFreAggregateOperationInner::CountFixedUnicodeSequence(plan) => {
                plan.count(haystack).map_err(|error| {
                    CompareError::new(format!("FRE fixed Unicode sequence Count: {error}"))
                })
            }
            CurrentFreAggregateOperationInner::CountTerminalByteFrontier(plan) => {
                plan.count(haystack).map_err(|error| {
                    CompareError::new(format!(
                        "FRE terminal-byte frontier Count: {}",
                        error.message
                    ))
                })
            }
            CurrentFreAggregateOperationInner::CountFolded(regex, limits) => regex
                .execute(haystack, *limits)
                .map(|result| result.value)
                .map_err(aggregate_lifecycle_folded_count_error),
            CurrentFreAggregateOperationInner::CountSingle(regex, limits) => regex
                .count_value(haystack, limits)
                .map_err(aggregate_lifecycle_count_error),
            CurrentFreAggregateOperationInner::CountSinglePreparedWidthOneShiftAnd(
                regex,
                _,
                admission,
            ) => regex
                .count_value_prepared_fixed_predicate_width_one_shift_and(haystack, admission)
                .map_err(aggregate_lifecycle_count_error),
            CurrentFreAggregateOperationInner::CountSinglePreparedUnicodeScalar(
                regex,
                _,
                admission,
            ) => regex
                .count_value_prepared_unicode_scalar(haystack, admission)
                .map_err(aggregate_lifecycle_count_error),
            CurrentFreAggregateOperationInner::CountSingleDense(regex, limits, workspace) => {
                let mut workspace = workspace.borrow_mut();
                regex
                    .count_value_with_workspace(haystack, limits, &mut workspace)
                    .map_err(aggregate_lifecycle_count_error)
            }
            CurrentFreAggregateOperationInner::CountMany(regex, limits) => regex
                .count_value(haystack, *limits)
                .map_err(aggregate_lifecycle_count_many_error),
            CurrentFreAggregateOperationInner::CompleteMatchCountSingle(regex, limits) => regex
                .spans(haystack, limits)
                .map_err(aggregate_lifecycle_complete_spans_error)
                .and_then(|spans| rebar_count_match_bounds(&spans).map_err(CompareError::new)),
            CurrentFreAggregateOperationInner::CompleteMatchCountMany(regex, limits) => regex
                .spans(haystack, *limits)
                .map_err(aggregate_lifecycle_complete_spans_many_error)
                .and_then(|spans| rebar_count_match_bounds(&spans).map_err(CompareError::new)),
            #[cfg(test)]
            CurrentFreAggregateOperationInner::SpanSumSingleDense(regex, limits, workspace) => {
                let mut workspace = workspace.borrow_mut();
                regex
                    .span_sum_value_with_workspace(haystack, limits, &mut workspace)
                    .map_err(aggregate_lifecycle_span_sum_error)
            }
            CurrentFreAggregateOperationInner::CompleteSpansSingle(regex, limits) => {
                rebar_sum_streamed_single_match_bounds(regex, haystack, limits)
            }
            CurrentFreAggregateOperationInner::StreamingSpansMany(regex, limits, workspace) => {
                let mut workspace = workspace.borrow_mut();
                rebar_sum_streamed_many_match_bounds_with_workspace(
                    regex,
                    haystack,
                    *limits,
                    &mut workspace,
                )
                .map_err(|error| match error {
                    RebarStreamedManySpanError::Execution(error) => {
                        aggregate_lifecycle_complete_spans_many_error(error)
                    }
                    RebarStreamedManySpanError::Reduction(error) => error,
                })
            }
        }
    }

    /// Execute an out-of-band value operation and publish its native evidence
    /// status.
    ///
    /// This diagnostic is not called by the benchmark runner. It reuses the
    /// same prebuilt artifact and exact derived limits, and receives no
    /// benchmark or fixture metadata. When [`Self::execute`] can select the
    /// persistent continuation sweep, this method deliberately invokes the
    /// incumbent counter-producing path and reports
    /// [`CurrentFreAggregateCounterReceiptStatus::IncumbentProjectionForUnreceiptedSweep`].
    /// That projection is not a receipt for the sweep-executed operation.
    ///
    /// # Errors
    ///
    /// Returns the same input-length and retained-plan errors as
    /// [`Self::execute`].
    pub fn execute_with_counters(
        &self,
        haystack: &[u8],
    ) -> Result<CurrentFreAggregateOperationCounterResult, CompareError> {
        if haystack.len() != self.haystack_len {
            return Err(CompareError::new(format!(
                "aggregate operation haystack length {} differs from prepared {}",
                haystack.len(),
                self.haystack_len
            )));
        }
        match &self.inner {
            CurrentFreAggregateOperationInner::CountAsciiFolded(plan) => plan
                .count(haystack)
                .map(|value| CurrentFreAggregateOperationCounterResult {
                    value,
                    receipt_status: CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                })
                .map_err(|error| CompareError::new(error.message)),
            CurrentFreAggregateOperationInner::CountCanonical(lifecycle) => lifecycle
                .execute(haystack)
                .map(|value| CurrentFreAggregateOperationCounterResult {
                    value,
                    receipt_status: CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                })
                .map_err(|error| {
                    CompareError::new(format!(
                        "FRE canonical case-fold count lifecycle: {}",
                        error.message
                    ))
                }),
            CurrentFreAggregateOperationInner::CountFixedUnicodeSequence(plan) => plan
                .count(haystack)
                .map(|value| CurrentFreAggregateOperationCounterResult {
                    value,
                    receipt_status: CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                })
                .map_err(|error| {
                    CompareError::new(format!("FRE fixed Unicode sequence Count: {error}"))
                }),
            CurrentFreAggregateOperationInner::CountTerminalByteFrontier(plan) => plan
                .count(haystack)
                .map(|value| CurrentFreAggregateOperationCounterResult {
                    value,
                    receipt_status: CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                })
                .map_err(|error| {
                    CompareError::new(format!(
                        "FRE terminal-byte frontier Count: {}",
                        error.message
                    ))
                }),
            CurrentFreAggregateOperationInner::CountFolded(regex, limits) => regex
                .execute(haystack, *limits)
                .map(|result| CurrentFreAggregateOperationCounterResult {
                    value: result.value,
                    receipt_status: CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                })
                .map_err(|error| {
                    CompareError::new(format!("FRE folded-literal count lifecycle: {error}"))
                }),
            CurrentFreAggregateOperationInner::CountSingle(regex, limits) => regex
                .count_value_with_counters(haystack, limits)
                .map(|result| CurrentFreAggregateOperationCounterResult {
                    value: result.value(),
                    receipt_status: result.continuation_receipt().cloned().map_or(
                        CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                        |receipt| {
                            CurrentFreAggregateCounterReceiptStatus::Continuation(Box::new(receipt))
                        },
                    ),
                })
                .map_err(|error| {
                    let message = format!("FRE count lifecycle: {error}");
                    CompareError::new(aggregate_attempt_error(&error, message).message)
                }),
            CurrentFreAggregateOperationInner::CountSinglePreparedWidthOneShiftAnd(
                regex,
                limits,
                ..,
            ) => regex
                .count_value_with_counters(haystack, limits)
                .map(|result| CurrentFreAggregateOperationCounterResult {
                    value: result.value(),
                    receipt_status: result.continuation_receipt().cloned().map_or(
                        CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                        |receipt| {
                            CurrentFreAggregateCounterReceiptStatus::Continuation(Box::new(receipt))
                        },
                    ),
                })
                .map_err(|error| {
                    let message = format!("FRE count lifecycle: {error}");
                    CompareError::new(aggregate_attempt_error(&error, message).message)
                }),
            CurrentFreAggregateOperationInner::CountSinglePreparedUnicodeScalar(
                regex,
                limits,
                ..,
            ) => regex
                .count_value_with_counters(haystack, limits)
                .map(|result| CurrentFreAggregateOperationCounterResult {
                    value: result.value(),
                    receipt_status: result.continuation_receipt().cloned().map_or(
                        CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                        |receipt| {
                            CurrentFreAggregateCounterReceiptStatus::Continuation(Box::new(receipt))
                        },
                    ),
                })
                .map_err(|error| {
                    let message = format!("FRE count lifecycle: {error}");
                    CompareError::new(aggregate_attempt_error(&error, message).message)
                }),
            CurrentFreAggregateOperationInner::CountSingleDense(regex, limits, _) => {
                let projects_unreceipted_sweep = regex
                    .continuation_sweep_upper_bounds()
                    .map_err(|error| {
                        CompareError::new(format!(
                            "FRE count lifecycle continuation-sweep diagnostic preflight: {error}"
                        ))
                    })?
                    .is_some();
                regex
                    .count_value_with_counters(haystack, limits)
                    .map(|result| CurrentFreAggregateOperationCounterResult {
                        value: result.value(),
                        receipt_status: if projects_unreceipted_sweep {
                            CurrentFreAggregateCounterReceiptStatus::IncumbentProjectionForUnreceiptedSweep
                        } else {
                            result.continuation_receipt().cloned().map_or(
                                CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                                |receipt| {
                                    CurrentFreAggregateCounterReceiptStatus::Continuation(
                                        Box::new(receipt),
                                    )
                                },
                            )
                        },
                    })
                    .map_err(|error| {
                        let message = format!("FRE count lifecycle: {error}");
                        CompareError::new(aggregate_attempt_error(&error, message).message)
                    })
            }
            CurrentFreAggregateOperationInner::CountMany(regex, limits) => regex
                .count_value(haystack, *limits)
                .map(|value| CurrentFreAggregateOperationCounterResult {
                    value,
                    receipt_status:
                        CurrentFreAggregateCounterReceiptStatus::MissingMultiPlanReceipt,
                })
                .map_err(|error| CompareError::new(format!("FRE count-many lifecycle: {error}"))),
            CurrentFreAggregateOperationInner::CompleteMatchCountSingle(regex, limits) => regex
                .spans(haystack, limits)
                .map_err(aggregate_lifecycle_complete_spans_error)
                .and_then(|spans| {
                    rebar_count_match_bounds(&spans)
                        .map(|value| CurrentFreAggregateOperationCounterResult {
                            value,
                            receipt_status:
                                CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                        })
                        .map_err(CompareError::new)
                }),
            CurrentFreAggregateOperationInner::CompleteMatchCountMany(regex, limits) => regex
                .spans(haystack, *limits)
                .map_err(aggregate_lifecycle_complete_spans_many_error)
                .and_then(|spans| {
                    rebar_count_match_bounds(&spans)
                        .map(|value| CurrentFreAggregateOperationCounterResult {
                            value,
                            receipt_status:
                                CurrentFreAggregateCounterReceiptStatus::MissingMultiPlanReceipt,
                        })
                        .map_err(CompareError::new)
                }),
            #[cfg(test)]
            CurrentFreAggregateOperationInner::SpanSumSingleDense(regex, limits, _) => {
                let projects_unreceipted_sweep = regex
                    .continuation_sweep_upper_bounds()
                    .map_err(|error| {
                        CompareError::new(format!(
                            "FRE span-sum lifecycle continuation-sweep diagnostic preflight: {error}"
                        ))
                    })?
                    .is_some();
                regex
                    .span_sum_value_with_counters(haystack, limits)
                    .map(|result| CurrentFreAggregateOperationCounterResult {
                        value: result.value(),
                        receipt_status: if projects_unreceipted_sweep {
                            CurrentFreAggregateCounterReceiptStatus::IncumbentProjectionForUnreceiptedSweep
                        } else {
                            result.continuation_receipt().cloned().map_or(
                                CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                                |receipt| {
                                    CurrentFreAggregateCounterReceiptStatus::Continuation(
                                        Box::new(receipt),
                                    )
                                },
                            )
                        },
                    })
                    .map_err(|error| {
                        let message = format!("FRE span-sum lifecycle: {error}");
                        CompareError::new(aggregate_attempt_error(&error, message).message)
                    })
            }
            CurrentFreAggregateOperationInner::CompleteSpansSingle(regex, limits) => {
                rebar_sum_streamed_single_match_bounds(regex, haystack, limits).map(|value| {
                    CurrentFreAggregateOperationCounterResult {
                        value,
                        receipt_status: CurrentFreAggregateCounterReceiptStatus::DirectSelectedPlan,
                    }
                })
            }
            CurrentFreAggregateOperationInner::StreamingSpansMany(regex, limits, _) => {
                rebar_sum_streamed_many_match_bounds(regex, haystack, *limits)
                    .map(|value| CurrentFreAggregateOperationCounterResult {
                        value,
                        receipt_status:
                            CurrentFreAggregateCounterReceiptStatus::MissingMultiPlanReceipt,
                    })
                    .map_err(|error| match error {
                        RebarStreamedManySpanError::Execution(error) => {
                            aggregate_lifecycle_complete_spans_many_error(error)
                        }
                        RebarStreamedManySpanError::Reduction(error) => error,
                    })
            }
        }
    }
}

/// Build one exact aggregate operation lifecycle outside the measured public
/// operation boundary.
///
/// # Errors
///
/// Returns an error for an empty pattern set, non-operation model, builder
/// refusal, semantic identity mismatch, or limit-derivation failure.
pub fn current_fre_rebar_aggregate_operation_lifecycle(
    model: &str,
    patterns: &[String],
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
) -> Result<CurrentFreAggregateOperationLifecycle, CompareError> {
    if patterns.is_empty() {
        return Err(CompareError::new(
            "FRE aggregate operation lifecycle requires at least one pattern",
        ));
    }
    match model {
        "count" => {
            build_current_fre_count_lifecycle(patterns, unicode, case_insensitive, haystack_len)
        }
        "count-spans" => {
            build_current_fre_span_sum_lifecycle(patterns, unicode, case_insensitive, haystack_len)
        }
        other => Err(CompareError::new(format!(
            "unexpected aggregate operation lifecycle model {other}"
        ))),
    }
}

const UNICODE_FOLDED_LITERAL_PLAN: &str = "aggregate-unicode-folded-literal-v4";

#[cold]
#[inline(never)]
fn unicode_folded_literal_build_limits(
    limits: &RunLimits,
) -> Result<UnicodeFoldedLiteralBuildLimits, ExecutionError> {
    let positions = limits.pattern_bytes_per_job;
    let equivalents = positions
        .checked_mul(4)
        .ok_or_else(|| ExecutionError::fault("folded-literal equivalent-scalar cap overflow"))?;
    let states = positions
        .checked_add(1)
        .ok_or_else(|| ExecutionError::fault("folded-literal state cap overflow"))?;
    let aggregate = aggregate_build_limits(limits);
    Ok(UnicodeFoldedLiteralBuildLimits {
        admission: aggregate.admission,
        syntax_safety: aggregate.syntax_safety,
        max_scalar_positions: positions,
        max_equivalent_scalars: equivalents,
        max_planner_work: limits.fre_aggregate_compile_work,
        max_planner_scratch_bytes: limits.fre_aggregate_scratch_bytes,
        trie: FoldedLiteralTrieBuildLimits {
            max_patterns: limits.patterns_per_job,
            max_scalar_positions: positions,
            max_equivalent_scalars: equivalents,
            max_states: states,
            max_transitions: equivalents,
            max_work: limits.fre_aggregate_compile_work,
            max_persistent_bytes: limits.fre_aggregate_program_bytes,
            max_peak_bytes: limits.fre_aggregate_program_bytes,
            max_allocations: 3,
        },
    })
}

#[cold]
#[inline(never)]
fn unicode_folded_literal_builder_with_limits(
    pattern: String,
    unicode: bool,
    case_insensitive: bool,
    limits: UnicodeFoldedLiteralBuildLimits,
) -> UnicodeFoldedLiteralBuilder {
    UnicodeFoldedLiteralBuilder::new(pattern)
        .profile(rebar_profile())
        .unicode(unicode)
        .case_insensitive(case_insensitive)
        .limits(limits)
}

#[cold]
#[inline(never)]
fn unicode_folded_literal_build_error(error: &UnicodeFoldedLiteralBuildError) -> ExecutionError {
    let message = format!("FRE Unicode folded-literal build: {error}");
    match error {
        UnicodeFoldedLiteralBuildError::Resource { .. }
        | UnicodeFoldedLiteralBuildError::Trie(fre::FoldedLiteralTrieBuildError::Resource {
            ..
        }) => ExecutionError::unsupported(message),
        _ => ExecutionError::fault(message),
    }
}

#[cold]
#[inline(never)]
fn unicode_folded_literal_resource_refusal(error: &UnicodeFoldedLiteralBuildError) -> bool {
    matches!(
        error,
        UnicodeFoldedLiteralBuildError::Resource { .. }
            | UnicodeFoldedLiteralBuildError::Trie(
                fre::FoldedLiteralTrieBuildError::Resource { .. }
            )
    )
}

#[cold]
#[inline(never)]
fn unicode_folded_literal_run_error(
    error: &UnicodeFoldedLiteralRunError,
    context: &str,
) -> ExecutionError {
    let message = format!("{context}: {error}");
    match error {
        UnicodeFoldedLiteralRunError::Resource { .. }
        | UnicodeFoldedLiteralRunError::Scan(fre::FoldedLiteralTrieScanAttemptError {
            source: fre::FoldedLiteralTrieScanError::Resource { .. },
            ..
        }) => ExecutionError::unsupported(message),
        _ => ExecutionError::fault(message),
    }
}

#[cold]
#[inline(never)]
fn validate_unicode_folded_literal_report(
    report: &fre::UnicodeFoldedLiteralBuildReport,
    operation: UnicodeFoldedLiteralOperation,
) -> Result<(), CompareError> {
    if report.algorithm != UNICODE_FOLDED_LITERAL_ALGORITHM_ID
        || report.operation != operation
        || report.operation.identity()
            != match operation {
                UnicodeFoldedLiteralOperation::Count => {
                    fre::UNICODE_FOLDED_LITERAL_COUNT_OPERATION_ID
                }
                UnicodeFoldedLiteralOperation::SpanSum => {
                    fre::UNICODE_FOLDED_LITERAL_SPAN_SUM_OPERATION_ID
                }
            }
    {
        return Err(CompareError::new(
            "Unicode folded-literal lifecycle identity mismatch",
        ));
    }
    Ok(())
}

#[cold]
#[inline(never)]
fn unicode_folded_literal_displaces_packed_finite_language(
    report: &fre::UnicodeFoldedLiteralBuildReport,
    limits: &RunLimits,
) -> bool {
    report.planner.cartesian_sequences_saturated
        > limits
            .patterns_per_job
            .min(PACKED_ORDERED_LITERAL_CERTIFIED_MAX_PATTERNS)
}

#[cold]
#[inline(never)]
fn try_current_fre_folded_count_lifecycle_with_limits(
    pattern: &str,
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
    limits: &RunLimits,
    build_limits: UnicodeFoldedLiteralBuildLimits,
) -> Result<
    Option<(
        UnicodeFoldedLiteralCountRegex,
        UnicodeFoldedLiteralRunLimits,
    )>,
    CompareError,
> {
    let attempt = match unicode_folded_literal_builder_with_limits(
        pattern.to_owned(),
        unicode,
        case_insensitive,
        build_limits,
    )
    .build_count()
    {
        Ok(attempt) => attempt,
        Err(error) if unicode_folded_literal_resource_refusal(&error) => return Ok(None),
        Err(error) => {
            return Err(CompareError::new(
                unicode_folded_literal_build_error(&error).message,
            ));
        }
    };
    let UnicodeFoldedLiteralBuildAttempt::Admitted(regex) = attempt else {
        return Ok(None);
    };
    if !unicode_folded_literal_displaces_packed_finite_language(regex.build_report(), &limits) {
        return Ok(None);
    }
    validate_unicode_folded_literal_report(
        regex.build_report(),
        UnicodeFoldedLiteralOperation::Count,
    )?;
    let upper = regex
        .full_window_upper_bounds(haystack_len)
        .map_err(|error| {
            CompareError::new(format!(
                "FRE folded-literal count lifecycle preflight: {error}"
            ))
        })?;
    let run_limits = match validate_unicode_folded_literal_policy(upper, limits) {
        Ok(run_limits) => run_limits,
        Err(_) => return Ok(None),
    };
    Ok(Some((regex, run_limits)))
}

fn build_current_fre_count_lifecycle(
    patterns: &[String],
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
) -> Result<CurrentFreAggregateOperationLifecycle, CompareError> {
    let (plan, inner) = if let [pattern] = patterns {
        let regex =
            current_fre_rebar_complete_spans_builder(pattern.clone(), unicode, case_insensitive)
                .build_spans()
                .map_err(|error| {
                    CompareError::new(format!("FRE complete-match count lifecycle build: {error}"))
                })?;
        require_rebar_complete_spans_identity(regex.build_report(), unicode, case_insensitive)
            .map_err(|error| CompareError::new(error.message))?;
        let plan = aggregate_single_plan_label("count", regex.build_report());
        let limits =
            aggregate_run_limits(haystack_len, regex.build_report(), &RunLimits::default())
                .map_err(|error| CompareError::new(error.message))?;
        (
            plan,
            CurrentFreAggregateOperationInner::CompleteMatchCountSingle(regex, limits),
        )
    } else {
        let regex = current_fre_rebar_aggregate_many_builder(patterns, unicode, case_insensitive)
            .build_spans()
            .map_err(|error| {
                CompareError::new(format!(
                    "FRE complete-match count-many lifecycle build: {error}"
                ))
            })?;
        require_aggregate_many_report_identity(
            patterns,
            unicode,
            case_insensitive,
            regex.build_report(),
            AggregateManyOperation::Spans,
        )
        .map_err(|error| CompareError::new(error.message))?;
        let plan = aggregate_many_plan_label("count", regex.build_report().plan);
        let limits =
            current_fre_rebar_aggregate_many_run_limits(haystack_len, regex.build_report())?;
        (
            plan,
            CurrentFreAggregateOperationInner::CompleteMatchCountMany(regex, limits),
        )
    };
    Ok(CurrentFreAggregateOperationLifecycle {
        model: CurrentFreAggregateOperationModel::Count,
        plan,
        haystack_len,
        inner,
    })
}

fn build_current_fre_count_lifecycle_with_folded_limits(
    patterns: &[String],
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
    run_limits: &RunLimits,
    folded_policy_limits: &RunLimits,
    folded_build_limits: UnicodeFoldedLiteralBuildLimits,
) -> Result<CurrentFreAggregateOperationLifecycle, CompareError> {
    if let Some(plan) = ascii_folded_literal::AsciiFoldedLiteralCount::try_build(
        patterns,
        unicode,
        case_insensitive,
        haystack_len,
        run_limits,
    )
    .map_err(|error| CompareError::new(error.message))?
    {
        return Ok(CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::Count,
            plan: ascii_folded_literal::PLAN,
            haystack_len,
            inner: CurrentFreAggregateOperationInner::CountAsciiFolded(Box::new(plan)),
        });
    }
    if let [pattern] = patterns
        && let Some(plan) = fixed_unicode_sequence::FixedUnicodeSequenceCount::try_build(
            pattern,
            unicode,
            case_insensitive,
        )
    {
        return Ok(CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::Count,
            plan: fixed_unicode_sequence::PLAN,
            haystack_len,
            inner: CurrentFreAggregateOperationInner::CountFixedUnicodeSequence(Box::new(plan)),
        });
    }
    if let [pattern] = patterns
        && let Some(plan) = terminal_byte_frontier::TerminalByteFrontierCount::try_build(
            pattern,
            unicode,
            case_insensitive,
            haystack_len,
            run_limits,
        )
        .map_err(|error| CompareError::new(error.message))?
    {
        return Ok(CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::Count,
            plan: terminal_byte_frontier::PLAN,
            haystack_len,
            inner: CurrentFreAggregateOperationInner::CountTerminalByteFrontier(Box::new(plan)),
        });
    }
    if let [pattern] = patterns
        && let Some((regex, limits)) = try_current_fre_folded_count_lifecycle_with_limits(
            pattern,
            unicode,
            case_insensitive,
            haystack_len,
            folded_policy_limits,
            folded_build_limits,
        )?
    {
        return Ok(CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::Count,
            plan: UNICODE_FOLDED_LITERAL_PLAN,
            haystack_len,
            inner: CurrentFreAggregateOperationInner::CountFolded(regex, limits),
        });
    }
    if let Some(lifecycle) = canonical_case_fold::try_build_count(
        patterns,
        unicode,
        case_insensitive,
        haystack_len,
        run_limits,
    )
    .map_err(|error| {
        CompareError::new(format!(
            "FRE canonical case-fold count lifecycle build: {}",
            error.message
        ))
    })? {
        return Ok(CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::Count,
            plan: canonical_case_fold::PLAN,
            haystack_len,
            inner: CurrentFreAggregateOperationInner::CountCanonical(lifecycle),
        });
    }
    build_current_fre_count_lifecycle_incumbent(patterns, unicode, case_insensitive, haystack_len)
}

// Prepared admission wins the focused tiny and 4 KiB screens, while the
// controlled 64 KiB multibyte screen and the public 248,919-byte Russian row
// retain the incumbent. Keep automatic selection inside the largest qualified
// input stratum until longer Unicode inputs clear their own pointwise gate.
const CURRENT_FRE_PREPARED_UNICODE_SCALAR_COUNT_MAX_INPUT_BYTES: usize = 4_096;

fn build_current_fre_count_lifecycle_incumbent(
    patterns: &[String],
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
) -> Result<CurrentFreAggregateOperationLifecycle, CompareError> {
    let (plan, inner) = if let [pattern] = patterns {
        let regex = current_fre_rebar_aggregate_builder(pattern.clone(), unicode, case_insensitive)
            .build_count()
            .map_err(|error| CompareError::new(format!("FRE count lifecycle build: {error}")))?;
        current_fre_rebar_validate_aggregate_identity_with_options(
            regex.build_report(),
            unicode,
            case_insensitive,
            "count",
        )?;
        let plan = aggregate_single_plan_label("count", regex.build_report());
        let retained_upper_bounds = regex
            .retained_full_window_upper_bounds(haystack_len)
            .map_err(|error| {
                CompareError::new(format!(
                    "FRE count lifecycle retained-owner preflight: {error}"
                ))
            })?;
        let fixed_absolute_prospective = regex
            .fixed_absolute_domain_full_window_prospective(haystack_len)
            .map_err(|error| {
                CompareError::new(format!(
                    "FRE count lifecycle fixed-domain preflight: {error}"
                ))
            })?;
        let fixed_absolute_composite = regex
            .fixed_absolute_domain_full_window_composite_prospective(haystack_len)
            .map_err(|error| {
                CompareError::new(format!(
                    "FRE count lifecycle fixed-domain composite preflight: {error}"
                ))
            })?;
        let continuation_sweep = regex.continuation_sweep_upper_bounds().map_err(|error| {
            CompareError::new(format!(
                "FRE count lifecycle continuation-sweep preflight: {error}"
            ))
        })?;
        let limits = aggregate_run_limits_with_fixed_absolute(
            haystack_len,
            regex.build_report(),
            retained_upper_bounds,
            fixed_absolute_prospective,
            fixed_absolute_composite,
            continuation_sweep,
            &RunLimits::default(),
        )
        .map_err(|error| CompareError::new(error.message))?;
        let prepared_unicode_scalar =
            if haystack_len <= CURRENT_FRE_PREPARED_UNICODE_SCALAR_COUNT_MAX_INPUT_BYTES {
                regex
                    .prepare_unicode_scalar_count(haystack_len, limits)
                    .map_err(aggregate_lifecycle_count_error)?
            } else {
                None
            };
        let prepared_width_one_shift_and = regex
            .prepare_fixed_predicate_width_one_shift_and_count(haystack_len, limits)
            .map_err(aggregate_lifecycle_count_error)?;
        let inner = if let Some(admission) = prepared_unicode_scalar {
            CurrentFreAggregateOperationInner::CountSinglePreparedUnicodeScalar(
                regex, limits, admission,
            )
        } else if let Some(admission) = prepared_width_one_shift_and {
            CurrentFreAggregateOperationInner::CountSinglePreparedWidthOneShiftAnd(
                regex, limits, admission,
            )
        } else if matches!(
            regex.build_report().plan,
            AggregatePlanKind::FiniteLiteralDfa | AggregatePlanKind::ContinuationProgram
        ) {
            CurrentFreAggregateOperationInner::CountSingleDense(
                regex,
                limits,
                RefCell::new(AggregateCountWorkspace::new()),
            )
        } else {
            CurrentFreAggregateOperationInner::CountSingle(regex, limits)
        };
        (plan, inner)
    } else {
        let regex = current_fre_rebar_aggregate_many_builder(patterns, unicode, case_insensitive)
            .build_count()
            .map_err(|error| {
                CompareError::new(format!("FRE count-many lifecycle build: {error}"))
            })?;
        current_fre_rebar_validate_aggregate_many_identity(
            patterns,
            regex.build_report(),
            unicode,
            case_insensitive,
            "count",
        )?;
        let plan = aggregate_many_plan_label("count", regex.build_report().plan);
        let limits =
            current_fre_rebar_aggregate_many_run_limits(haystack_len, regex.build_report())?;
        (
            plan,
            CurrentFreAggregateOperationInner::CountMany(regex, limits),
        )
    };
    Ok(CurrentFreAggregateOperationLifecycle {
        model: CurrentFreAggregateOperationModel::Count,
        plan,
        haystack_len,
        inner,
    })
}

fn build_current_fre_span_sum_lifecycle(
    patterns: &[String],
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
) -> Result<CurrentFreAggregateOperationLifecycle, CompareError> {
    let (plan, inner) = if let [pattern] = patterns {
        let regex =
            current_fre_rebar_complete_spans_builder(pattern.clone(), unicode, case_insensitive)
                .build_span_visitor()
                .map_err(|error| {
                    CompareError::new(format!("FRE complete-spans lifecycle build: {error}"))
                })?;
        require_rebar_complete_spans_identity(regex.build_report(), unicode, case_insensitive)
            .map_err(|error| CompareError::new(error.message))?;
        let plan = aggregate_single_plan_label("count-spans", regex.build_report());
        let limits =
            complete_spans_run_limits_with_policy(haystack_len, &regex, &RunLimits::default())
                .map_err(|error| CompareError::new(error.message))?;
        let inner = CurrentFreAggregateOperationInner::CompleteSpansSingle(regex, limits);
        (plan, inner)
    } else {
        let regex = current_fre_rebar_aggregate_many_builder(patterns, unicode, case_insensitive)
            .build_spans()
            .map_err(|error| {
                CompareError::new(format!("FRE complete-spans-many lifecycle build: {error}"))
            })?;
        require_aggregate_many_report_identity(
            patterns,
            unicode,
            case_insensitive,
            regex.build_report(),
            AggregateManyOperation::Spans,
        )
        .map_err(|error| CompareError::new(error.message))?;
        let plan = if regex.build_report().ascii_word_shadow.is_some() {
            "aggregate-many-ascii-word-shadow-continuation-sweep-v1"
        } else {
            aggregate_many_plan_label("count-spans", regex.build_report().plan)
        };
        let limits = current_fre_rebar_aggregate_many_streaming_run_limits(
            haystack_len,
            regex.build_report(),
        )?;
        (
            plan,
            CurrentFreAggregateOperationInner::StreamingSpansMany(
                regex,
                limits,
                RefCell::new(AggregateManySpansWorkspace::new()),
            ),
        )
    };
    Ok(CurrentFreAggregateOperationLifecycle {
        model: CurrentFreAggregateOperationModel::SpanSum,
        plan,
        haystack_len,
        inner,
    })
}

fn reverse_inner_single_plan_label(model: &str, report: &AggregateBuildReport) -> &'static str {
    let plan_id = match report.plan_identity {
        AggregatePlanIdentity::ReverseInner(identity) => Some(identity.kernel.plan_id),
        _ => None,
    };
    match (model == "compile", plan_id) {
        (true, Some(REVERSE_INNER_PLAN_ID)) => "compile-aggregate-reverse-inner-independent-v1",
        (true, Some(REVERSE_INNER_UNION_PLAN_ID)) => {
            "compile-aggregate-reverse-inner-adaptive-union-v2"
        }
        (true, Some(REVERSE_INNER_GROUPED_UNION_PLAN_ID)) => {
            "compile-aggregate-reverse-inner-grouped-union-v2"
        }
        (false, Some(REVERSE_INNER_PLAN_ID)) => "aggregate-reverse-inner-independent-v1",
        (false, Some(REVERSE_INNER_UNION_PLAN_ID)) => "aggregate-reverse-inner-adaptive-union-v2",
        (false, Some(REVERSE_INNER_GROUPED_UNION_PLAN_ID)) => {
            "aggregate-reverse-inner-grouped-union-v2"
        }
        (true, _) => "compile-aggregate-reverse-inner-unrecognized",
        (false, _) => "aggregate-reverse-inner-unrecognized",
    }
}

#[allow(
    clippy::too_many_lines,
    reason = "the exhaustive stable plan-label dispatch keeps every public route adjacent"
)]
fn aggregate_single_plan_label(model: &str, report: &AggregateBuildReport) -> &'static str {
    let url_plan = matches!(
        report.build,
        AggregateBuildAccounting::Continuation(compile)
            if compile.url_aggregate_plans == 1
    ) && report.authenticates_url_aggregate_identity();
    let url_route = report.continuation_strategy == Some(AggregateStrategy::ReverseSequentialRows)
        && matches!(
            (model, report.operation),
            ("count", AggregateOperation::Count)
                | (
                    "count-spans",
                    AggregateOperation::SpanSum | AggregateOperation::Spans
                )
        );
    if url_plan && (model == "compile" || url_route) {
        return if model == "compile" {
            "compile-aggregate-url"
        } else {
            "aggregate-url"
        };
    }
    if matches!(
        report.plan_identity,
        AggregatePlanIdentity::BoundedContext(identity)
            if identity.kernel.plan_id == fre::BOUNDED_AFFIX_PLAN_ID
    ) {
        return if model == "compile" {
            "compile-aggregate-bounded-affix"
        } else {
            "aggregate-bounded-affix"
        };
    }
    if matches!(
        report.plan_identity,
        AggregatePlanIdentity::WordRun(identity)
            if identity.semantics
                == fre::AggregateWordRunSemantics::UnicodeOffFixedWidthByteClassChunks
    ) {
        return if model == "compile" {
            "compile-aggregate-fixed-class-chunks-v1"
        } else {
            "aggregate-fixed-class-chunks-v1"
        };
    }
    let forward_bucket_count = matches!(
        (report.plan_identity, report.build),
        (
            AggregatePlanIdentity::FiniteLiteral(identity),
            AggregateBuildAccounting::FiniteLiteral(build),
        ) if identity.algorithm == fre::ORDERED_LITERAL_FORWARD_BUCKET_TRIE_ALGORITHM_ID
            && identity.operation == fre::ORDERED_LITERAL_FORWARD_BUCKET_TRIE_COUNT_PLAN_ID
            && build.physical_route
                == fre::OrderedLiteralAggregatePhysicalRoute::ByteBucketForwardTrie
    );
    if forward_bucket_count {
        return if model == "compile" {
            "compile-aggregate-finite-literal-bucket-trie-count-v1"
        } else {
            "aggregate-finite-literal-bucket-trie-count-v1"
        };
    }
    let sparse = matches!(
        report.build,
        AggregateBuildAccounting::SparseFiniteLiteral(_)
    );
    match (model, report.plan, sparse) {
        ("compile", AggregatePlanKind::ExactLiteral, _) => "compile-aggregate-exact-literal",
        ("compile", AggregatePlanKind::UnicodeScalarClass, _) => {
            "compile-aggregate-unicode-scalar-class"
        }
        ("compile", AggregatePlanKind::WordRun, _) => "compile-aggregate-word-run-v1",
        ("compile", AggregatePlanKind::LiteralAssertions, _) => {
            "compile-aggregate-literal-assertions-v1"
        }
        ("compile", AggregatePlanKind::BlockingDelimiter, _) => {
            "compile-aggregate-blocking-delimiter-v1"
        }
        ("compile", AggregatePlanKind::TokenPhrase, _) => "compile-aggregate-token-phrase-v2",
        ("compile", AggregatePlanKind::FixedClassSandwich, _) => {
            "compile-aggregate-fixed-class-sandwich"
        }
        ("compile", AggregatePlanKind::LiteralClassRunLiteral, _) => {
            "compile-aggregate-literal-class-run-literal-v2"
        }
        ("compile", AggregatePlanKind::ReverseInner, _) => {
            reverse_inner_single_plan_label(model, report)
        }
        ("compile", AggregatePlanKind::GraphemeScalarDfa, _) => {
            "compile-aggregate-grapheme-scalar-dfa"
        }
        ("compile", AggregatePlanKind::BoundedClassSequence, _) => {
            "compile-aggregate-bounded-class-sequence"
        }
        ("compile", AggregatePlanKind::BoundedSeparatedFields, _) => {
            "compile-aggregate-bounded-separated-fields"
        }
        ("compile", AggregatePlanKind::DelimiterFieldSpans, _) => {
            "compile-aggregate-delimiter-field-spans"
        }
        ("compile", AggregatePlanKind::PrefixClassAlternation, _) => {
            "compile-aggregate-prefix-class-alternation"
        }
        ("compile", AggregatePlanKind::BoundedContext, _) => "compile-aggregate-bounded-context",
        ("compile", AggregatePlanKind::FixedAbsoluteDomain, _) => {
            "compile-aggregate-fixed-absolute-domain"
        }
        ("compile", AggregatePlanKind::BoundedLiteralPair, _)
            if matches!(
                report.plan_identity,
                AggregatePlanIdentity::BoundedLiteralPair(identity) if identity.kernel.gap_min > 0
            ) =>
        {
            "compile-aggregate-bounded-literal-pair-v2"
        }
        ("compile", AggregatePlanKind::BoundedLiteralPair, _) => {
            "compile-aggregate-bounded-literal-pair-v1"
        }
        ("compile", AggregatePlanKind::FiniteLiteralDfa, true) => {
            "compile-aggregate-finite-literal-sparse"
        }
        ("compile", AggregatePlanKind::FiniteLiteralDfa, false) => {
            "compile-aggregate-finite-literal-dfa"
        }
        ("compile", AggregatePlanKind::PackedFiniteLiteral, _) => {
            "compile-aggregate-finite-literal-packed-v3"
        }
        ("compile", AggregatePlanKind::GuardedAsciiWordDictionary, _) => {
            "compile-aggregate-guarded-ascii-word"
        }
        ("compile", AggregatePlanKind::GuardedUnicodeWordLiteralSet, _) => {
            "compile-aggregate-guarded-unicode-word"
        }
        ("compile", AggregatePlanKind::FixedPredicateWord64, _) => {
            "compile-aggregate-fixed-predicate-word64"
        }
        ("compile", AggregatePlanKind::ContinuationProgram, _) => {
            "compile-aggregate-continuation-program"
        }
        (_, AggregatePlanKind::ExactLiteral, _) => "aggregate-exact-literal",
        (_, AggregatePlanKind::UnicodeScalarClass, _) => "aggregate-unicode-scalar-class",
        (_, AggregatePlanKind::WordRun, _) => "aggregate-word-run-v1",
        (_, AggregatePlanKind::LiteralAssertions, _) => "aggregate-literal-assertions-v1",
        (_, AggregatePlanKind::BlockingDelimiter, _) => "aggregate-blocking-delimiter-v1",
        (_, AggregatePlanKind::TokenPhrase, _) => "aggregate-token-phrase-v2",
        (_, AggregatePlanKind::FixedClassSandwich, _) => "aggregate-fixed-class-sandwich",
        (_, AggregatePlanKind::LiteralClassRunLiteral, _) => {
            "aggregate-literal-class-run-literal-v2"
        }
        (_, AggregatePlanKind::ReverseInner, _) => reverse_inner_single_plan_label(model, report),
        (_, AggregatePlanKind::GraphemeScalarDfa, _) => "aggregate-grapheme-scalar-dfa",
        (_, AggregatePlanKind::BoundedClassSequence, _) => "aggregate-bounded-class-sequence",
        (_, AggregatePlanKind::BoundedSeparatedFields, _) => "aggregate-bounded-separated-fields",
        (_, AggregatePlanKind::DelimiterFieldSpans, _) => "aggregate-delimiter-field-spans",
        (_, AggregatePlanKind::PrefixClassAlternation, _) => "aggregate-prefix-class-alternation",
        (_, AggregatePlanKind::BoundedContext, _) => "aggregate-bounded-context",
        (_, AggregatePlanKind::FixedAbsoluteDomain, _) => "aggregate-fixed-absolute-domain",
        (_, AggregatePlanKind::BoundedLiteralPair, _)
            if matches!(
                report.plan_identity,
                AggregatePlanIdentity::BoundedLiteralPair(identity) if identity.kernel.gap_min > 0
            ) =>
        {
            "aggregate-bounded-literal-pair-v2"
        }
        (_, AggregatePlanKind::BoundedLiteralPair, _) => "aggregate-bounded-literal-pair-v1",
        (_, AggregatePlanKind::FiniteLiteralDfa, true) => "aggregate-finite-literal-sparse",
        (_, AggregatePlanKind::FiniteLiteralDfa, false) => "aggregate-finite-literal-dfa",
        (_, AggregatePlanKind::PackedFiniteLiteral, _) => "aggregate-finite-literal-packed-v3",
        (_, AggregatePlanKind::GuardedAsciiWordDictionary, _) => "aggregate-guarded-ascii-word",
        (_, AggregatePlanKind::GuardedUnicodeWordLiteralSet, _) => "aggregate-guarded-unicode-word",
        (_, AggregatePlanKind::FixedPredicateWord64, _) => "aggregate-fixed-predicate-word64",
        (_, AggregatePlanKind::ContinuationProgram, _) => "aggregate-continuation-program",
    }
}

fn aggregate_many_plan_label(model: &str, plan: AggregateManyPlanKind) -> &'static str {
    match (model, plan) {
        ("compile", AggregateManyPlanKind::OrderedLiteral) => "compile-many-ordered-literal",
        ("compile", AggregateManyPlanKind::TotalByteCoverSpanSum) => {
            "compile-many-total-byte-cover"
        }
        ("compile", AggregateManyPlanKind::ContinuationProgram) => {
            "compile-many-continuation-program"
        }
        (_, AggregateManyPlanKind::OrderedLiteral) => "aggregate-many-ordered-literal",
        (_, AggregateManyPlanKind::TotalByteCoverSpanSum) => {
            "aggregate-many-total-byte-cover-span-sum"
        }
        (_, AggregateManyPlanKind::ContinuationProgram) => "aggregate-many-continuation-program",
    }
}

/// Construct the exact portable-search builder used by the authenticated
/// current-FRE Rebar adapter.
///
/// # Errors
///
/// Returns an error for the case-insensitive inputs the semantic adapter
/// currently refuses rather than silently widening timing coverage.
pub fn current_fre_rebar_portable_builder(
    pattern: impl Into<String>,
    unicode: bool,
    case_insensitive: bool,
) -> Result<PortableBuilder, CompareError> {
    if case_insensitive {
        return Err(CompareError::new(
            "current FRE facade has no case-insensitive builder option",
        ));
    }
    Ok(PortableBuilder::new(pattern)
        .profile(rebar_profile())
        .unicode(unicode))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct CurrentFreGrepLimits {
    search: SearchLimits,
    reducer_steps: u64,
    operation_work: usize,
    sequential_bytes: usize,
    prefilter_build: CaptureRequiredLiteralBuildLimits,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct CurrentFreRequiredLiteralScan {
    run_limits: CaptureRequiredLiteralRunLimits,
    transitions_upper_bound: usize,
    match_events_upper_bound: usize,
    searched_bytes: usize,
}

// A consolidated literal scan has fixed iterator/dispatch cost in addition to
// touching the source a second time. Below one KiB, even eliminating every K0
// line search cannot reliably amortize that fixed cost. This construction-time
// gate depends only on authenticated source length.
const CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES: usize = 1_024;

// Once at least this many observed line domains have supplied candidates and
// at least three quarters of them survive, continuing the prefilter can save
// at most one quarter of the remaining K0 calls under the observed prefix.
// Retiring it bounds dense-input regret while retaining sparse-input wins.
const CURRENT_FRE_GREP_PREFILTER_DENSITY_MIN_LINES: usize = 16;

#[derive(Debug)]
#[allow(
    clippy::large_enum_variant,
    reason = "the exact caller-owned K0 workspace stays inline and construction remains outside the operation boundary"
)]
enum CurrentFreGrepRoute<'r> {
    /// The only route admitted by the formal Rebar grep lifecycle. The search
    /// workspace is deliberately created by the first operation so that the
    /// first/steady distinction includes the same kind of lazy scratch setup
    /// as the pinned Rust `Regex::is_match` API.
    RebarLines {
        regex: &'r PortableRegex,
        search: Option<PortableSearchSession<'r>>,
        is_match_token: Option<PortableIsMatchValueToken>,
        bound_byte_class_delimiter: Option<PortableBoundByteClassDelimiterMatcher>,
    },
    /// Generic whole-input routes retained for non-scoreboard callers and
    /// focused regression tests. Formal Rebar construction never selects it.
    Stream(PortableGrepSession<'r>),
    /// Generic candidate-pruned line search retained outside the formal Rebar
    /// boundary. Formal Rebar construction never selects it.
    Search {
        search: PortableSearchSession<'r>,
        prefilter: Option<CaptureRequiredLiteralPlan>,
        required_literal_scan: Option<CurrentFreRequiredLiteralScan>,
        scan_admission: CurrentFreGrepScanAdmission,
    },
}

/// One already-built plain-grep artifact at the first/steady public-operation
/// boundary used by the authenticated current-FRE Rebar adapter.
///
/// The formal route invokes the retained matcher on every `ByteSlice::lines`
/// domain. It never selects a whole-input stream, prefilters candidate lines,
/// or fuses line iteration with matching. Its reusable search workspace is
/// initialized by the first public operation and retained for steady calls.
#[derive(Debug)]
pub struct CurrentFreGrepSession<'r> {
    route: CurrentFreGrepRoute<'r>,
    runtime_implementation_id: &'static str,
    haystack_len: usize,
    limits: CurrentFreGrepLimits,
}

impl CurrentFreGrepSession<'_> {
    /// Stable runtime identity inherited from the immutable semantic matcher.
    #[must_use]
    pub const fn runtime_implementation_id(&self) -> &'static str {
        self.runtime_implementation_id
    }

    /// Whether construction published the generic required-literal sidecar.
    ///
    /// A published sidecar can still retain its construction-proved
    /// delimiter-sensitive per-line fallback for this route.
    #[must_use]
    pub const fn has_required_literal_prefilter(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::Search {
                prefilter: Some(_),
                ..
            }
        )
    }

    /// Whether this haystack length admitted the consolidated whole-input
    /// required-literal scan. Dense-prefix execution may retire that scan
    /// after a bounded number of line domains.
    #[must_use]
    pub const fn uses_required_literal_prefilter(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::Search {
                required_literal_scan: Some(_),
                ..
            }
        )
    }

    /// Whether construction retained a reusable K0 workspace for candidate
    /// line searches.
    #[must_use]
    pub const fn has_reusable_k0_workspace(&self) -> bool {
        match &self.route {
            CurrentFreGrepRoute::RebarLines { search, .. } => search.is_some(),
            CurrentFreGrepRoute::Search { search, .. } => {
                search.workspace_setup_accounting().is_some()
            }
            CurrentFreGrepRoute::Stream(_) => false,
        }
    }

    /// Whether the initialized strict line route retained an admitted K0
    /// repeated-is-match token.
    #[must_use]
    pub const fn uses_prepared_k0_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_k0_warm_route()
        )
    }

    /// Whether the initialized strict line route retained an admitted Unicode
    /// word-run token.
    #[must_use]
    pub const fn uses_prepared_unicode_word_run_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_unicode_word_run_route()
        )
    }

    /// Whether the initialized strict line route retained an exact byte-class
    /// delimiter token and its construction-bound matcher.
    #[must_use]
    pub const fn uses_prepared_byte_class_delimiter_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                bound_byte_class_delimiter: Some(_),
                ..
            } if token.uses_byte_class_delimiter_route()
        )
    }

    /// Whether the initialized strict line route retained an exact bounded
    /// delimited-field token.
    #[must_use]
    pub const fn uses_prepared_bounded_delimited_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_bounded_delimited_route()
        )
    }

    /// Whether the initialized strict line route retained an exact
    /// class-guarded literal existence token.
    #[must_use]
    pub const fn uses_prepared_uri_like_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_uri_like_route()
        )
    }

    /// Whether the initialized strict line route retained the fused exact
    /// class-guarded-literal/byte-class-delimiter union token.
    #[must_use]
    pub const fn uses_prepared_fused_uri_like_composite_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_fused_uri_like_composite_route()
        )
    }

    /// Whether the initialized strict line route retained an exact
    /// absolute-start scalar-corridor existence token.
    #[must_use]
    pub const fn uses_prepared_anchored_scalar_corridor_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_anchored_scalar_corridor_route()
        )
    }

    /// Whether the initialized strict line route retained an exact
    /// literal-prefix/fixed-class existence token.
    #[must_use]
    pub const fn uses_prepared_literal_prefix_class_is_match(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::RebarLines {
                is_match_token: Some(token),
                ..
            } if token.uses_literal_prefix_class_route()
        )
    }

    /// Whether construction selected the certified direct line-total stream.
    #[must_use]
    pub const fn uses_line_total_stream(&self) -> bool {
        matches!(
            &self.route,
            CurrentFreGrepRoute::Stream(session) if session.is_line_total()
        )
    }

    /// Execute one complete Rebar LF/CRLF plain-grep operation.
    ///
    /// The first call is the first-operation boundary and later calls on the
    /// same value are steady operations. The first call initializes the
    /// caller-owned search workspace before invoking the matcher on its first
    /// line; later calls reuse it.
    ///
    /// # Errors
    ///
    /// Returns an error for a source-length mismatch, source-independent
    /// operation preflight refusal, a typed semantic-search refusal, or an
    /// authenticated engine/adapter invariant failure. No post-source route
    /// fallback is permitted.
    pub fn execute(&mut self, haystack: &[u8]) -> Result<u64, CompareError> {
        self.execute_inner(haystack)
            .map_err(|error| CompareError::new(error.message))
    }

    fn execute_inner(&mut self, haystack: &[u8]) -> Result<u64, ExecutionError> {
        if haystack.len() != self.haystack_len {
            return Err(ExecutionError::fault(format!(
                "grep lifecycle haystack length {} differs from prepared {}",
                haystack.len(),
                self.haystack_len
            )));
        }
        match &mut self.route {
            CurrentFreGrepRoute::RebarLines {
                regex,
                search,
                is_match_token,
                bound_byte_class_delimiter,
            } => {
                if search.is_none() {
                    let prepared = regex
                        .search_session(SearchSessionLimits {
                            max_setup_work: self.limits.search.max_work,
                            max_scratch_bytes: self.limits.search.max_scratch_bytes,
                        })
                        .map_err(|error| {
                            ExecutionError::unsupported(format!(
                                "FRE strict Rebar grep search-session build failed: {error}"
                            ))
                        })?;
                    if prepared.runtime_implementation_id() != self.runtime_implementation_id {
                        return Err(ExecutionError::fault(
                            "FRE strict Rebar grep matcher/session runtime identity mismatch",
                        ));
                    }
                    let preferred = prepared
                        .prepare_is_match_value_token(self.haystack_len, self.limits.search);
                    let token = if formal_rebar_prepared_is_match_token(preferred) {
                        preferred
                    } else {
                        prepared.prepare_k0_warm_is_match_value_token(
                            self.haystack_len,
                            self.limits.search,
                        )
                    };
                    let token = formal_rebar_prepared_is_match_token(token).then_some(token);
                    *bound_byte_class_delimiter = token.and_then(|token| {
                        prepared.bind_byte_class_delimiter_is_match_value_token(token)
                    });
                    *is_match_token = token;
                    *search = Some(prepared);
                }
                let search = search.as_mut().ok_or_else(|| {
                    ExecutionError::fault("FRE strict Rebar grep session initialization vanished")
                })?;
                execute_rebar_line_grep(
                    search,
                    *is_match_token,
                    *bound_byte_class_delimiter,
                    haystack,
                    self.limits,
                )
            }
            CurrentFreGrepRoute::Stream(session) => {
                let result = session.count(haystack).map_err(|error| {
                    ExecutionError::fault(format!(
                        "FRE whole-input grep lifecycle refused execution: {error}"
                    ))
                })?;
                if !result.receipt.closes() {
                    return Err(ExecutionError::fault(
                        "FRE whole-input grep lifecycle returned an open receipt",
                    ));
                }
                Ok(result.count())
            }
            CurrentFreGrepRoute::Search {
                search,
                prefilter,
                required_literal_scan,
                scan_admission,
            } => execute_current_fre_search_grep(
                search,
                prefilter.as_ref(),
                *required_literal_scan,
                *scan_admission,
                haystack,
                self.limits,
            ),
        }
    }
}

/// Construct the default authenticated current-FRE plain-grep lifecycle.
///
/// Matcher construction occurs before the first public operation. Reusable
/// search scratch is initialized by the first operation, matching the lazy
/// first-call boundary of the pinned Rust reference API.
///
/// # Errors
///
/// Returns an error for a source-independent construction refusal or an
/// impossible profile/plan binding. Optional required-literal capability and
/// resource refusals retain the already-built semantic search route.
pub fn current_fre_rebar_grep_session(
    regex: &PortableRegex,
    haystack_len: usize,
) -> Result<CurrentFreGrepSession<'_>, CompareError> {
    current_fre_rebar_grep_session_with_limits(regex, haystack_len, &RunLimits::default())
}

/// Construct the authenticated plain-grep lifecycle under explicit adapter
/// limits.
///
/// This is the limit-controlled counterpart to
/// [`current_fre_rebar_grep_session`].
///
/// # Errors
///
/// Returns the same failures as [`current_fre_rebar_grep_session`].
pub fn current_fre_rebar_grep_session_with_limits<'r>(
    regex: &'r PortableRegex,
    haystack_len: usize,
    limits: &RunLimits,
) -> Result<CurrentFreGrepSession<'r>, CompareError> {
    let search_limits = SearchLimits {
        max_work: limits.fre_search_work,
        max_scratch_bytes: limits.fre_scratch_bytes,
    };
    let prefilter_build = capture_required_literal_build_limits(limits);
    let runtime_implementation_id = regex.runtime_implementation_id();
    let grep_limits = CurrentFreGrepLimits {
        search: search_limits,
        reducer_steps: limits.reducer_steps,
        operation_work: limits.fre_aggregate_operation_work,
        sequential_bytes: limits.fre_aggregate_sequential_bytes,
        prefilter_build,
    };
    // Rebar explicitly requires the line iterator and one `is_match` call for
    // every line to remain in the measured operation. Admit that complete LF
    // scan before source access, but do not inspect source bytes or construct a
    // whole-input/prefilter sidecar here.
    CurrentFreGrepScanAdmission::line_scan(haystack_len, grep_limits)
        .map_err(|error| CompareError::new(error.message))?;
    let route = CurrentFreGrepRoute::RebarLines {
        regex,
        search: None,
        is_match_token: None,
        bound_byte_class_delimiter: None,
    };
    Ok(CurrentFreGrepSession {
        route,
        runtime_implementation_id,
        haystack_len,
        limits: grep_limits,
    })
}

fn prepare_current_fre_grep_prefilter(
    prefilter: Option<CaptureRequiredLiteralPlan>,
    haystack_len: usize,
    max_prefilter_transitions: usize,
    limits: CurrentFreGrepLimits,
) -> Result<
    (
        Option<CaptureRequiredLiteralPlan>,
        Option<CurrentFreRequiredLiteralScan>,
        CurrentFreGrepScanAdmission,
    ),
    CompareError,
> {
    let line_scan = CurrentFreGrepScanAdmission::line_scan(haystack_len, limits)
        .map_err(|error| CompareError::new(error.message))?;
    let Some(prefilter) = prefilter else {
        return Ok((None, None, line_scan));
    };
    if haystack_len < CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES {
        return Ok((Some(prefilter), None, line_scan));
    }
    let Some(prospective) =
        prefilter
            .line_partition_prospective(haystack_len)
            .map_err(|error| {
                CompareError::new(format!(
                    "FRE grep required-literal prospective failed: {error}"
                ))
            })?
    else {
        return Ok((Some(prefilter), None, line_scan));
    };
    if prospective.transitions_upper_bound > max_prefilter_transitions {
        return Ok((Some(prefilter), None, line_scan));
    }
    let scan_admission = match CurrentFreGrepScanAdmission::line_and_required_literal(
        haystack_len,
        prospective.transitions_upper_bound,
        prospective.match_events_upper_bound,
        limits,
    ) {
        Ok(admission) => admission,
        Err(error) if error.status == Status::Unsupported => {
            return Ok((Some(prefilter), None, line_scan));
        }
        Err(error) => return Err(CompareError::new(error.message)),
    };
    let required_literal_scan = CurrentFreRequiredLiteralScan {
        run_limits: CaptureRequiredLiteralRunLimits {
            max_transitions: max_prefilter_transitions,
        },
        transitions_upper_bound: prospective.transitions_upper_bound,
        match_events_upper_bound: prospective.match_events_upper_bound,
        searched_bytes: prospective.searched_bytes,
    };
    Ok((Some(prefilter), Some(required_literal_scan), scan_admission))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct CurrentFreGrepScanAdmission {
    work: usize,
    sequential_bytes: usize,
}

impl CurrentFreGrepScanAdmission {
    fn line_scan(
        haystack_len: usize,
        limits: CurrentFreGrepLimits,
    ) -> Result<Self, ExecutionError> {
        Self::check(haystack_len, haystack_len, limits)
    }

    fn line_and_required_literal(
        haystack_len: usize,
        prefilter_transitions: usize,
        prefilter_match_events: usize,
        limits: CurrentFreGrepLimits,
    ) -> Result<Self, ExecutionError> {
        let scan_work = checked_aggregate_add(
            haystack_len,
            prefilter_transitions,
            "plain-grep LF and required-literal work",
        )?;
        let work = checked_aggregate_add(
            scan_work,
            prefilter_match_events,
            "plain-grep required-literal match-event work",
        )?;
        let sequential_bytes = checked_aggregate_mul(
            haystack_len,
            2,
            "plain-grep LF and required-literal sequential bytes",
        )?;
        Self::check(work, sequential_bytes, limits)
    }

    fn check(
        work: usize,
        sequential_bytes: usize,
        limits: CurrentFreGrepLimits,
    ) -> Result<Self, ExecutionError> {
        if work > limits.operation_work {
            return Err(ExecutionError::unsupported(format!(
                "FRE plain-grep prefilter requires {work} work, limit is {}",
                limits.operation_work
            )));
        }
        if sequential_bytes > limits.sequential_bytes {
            return Err(ExecutionError::unsupported(format!(
                "FRE plain-grep prefilter requires {sequential_bytes} sequential bytes, limit is {}",
                limits.sequential_bytes
            )));
        }
        Ok(Self {
            work,
            sequential_bytes,
        })
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct CurrentFreSearchGrepReport {
    count: u64,
    line_domains: usize,
    candidate_domains: usize,
    search_executions: usize,
    consolidated_prefilter: bool,
    prefilter_cutover: bool,
    prefilter_transitions: usize,
    prefilter_match_events: usize,
    prefilter_match_events_upper_bound: usize,
    prefilter_sequential_bytes: usize,
}

fn current_fre_grep_should_cut_over_prefilter(
    line_domains: usize,
    candidate_domains: usize,
) -> bool {
    line_domains >= CURRENT_FRE_GREP_PREFILTER_DENSITY_MIN_LINES
        && candidate_domains >= line_domains.saturating_sub(line_domains / 4)
}

/// Execute Rebar's plain-grep contract literally: split with
/// `ByteSlice::lines` (which removes LF and an immediately preceding CR), then
/// invoke the retained matcher exactly once for every line domain.
fn execute_rebar_line_grep(
    search: &mut PortableSearchSession<'_>,
    is_match_token: Option<PortableIsMatchValueToken>,
    bound_byte_class_delimiter: Option<PortableBoundByteClassDelimiterMatcher>,
    haystack: &[u8],
    limits: CurrentFreGrepLimits,
) -> Result<u64, ExecutionError> {
    if let Some(is_match_token) = is_match_token {
        if let Some(bound) = bound_byte_class_delimiter {
            return execute_rebar_line_grep_with(search, haystack, limits, |search, line| {
                if let Some(matched) = bound.try_is_match(line) {
                    Ok(matched)
                } else {
                    search.is_match_value_prepared(line, is_match_token)
                }
            });
        }
        if is_match_token.uses_prepared_route() {
            return execute_rebar_line_grep_with(search, haystack, limits, |search, line| {
                search.is_match_value_prepared(line, is_match_token)
            });
        }
    }
    execute_rebar_line_grep_with(search, haystack, limits, |search, line| {
        search.is_match_value(line, limits.search)
    })
}

/// Keep generic prepared matchers available to ordinary FRE callers, but do
/// not score rigid single-workload HIR recognizers until each has independent
/// family witnesses. Formal grep falls through to the ordinary retained K0
/// search for these shapes.
fn formal_rebar_prepared_is_match_token(token: PortableIsMatchValueToken) -> bool {
    !token.uses_prepared_route()
        || token.uses_k0_warm_route()
        || token.uses_unicode_word_run_route()
        || token.uses_byte_class_delimiter_route()
}

#[inline]
fn execute_rebar_line_grep_with(
    search: &mut PortableSearchSession<'_>,
    haystack: &[u8],
    limits: CurrentFreGrepLimits,
    mut is_match: impl FnMut(&mut PortableSearchSession<'_>, &[u8]) -> Result<bool, fre::SearchError>,
) -> Result<u64, ExecutionError> {
    let mut count = 0_u64;
    let mut line_events = 0_u64;
    for line in haystack.lines() {
        charge(
            &mut line_events,
            1,
            limits.reducer_steps,
            "FRE strict Rebar grep line events",
        )?;
        let matched = is_match(search, line).map_err(|error| {
            ExecutionError::unsupported(format!(
                "FRE strict Rebar grep line search refused: {error}"
            ))
        })?;
        if matched {
            count = count
                .checked_add(1)
                .ok_or_else(|| ExecutionError::fault("FRE strict Rebar grep count overflow"))?;
        }
    }
    Ok(count)
}

#[allow(
    clippy::too_many_lines,
    reason = "source-free scan admission, exact line alignment, K0 authority, and final accounting authentication remain one auditable transaction"
)]
fn execute_current_fre_search_grep(
    search: &mut PortableSearchSession<'_>,
    prefilter: Option<&CaptureRequiredLiteralPlan>,
    required_literal_scan: Option<CurrentFreRequiredLiteralScan>,
    scan_admission: CurrentFreGrepScanAdmission,
    haystack: &[u8],
    limits: CurrentFreGrepLimits,
) -> Result<u64, ExecutionError> {
    let consolidated_prefilter = required_literal_scan.is_some();
    let prefilter_transition_bound =
        required_literal_scan.map_or(0, |scan| scan.transitions_upper_bound);
    let prefilter_match_events_upper_bound =
        required_literal_scan.map_or(0, |scan| scan.match_events_upper_bound);
    let prefilter_sequential_bytes = required_literal_scan.map_or(0, |scan| scan.searched_bytes);
    let mut line_matches = if let Some(prepared) = required_literal_scan {
        let prefilter = prefilter.ok_or_else(|| {
            ExecutionError::fault(
                "FRE plain-grep admitted a required-literal scan without its immutable plan",
            )
        })?;
        let scan = prefilter
            .line_partition_matches(haystack, prepared.run_limits)
            .map_err(|error| {
                ExecutionError::fault(format!(
                    "FRE plain-grep required-literal scan violated preflight: {error}"
                ))
            })?
            .ok_or_else(|| {
                ExecutionError::fault(
                    "FRE plain-grep required-literal delimiter proof changed after admission",
                )
            })?;
        if scan.identity().plan != prefilter.build_report().identity
            || scan.identity().build_limits != limits.prefilter_build
            || scan.identity().operation
                != CaptureRequiredLiteralSearchOperation::LinePartitionMatchesV1
            || scan.identity().run_limits != prepared.run_limits
            || scan.accounting().transitions_upper_bound != prepared.transitions_upper_bound
            || scan.accounting().match_events_upper_bound != prepared.match_events_upper_bound
            || scan.accounting().searched_bytes != prepared.searched_bytes
        {
            return Err(ExecutionError::fault(
                "FRE plain-grep required-literal scan failed identity/P/A authentication",
            ));
        }
        Some(scan.peekable())
    } else {
        None
    };

    let mut report = CurrentFreSearchGrepReport {
        consolidated_prefilter,
        prefilter_transitions: prefilter_transition_bound,
        prefilter_match_events_upper_bound,
        prefilter_sequential_bytes,
        ..CurrentFreSearchGrepReport::default()
    };
    let mut reducer_events = 0_u64;
    let mut raw_cursor = 0_usize;
    for raw_line in haystack.lines_with_terminator() {
        let line_start = raw_cursor;
        raw_cursor = raw_cursor
            .checked_add(raw_line.len())
            .ok_or_else(|| ExecutionError::fault("FRE plain-grep raw line cursor overflow"))?;
        let line = if let Some(without_lf) = raw_line.strip_suffix(b"\n") {
            without_lf.strip_suffix(b"\r").unwrap_or(without_lf)
        } else {
            raw_line
        };
        let line_end = line_start
            .checked_add(line.len())
            .ok_or_else(|| ExecutionError::fault("FRE plain-grep semantic line end overflow"))?;
        report.line_domains =
            checked_aggregate_add(report.line_domains, 1, "plain-grep line domains")?;
        charge(
            &mut reducer_events,
            1,
            limits.reducer_steps,
            "FRE plain-grep line events",
        )?;
        let mut cut_over_after_candidate = false;
        let candidate = if let Some(matches) = line_matches.as_mut() {
            let mut candidate = false;
            while matches.peek().is_some_and(|&(start, _)| start < raw_cursor) {
                let (start, end) = matches.next().ok_or_else(|| {
                    ExecutionError::fault("peeked plain-grep literal match disappeared")
                })?;
                report.prefilter_match_events = checked_aggregate_add(
                    report.prefilter_match_events,
                    1,
                    "plain-grep required-literal match events",
                )?;
                if start < line_start || start >= end || end > line_end {
                    return Err(ExecutionError::fault(
                        "FRE plain-grep required-literal match escaped its semantic line",
                    ));
                }
                let first_candidate_match = !candidate;
                candidate = true;
                if first_candidate_match
                    && current_fre_grep_should_cut_over_prefilter(
                        report.line_domains,
                        report.candidate_domains.saturating_add(1),
                    )
                {
                    // Stop after the first proving match on the cutover line.
                    // In particular, do not `peek` for another match: that
                    // lookahead could traverse the entire remaining source
                    // before the dense-prefix decision retires the iterator.
                    cut_over_after_candidate = true;
                    break;
                }
            }
            candidate
        } else {
            true
        };
        if !candidate {
            continue;
        }
        report.candidate_domains =
            checked_aggregate_add(report.candidate_domains, 1, "plain-grep candidate domains")?;
        if cut_over_after_candidate {
            // The semantic K0 matcher remains authoritative. Dropping the
            // borrowed literal iterator merely admits all remaining line
            // domains, avoiding a redundant full second traversal on dense
            // inputs. The whole-input prospective was charged before source
            // access and remains a conservative terminal envelope.
            line_matches = None;
            report.prefilter_cutover = true;
        }
        report.search_executions =
            checked_aggregate_add(report.search_executions, 1, "plain-grep search executions")?;
        if search
            .is_match_value(line, limits.search)
            .map_err(|error| {
                ExecutionError::unsupported(format!(
                    "FRE plain-grep semantic search refused: {error}"
                ))
            })?
        {
            report.count = report
                .count
                .checked_add(1)
                .ok_or_else(|| ExecutionError::fault("FRE plain-grep count overflow"))?;
        }
    }
    if raw_cursor != haystack.len() {
        return Err(ExecutionError::fault(
            "FRE plain-grep line iterator did not consume the complete source",
        ));
    }
    // A dense-prefix cutover intentionally discarded the remaining iterator:
    // its unassigned matches are no longer needed because K0 searched every
    // subsequent line. Without a cutover, retain the complete-stream drain
    // invariant.
    if let Some(matches) = line_matches.as_mut()
        && matches.next().is_some()
    {
        return Err(ExecutionError::fault(
            "FRE plain-grep required-literal match was not assigned to a semantic line",
        ));
    }
    if report.prefilter_transitions > prefilter_transition_bound
        || report.prefilter_match_events > report.prefilter_match_events_upper_bound
        || report.prefilter_sequential_bytes > haystack.len()
    {
        return Err(ExecutionError::fault(
            "FRE plain-grep required-literal scan exceeded its prospective",
        ));
    }
    if report.search_executions != report.candidate_domains
        || report.candidate_domains > report.line_domains
        || (report.prefilter_cutover && !report.consolidated_prefilter)
    {
        return Err(ExecutionError::fault(
            "FRE plain-grep search/domain cardinality invariant failed",
        ));
    }
    if consolidated_prefilter {
        if scan_admission.work
            != haystack
                .len()
                .checked_add(prefilter_transition_bound)
                .and_then(|work| work.checked_add(prefilter_match_events_upper_bound))
                .ok_or_else(|| {
                    ExecutionError::fault("FRE plain-grep admitted work overflowed on closure")
                })?
            || scan_admission.sequential_bytes
                != haystack.len().checked_mul(2).ok_or_else(|| {
                    ExecutionError::fault(
                        "FRE plain-grep admitted sequential bytes overflowed on closure",
                    )
                })?
        {
            return Err(ExecutionError::fault(
                "FRE plain-grep prefilter admission failed to close",
            ));
        }
    } else if scan_admission.work != haystack.len()
        || scan_admission.sequential_bytes != haystack.len()
    {
        return Err(ExecutionError::fault(
            "FRE plain-grep line-scan admission failed to close",
        ));
    }
    Ok(report.count)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CurrentFreCaptureModel {
    CountCaptures,
    GrepCaptures,
}

#[derive(Clone, Copy, Debug)]
enum CurrentFreCapturePreparation {
    MaterializedWhole(CaptureAggregateLimits),
    MaterializedLines(CaptureAggregateLimits),
}

// Retained by the generic capture-participation API below. The formal Rebar
// lifecycle deliberately never constructs this batch shortcut.
#[derive(Debug)]
struct LineBatchPreparation {
    /// Exact-capacity caller-owned candidate-domain storage.
    packed: Vec<u8>,
    /// Construction-certified byte that no consuming HIR atom accepts.
    separator: u8,
    /// Exact bytes retained by `packed` across public operations.
    retained_bytes: usize,
    /// Residual dynamic peak after the retained batch storage is charged.
    operation_peak_limit: usize,
}

#[derive(Clone, Debug)]
enum CurrentFreCaptureRegex {
    General(Box<CaptureRegex>),
}

impl CurrentFreCaptureModel {
    fn parse(model: &str) -> Result<Self, CompareError> {
        match model {
            "count-captures" => Ok(Self::CountCaptures),
            "grep-captures" => Ok(Self::GrepCaptures),
            other => Err(CompareError::new(format!(
                "unexpected capture lifecycle model {other}"
            ))),
        }
    }

    const fn as_str(self) -> &'static str {
        match self {
            Self::CountCaptures => "count-captures",
            Self::GrepCaptures => "grep-captures",
        }
    }
}

fn materialized_capture_iteration_error(error: fre::CaptureIterationError) -> ExecutionError {
    let message = format!("FRE materialized capture iteration failed: {error}");
    if !error.has_closed_session_attempt() {
        return ExecutionError::fault(format!(
            "{message}; terminal capture-iteration receipt did not close"
        ));
    }
    match error.source {
        CaptureSearchError::Resource { .. } | CaptureSearchError::Allocation(_) => {
            ExecutionError::unsupported(message)
        }
        CaptureSearchError::BoundOverflow(_)
        | CaptureSearchError::InvalidWindow
        | CaptureSearchError::EmptyMatch
        | CaptureSearchError::InvalidProgram => ExecutionError::fault(message),
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct MaterializedCaptureOperationLedger {
    actual: CaptureIterationActual,
}

impl MaterializedCaptureOperationLedger {
    fn remaining_line_limits(
        self,
        base: CaptureAggregateLimits,
        selector: CaptureSelectorLedger,
        reducer_events: u64,
        limits: &RunLimits,
    ) -> Result<CaptureAggregateLimits, ExecutionError> {
        let (operation_work_after_scan, sequential_after_completed_work) =
            selector.remaining(limits)?;
        let remaining = |capacity: usize, consumed: usize, resource: &str| {
            capacity.checked_sub(consumed).ok_or_else(|| {
                ExecutionError::fault(format!(
                    "FRE materialized capture cumulative {resource} accounting underflow"
                ))
            })
        };
        let total_state_capacity = base.max_total_state_visits.min(operation_work_after_scan);
        let total_slot_capacity = base.max_total_slot_copies.min(operation_work_after_scan);
        let total_node_capacity = base.max_total_history_nodes.min(operation_work_after_scan);
        let total_walk_capacity = base.max_total_history_walk.min(operation_work_after_scan);
        let mut invocation = base;
        invocation.max_searches = remaining(base.max_searches, self.actual.searches, "search")?;
        invocation.max_results = remaining(base.max_results, self.actual.results, "result")?;
        invocation.max_total_state_visits = remaining(
            total_state_capacity,
            self.actual.total_state_visits,
            "state-visit",
        )?
        // Every charged persistent-history byte advance is bounded by its
        // corresponding charged state-visit prospective. Sharing the smaller
        // residual makes the source-read ledger close before the next line
        // can be inspected by the exact matcher.
        .min(sequential_after_completed_work);
        invocation.max_total_slot_copies = remaining(
            total_slot_capacity,
            self.actual.total_slot_copies,
            "slot-copy",
        )?;
        invocation.max_total_history_nodes = remaining(
            total_node_capacity,
            self.actual.total_history_nodes,
            "history-node",
        )?;
        invocation.max_total_history_walk = remaining(
            total_walk_capacity,
            self.actual.total_history_walk,
            "history-walk",
        )?;
        let reducer_remaining = limits
            .reducer_steps
            .checked_sub(reducer_events)
            .and_then(|remaining| usize::try_from(remaining).ok())
            .ok_or_else(|| {
                ExecutionError::fault("FRE materialized capture reducer accounting underflowed")
            })?;
        invocation.max_capture_events = remaining(
            base.max_capture_events,
            self.actual.capture_events,
            "capture-event",
        )?
        .min(reducer_remaining);
        invocation.per_search.max_state_visits = invocation
            .per_search
            .max_state_visits
            .min(invocation.max_total_state_visits);
        invocation.per_search.max_slot_copies = invocation
            .per_search
            .max_slot_copies
            .min(invocation.max_total_slot_copies);
        invocation.per_search.max_history_nodes = invocation
            .per_search
            .max_history_nodes
            .min(invocation.max_total_history_nodes);
        invocation.per_search.max_history_walk = invocation
            .per_search
            .max_history_walk
            .min(invocation.max_total_history_walk);
        Ok(invocation)
    }

    fn charge(&mut self, next: CaptureIterationActual) -> Result<(), ExecutionError> {
        let add = |left: usize, right: usize, resource: &str| {
            left.checked_add(right).ok_or_else(|| {
                ExecutionError::fault(format!(
                    "FRE materialized capture cumulative {resource} overflow"
                ))
            })
        };
        self.actual.searches = add(self.actual.searches, next.searches, "search")?;
        self.actual.materialized_records = add(
            self.actual.materialized_records,
            next.materialized_records,
            "materialized-record",
        )?;
        self.actual.results = add(self.actual.results, next.results, "result")?;
        self.actual.total_state_visits = add(
            self.actual.total_state_visits,
            next.total_state_visits,
            "state-visit",
        )?;
        self.actual.total_slot_copies = add(
            self.actual.total_slot_copies,
            next.total_slot_copies,
            "slot-copy",
        )?;
        self.actual.total_history_nodes = add(
            self.actual.total_history_nodes,
            next.total_history_nodes,
            "history-node",
        )?;
        self.actual.total_history_walk = add(
            self.actual.total_history_walk,
            next.total_history_walk,
            "history-walk",
        )?;
        self.actual.capture_events = add(
            self.actual.capture_events,
            next.capture_events,
            "capture-event",
        )?;
        self.actual.bytes_examined = add(
            self.actual.bytes_examined,
            next.bytes_examined,
            "source-byte",
        )?;
        self.actual.starts_injected = add(
            self.actual.starts_injected,
            next.starts_injected,
            "start-injection",
        )?;
        self.actual.peak_threads = self.actual.peak_threads.max(next.peak_threads);
        self.actual.scratch_bytes = self.actual.scratch_bytes.max(next.scratch_bytes);
        // Each line-local materialized array is fully reduced and dropped
        // before the next invocation, so retained and combined bytes overlap
        // only within one line and compose by maximum rather than addition.
        self.actual.retained_output_bytes = self
            .actual
            .retained_output_bytes
            .max(next.retained_output_bytes);
        self.actual.combined_peak_bytes = self
            .actual
            .combined_peak_bytes
            .max(next.combined_peak_bytes);
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MaterializedCaptureSlotReport {
    count: u64,
    actual: CaptureIterationActual,
    prospective: CaptureIterationProspective,
}

fn count_materialized_capture_slots(
    regex: &CaptureRegex,
    haystack: &[u8],
    run_limits: CaptureAggregateLimits,
    reducer_events: &mut u64,
    limits: &RunLimits,
) -> Result<MaterializedCaptureSlotReport, ExecutionError> {
    let report = regex
        .captures_iter(haystack, run_limits)
        .map_err(materialized_capture_iteration_error)?;
    if !report.has_closed_session_attempt()
        || report.identity.plan != fre::CaptureIterationPlanKind::RestartedPersistentHistory
        || report.identity.run_limits != run_limits
        || report.searches == 0
    {
        return Err(ExecutionError::fault(
            "FRE materialized capture iteration identity did not close",
        ));
    }

    let expected_groups = regex
        .build_report()
        .engine
        .captures
        .checked_add(1)
        .ok_or_else(|| ExecutionError::fault("FRE capture schema overflowed"))?;
    let mut actual = 0_u64;
    let mut inspected = 0_usize;
    for record in &report.captures {
        let overall = record
            .overall()
            .ok_or_else(|| ExecutionError::fault("materialized capture record lacks group zero"))?;
        if overall.start == overall.end {
            return Err(ExecutionError::fault(
                "capture model violated its non-empty-match promise",
            ));
        }
        if record.groups.len() != expected_groups {
            return Err(ExecutionError::fault(
                "materialized capture record has the wrong schema width",
            ));
        }
        for (index, group) in record.groups.iter().enumerate() {
            charge(
                reducer_events,
                1,
                limits.reducer_steps,
                "capture group events",
            )?;
            inspected = inspected
                .checked_add(1)
                .ok_or_else(|| ExecutionError::fault("capture inspection count overflow"))?;
            if usize::try_from(group.index) != Ok(index) {
                return Err(ExecutionError::fault(
                    "materialized capture slots are not in numeric order",
                ));
            }
            if let Some(span) = group.span {
                if span.start > span.end || span.end > haystack.len() {
                    return Err(ExecutionError::fault(
                        "materialized capture slot escaped its haystack",
                    ));
                }
                actual = actual
                    .checked_add(1)
                    .ok_or_else(|| ExecutionError::fault("capture reducer overflow"))?;
            }
        }
    }
    if inspected != report.capture_events {
        return Err(ExecutionError::fault(
            "materialized capture iteration did not inspect every published slot",
        ));
    }
    let receipt_actual = report.session_receipt.actual;
    let operation_prospective = report.session_receipt.prospective.ok_or_else(|| {
        ExecutionError::fault("successful materialized capture iteration omitted its prospective")
    })?;
    if receipt_actual.capture_events != inspected
        || receipt_actual.results != report.captures.len()
        || report.total_state_visits > receipt_actual.total_state_visits
        || report.total_slot_copies > receipt_actual.total_slot_copies
        || report.total_history_nodes > receipt_actual.total_history_nodes
        || report.total_history_walk > receipt_actual.total_history_walk
    {
        return Err(ExecutionError::fault(
            "materialized capture iteration did not publish a complete operation ledger",
        ));
    }
    // The terminal receipt charges every admitted per-search prospective so
    // nested failures remain lossless. Successful outer-operation accounting
    // composes the separately published physical counters instead; charging
    // the conservative prospective again for every completed line would turn
    // independent P bounds into fictitious work. Each physical A is sealed by
    // and componentwise no larger than the retained receipt above.
    let operation_actual = CaptureIterationActual {
        total_state_visits: report.total_state_visits,
        total_slot_copies: report.total_slot_copies,
        total_history_nodes: report.total_history_nodes,
        total_history_walk: report.total_history_walk,
        ..receipt_actual
    };
    Ok(MaterializedCaptureSlotReport {
        count: actual,
        actual: operation_actual,
        prospective: operation_prospective,
    })
}

fn execute_materialized_count_captures(
    regex: &CaptureRegex,
    haystack: &[u8],
    run_limits: CaptureAggregateLimits,
    limits: &RunLimits,
) -> Result<u64, ExecutionError> {
    let mut reducer_events = 0_u64;
    count_materialized_capture_slots(regex, haystack, run_limits, &mut reducer_events, limits)
        .map(|report| report.count)
}

fn execute_materialized_grep_captures(
    regex: &CaptureRegex,
    haystack: &[u8],
    run_limits: CaptureAggregateLimits,
    limits: &RunLimits,
) -> Result<u64, ExecutionError> {
    execute_materialized_grep_captures_inner(
        active_capture_required_literal_plan(regex),
        regex,
        haystack,
        run_limits,
        limits,
    )
    .map(|report| report.count)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MaterializedGrepCaptureExecutionReport {
    count: u64,
    line_domains: usize,
    candidate_domains: usize,
    materialized_domains: usize,
    consolidated_prefilter: bool,
    prefilter_cutover: bool,
    prefilter_transitions: usize,
    prefilter_match_events: usize,
    prefilter_match_events_upper_bound: usize,
    prefilter_sequential_bytes: usize,
    selector: CaptureSelectorLedger,
    materialization: CaptureIterationActual,
    materialization_work_high_water: usize,
    materialization_sequential_high_water: usize,
}

#[allow(
    clippy::too_many_lines,
    reason = "the admitted whole-source literal proof, semantic line ownership and complete materialized-array reducer remain one auditable timed transaction"
)]
fn execute_materialized_grep_captures_inner(
    prefilter: Option<&CaptureRequiredLiteralPlan>,
    regex: &CaptureRegex,
    haystack: &[u8],
    run_limits: CaptureAggregateLimits,
    limits: &RunLimits,
) -> Result<MaterializedGrepCaptureExecutionReport, ExecutionError> {
    let line_partition_prospective =
        if haystack.len() >= CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES {
            if let Some(prefilter) = prefilter {
                prefilter
                    .line_partition_prospective(haystack.len())
                    .map_err(|error| {
                        ExecutionError::fault(format!(
                            "FRE materialized required-literal line prospective failed: {error}"
                        ))
                    })?
            } else {
                None
            }
        } else {
            None
        };
    let mut selector = if let Some(prospective) = line_partition_prospective {
        CaptureSelectorLedger::preflight_lf_and_required_literal(
            haystack.len(),
            prospective.transitions_upper_bound,
            prospective.match_events_upper_bound,
            limits,
        )?
    } else {
        CaptureSelectorLedger::preflight_lf_scan(haystack.len(), limits)?
    };
    let mut prefilter_transitions = 0_usize;
    let mut prefilter_sequential_bytes = 0_usize;
    let mut prefilter_match_events = 0_usize;
    let mut line_matches = match (prefilter, line_partition_prospective) {
        (Some(prefilter), Some(prospective)) => {
            let scan_limits = CaptureRequiredLiteralRunLimits {
                max_transitions: prospective.transitions_upper_bound,
            };
            let scan = prefilter
                .line_partition_matches(haystack, scan_limits)
                .map_err(|error| {
                    ExecutionError::fault(format!(
                        "FRE materialized required-literal scan violated preflight: {error}"
                    ))
                })?
                .ok_or_else(|| {
                    ExecutionError::fault(
                        "FRE materialized required-literal scan changed its construction route",
                    )
                })?;
            if scan.identity().plan != prefilter.build_report().identity
                || scan.identity().build_limits != capture_required_literal_build_limits(limits)
                || scan.identity().operation
                    != CaptureRequiredLiteralSearchOperation::LinePartitionMatchesV1
                || scan.identity().run_limits != scan_limits
                || scan.accounting() != prospective
            {
                return Err(ExecutionError::fault(
                    "FRE materialized required-literal scan failed identity/P/A authentication",
                ));
            }
            prefilter_transitions = prospective.transitions_upper_bound;
            prefilter_sequential_bytes = prospective.searched_bytes;
            Some(scan.peekable())
        }
        (None, None) | (Some(_), None) => None,
        (None, Some(_)) => {
            return Err(ExecutionError::fault(
                "FRE materialized required-literal prospective has no owning plan",
            ));
        }
    };

    let mut actual = 0_u64;
    let mut reducer_events = 0_u64;
    let mut raw_cursor = 0_usize;
    let mut line_domains = 0_usize;
    let mut candidate_domains = 0_usize;
    let mut materialized_domains = 0_usize;
    let mut materialization = MaterializedCaptureOperationLedger::default();
    let mut materialization_work_high_water = 0_usize;
    let mut materialization_sequential_high_water = selector.sequential_bytes;
    let mut prefilter_cutover = false;
    for raw_line in haystack.lines_with_terminator() {
        let line_start = raw_cursor;
        raw_cursor = raw_cursor
            .checked_add(raw_line.len())
            .ok_or_else(|| ExecutionError::fault("materialized capture raw cursor overflow"))?;
        let line = if let Some(without_lf) = raw_line.strip_suffix(b"\n") {
            without_lf.strip_suffix(b"\r").unwrap_or(without_lf)
        } else {
            raw_line
        };
        let line_end = line_start
            .checked_add(line.len())
            .ok_or_else(|| ExecutionError::fault("materialized capture line end overflow"))?;
        line_domains =
            checked_aggregate_add(line_domains, 1, "materialized grep-captures line domains")?;
        charge(
            &mut reducer_events,
            1,
            limits.reducer_steps,
            "grep-captures line events",
        )?;
        let mut cut_over_after_candidate = false;
        let candidate = if let Some(matches) = line_matches.as_mut() {
            let mut candidate = false;
            while matches.peek().is_some_and(|&(start, _)| start < raw_cursor) {
                let (start, end) = matches.next().ok_or_else(|| {
                    ExecutionError::fault("materialized required-literal peeked match disappeared")
                })?;
                prefilter_match_events = checked_aggregate_add(
                    prefilter_match_events,
                    1,
                    "materialized required-literal match events",
                )?;
                if start < line_start || start >= end || end > line_end {
                    return Err(ExecutionError::fault(
                        "materialized required-literal match escaped its semantic line",
                    ));
                }
                let first_candidate_match = !candidate;
                candidate = true;
                if first_candidate_match
                    && current_fre_grep_should_cut_over_prefilter(
                        line_domains,
                        candidate_domains.saturating_add(1),
                    )
                {
                    // The exact materialized matcher remains authoritative.
                    // Stop before peeking for another literal occurrence: a
                    // dense prefix proves that scanning the remaining source
                    // cannot amortize a second full pass. The complete scan
                    // prospective was already charged before source access.
                    cut_over_after_candidate = true;
                    break;
                }
            }
            candidate
        } else {
            true
        };
        if !candidate {
            continue;
        }
        candidate_domains = checked_aggregate_add(
            candidate_domains,
            1,
            "materialized grep-captures candidate domains",
        )?;
        if cut_over_after_candidate {
            line_matches = None;
            prefilter_cutover = true;
        }
        let line_run_limits =
            materialization.remaining_line_limits(run_limits, selector, reducer_events, limits)?;
        let line_report = count_materialized_capture_slots(
            regex,
            line,
            line_run_limits,
            &mut reducer_events,
            limits,
        )?;
        let prospective = line_report.prospective.engine;
        for (completed, next, resource) in [
            (
                materialization.actual.total_state_visits,
                prospective.total_state_visits,
                "state-visit prospective",
            ),
            (
                materialization.actual.total_slot_copies,
                prospective.total_slot_copies,
                "slot-copy prospective",
            ),
            (
                materialization.actual.total_history_nodes,
                prospective.total_history_nodes,
                "history-node prospective",
            ),
            (
                materialization.actual.total_history_walk,
                prospective.total_history_walk,
                "history-walk prospective",
            ),
        ] {
            let high_water = completed.checked_add(next).ok_or_else(|| {
                ExecutionError::fault(format!(
                    "FRE materialized capture cumulative {resource} overflow"
                ))
            })?;
            materialization_work_high_water = materialization_work_high_water.max(high_water);
        }
        let sequential_high_water = selector
            .sequential_bytes
            .checked_add(prospective.total_state_visits)
            .ok_or_else(|| {
                ExecutionError::fault("FRE materialized capture sequential prospective overflow")
            })?;
        materialization_sequential_high_water =
            materialization_sequential_high_water.max(sequential_high_water);
        materialization.charge(line_report.actual)?;
        // The exact array report publishes its cumulative byte-advance
        // prospective. Charge it into the same complete-operation sequential
        // ledger as LF partitioning and the optional literal traversal.
        selector.charge(0, 0, line_report.actual.bytes_examined, limits)?;
        materialized_domains = checked_aggregate_add(
            materialized_domains,
            1,
            "materialized grep-captures executions",
        )?;
        actual = actual
            .checked_add(line_report.count)
            .ok_or_else(|| ExecutionError::fault("grep-captures reducer overflow"))?;
    }
    if raw_cursor != haystack.len() {
        return Err(ExecutionError::fault(
            "materialized capture line iterator did not consume the complete source",
        ));
    }
    if let Some(matches) = line_matches.as_mut()
        && matches.next().is_some()
    {
        return Err(ExecutionError::fault(
            "materialized required-literal match was not assigned to a semantic line",
        ));
    }
    let prefilter_match_events_upper_bound =
        line_partition_prospective.map_or(0, |prospective| prospective.match_events_upper_bound);
    if line_partition_prospective.is_some()
        && (prefilter_match_events > prefilter_match_events_upper_bound
            || prefilter_sequential_bytes > haystack.len())
    {
        return Err(ExecutionError::fault(
            "materialized required-literal scan exceeded its prospective",
        ));
    }
    if materialized_domains != candidate_domains || candidate_domains > line_domains {
        return Err(ExecutionError::fault(
            "materialized grep-captures domain cardinality invariant failed",
        ));
    }
    for (resource, consumed) in [
        ("state visits", materialization.actual.total_state_visits),
        ("slot copies", materialization.actual.total_slot_copies),
        ("history nodes", materialization.actual.total_history_nodes),
        ("history walk", materialization.actual.total_history_walk),
    ] {
        let combined = selector
            .work
            .checked_add(consumed)
            .ok_or_else(|| ExecutionError::fault("materialized operation work overflow"))?;
        if combined > limits.fre_aggregate_operation_work {
            return Err(ExecutionError::fault(format!(
                "FRE materialized capture scan plus cumulative {resource} exceeded its public-operation envelope"
            )));
        }
    }
    Ok(MaterializedGrepCaptureExecutionReport {
        count: actual,
        line_domains,
        candidate_domains,
        materialized_domains,
        consolidated_prefilter: line_partition_prospective.is_some(),
        prefilter_cutover,
        prefilter_transitions,
        prefilter_match_events,
        prefilter_match_events_upper_bound,
        prefilter_sequential_bytes,
        selector,
        materialization: materialization.actual,
        materialization_work_high_water,
        materialization_sequential_high_water,
    })
}

/// One already-built capture artifact at the public operation lifecycle
/// boundary used by the authenticated current-FRE Rebar adapter.
///
/// The first call to [`Self::execute`] is the contracted first-operation
/// boundary. Later calls on the same value are steady-operation boundaries.
/// Construction and input loading are outside both boundaries.
#[derive(Debug)]
pub struct CurrentFreCaptureLifecycle {
    model: CurrentFreCaptureModel,
    regex: CurrentFreCaptureRegex,
    limits: RunLimits,
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
    preparation: CurrentFreCapturePreparation,
}

impl CurrentFreCaptureLifecycle {
    /// Exact Rebar model bound into this lifecycle producer.
    #[must_use]
    pub const fn model(&self) -> &'static str {
        self.model.as_str()
    }

    /// Stable authenticated plan label expected by the timing runner.
    #[must_use]
    pub fn plan(&self) -> &'static str {
        CURRENT_FRE_CAPTURE_MATERIALIZED_PLAN
    }

    /// Exact Rust-regex Unicode option bound at construction.
    #[must_use]
    pub const fn unicode(&self) -> bool {
        self.unicode
    }

    /// Exact Rust-regex case-insensitive option bound at construction.
    #[must_use]
    pub const fn case_insensitive(&self) -> bool {
        self.case_insensitive
    }

    /// Execute one complete public model operation on the retained artifact.
    ///
    /// # Errors
    ///
    /// Returns an error if checked reducer limits or the capture engine refuse
    /// the operation, or if the input length differs from the authenticated
    /// preparation. No alternate implementation is selected.
    pub fn execute(&mut self, haystack: &[u8]) -> Result<u64, CompareError> {
        if haystack.len() != self.haystack_len {
            return Err(CompareError::new(format!(
                "capture lifecycle haystack length {} differs from prepared {}",
                haystack.len(),
                self.haystack_len
            )));
        }
        let result = match (&self.regex, self.preparation) {
            (
                CurrentFreCaptureRegex::General(regex),
                CurrentFreCapturePreparation::MaterializedWhole(run_limits),
            ) => execute_materialized_count_captures(regex, haystack, run_limits, &self.limits),
            (
                CurrentFreCaptureRegex::General(regex),
                CurrentFreCapturePreparation::MaterializedLines(run_limits),
            ) => execute_materialized_grep_captures(regex, haystack, run_limits, &self.limits),
        };
        result.map_err(|error| CompareError::new(error.message))
    }
}

/// Construct the exact capture lifecycle producer used by the authenticated
/// current-FRE Rebar adapter.
///
/// # Errors
///
/// `haystack_len` binds checked operation limits before the lifecycle boundary.
/// Returns an error for a non-capture model, unsupported syntax/profile, or an
/// unexpected capture plan identity. It never substitutes another engine.
pub fn current_fre_rebar_capture_lifecycle(
    model: &str,
    pattern: &str,
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
) -> Result<CurrentFreCaptureLifecycle, CompareError> {
    current_fre_rebar_capture_lifecycle_with_limits(
        model,
        pattern,
        unicode,
        case_insensitive,
        haystack_len,
        RunLimits::default(),
    )
}

fn current_fre_rebar_capture_lifecycle_with_limits(
    model: &str,
    pattern: &str,
    unicode: bool,
    case_insensitive: bool,
    haystack_len: usize,
    limits: RunLimits,
) -> Result<CurrentFreCaptureLifecycle, CompareError> {
    let model = CurrentFreCaptureModel::parse(model)?;
    let regex = match model {
        CurrentFreCaptureModel::CountCaptures => {
            capture_regex_one(pattern, unicode, case_insensitive, &limits)
        }
        CurrentFreCaptureModel::GrepCaptures => {
            capture_grep_regex_one(pattern, unicode, case_insensitive, &limits)
        }
    }
    .map_err(|error| CompareError::new(error.message))?;
    let run_limits = capture_count_run_limits(&regex, haystack_len, &limits)
        .map_err(|error| CompareError::new(error.message))?
        .aggregate;
    let preparation = match model {
        CurrentFreCaptureModel::CountCaptures => {
            CurrentFreCapturePreparation::MaterializedWhole(run_limits)
        }
        CurrentFreCaptureModel::GrepCaptures => {
            CurrentFreCapturePreparation::MaterializedLines(run_limits)
        }
    };
    Ok(CurrentFreCaptureLifecycle {
        model,
        regex: CurrentFreCaptureRegex::General(Box::new(regex)),
        limits,
        unicode,
        case_insensitive,
        haystack_len,
        preparation,
    })
}

/// Derive whole-operation limits for a report-authenticated aggregate plan.
/// Every Unicode-scalar, prefix/class, literal/class-run/literal, bounded-
/// context, and fixed absolute-domain plan requires the retained artifact.
/// The copied report intentionally cannot distinguish scalar from private
/// dispatched owners, so callers for any of those families must use
/// [`current_fre_rebar_compile_run_limits`],
/// [`current_fre_rebar_count_run_limits`] or
/// [`current_fre_generic_span_sum_run_limits`] instead.
///
/// # Errors
///
/// Returns an authentication/resource error if a bound cannot be represented.
pub fn current_fre_rebar_aggregate_run_limits(
    haystack_len: usize,
    report: &AggregateBuildReport,
) -> Result<AggregateRunLimits, CompareError> {
    aggregate_run_limits(haystack_len, report, &RunLimits::default())
        .map_err(|error| CompareError::new(error.message))
}

fn compile_run_limits_with_policy(
    haystack_len: usize,
    regex: &AggregateCompileRegex,
    limits: &RunLimits,
) -> Result<AggregateRunLimits, ExecutionError> {
    let retained_upper_bounds = regex
        .retained_full_window_upper_bounds(haystack_len)
        .map_err(|error| {
            ExecutionError::fault(format!("FRE compile retained-owner preflight: {error}"))
        })?;
    let fixed_absolute_prospective = regex
        .fixed_absolute_domain_full_window_prospective(haystack_len)
        .map_err(|error| {
            ExecutionError::fault(format!("FRE compile fixed-domain preflight: {error}"))
        })?;
    let fixed_absolute_composite = regex
        .fixed_absolute_domain_full_window_composite_prospective(haystack_len)
        .map_err(|error| {
            ExecutionError::fault(format!(
                "FRE compile fixed-domain composite preflight: {error}"
            ))
        })?;
    aggregate_run_limits_with_fixed_absolute(
        haystack_len,
        regex.build_report(),
        retained_upper_bounds,
        fixed_absolute_prospective,
        fixed_absolute_composite,
        None,
        limits,
    )
}

