    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the fail-closed adapter audit keeps all receipt mutations in one test"
    )]
    fn rust_functions_direct_receipts_fail_closed_in_adapter() {
        let pattern = r"fn is_(\w+)|fn as_(\w+)";
        let haystack = b"fn is_alpha fn as_beta";
        let adapter_limits = RunLimits::default();
        let regex = capture_regex_one(pattern, false, false, &adapter_limits)
            .expect("direct capture artifact");
        let run_limits = capture_count_run_limits(&regex, haystack.len(), &adapter_limits)
            .expect("direct run limits");
        let retained = regex
            .retained_prefix_class_participation_prospective(haystack.len())
            .expect("direct retained envelope")
            .expect("direct artifact");
        assert_eq!(
            run_limits
                .prefix_class_participation
                .max_greedy_extension_reads,
            retained.greedy_extension_reads
        );
        assert_eq!(
            run_limits.prefix_class_participation.max_work,
            retained.work
        );
        let result = regex
            .count_captures(haystack, run_limits)
            .expect("direct capture result");
        assert!(authenticates_direct_capture_success(
            &regex,
            haystack.len(),
            &run_limits,
            &result
        ));
        let mut forged_success = result.clone();
        forged_success
            .prefix_class_participation_receipt
            .as_mut()
            .expect("direct success receipt")
            .actual_allocations = 1;
        assert!(!authenticates_direct_capture_success(
            &regex,
            haystack.len(),
            &run_limits,
            &forged_success
        ));

        let prospective = result
            .prefix_class_participation
            .expect("direct success accounting")
            .prospective;
        assert_eq!(prospective, retained);
        let mut greedy_one_below = run_limits;
        greedy_one_below
            .prefix_class_participation
            .max_greedy_extension_reads = prospective.greedy_extension_reads - 1;
        let greedy_terminal = regex
            .count_captures(haystack, greedy_one_below)
            .expect_err("direct greedy-extension one-below");
        assert!(matches!(
            greedy_terminal.source,
            fre::CaptureExecutionSource::PrefixClassParticipation(
                fre::PrefixClassUniformParticipationError::GreedyExtensionReadsLimit {
                    needed,
                    limit,
                }
            ) if needed == prospective.greedy_extension_reads
                && limit == prospective.greedy_extension_reads - 1
        ));
        assert!(authenticates_direct_capture_error(
            &regex,
            haystack.len(),
            &greedy_one_below,
            &greedy_terminal
        ));
        let mut one_below = run_limits;
        one_below.prefix_class_participation.max_work = prospective.work - 1;
        let terminal = regex
            .count_captures(haystack, one_below)
            .expect_err("direct one-below");
        assert!(authenticates_direct_capture_error(
            &regex,
            haystack.len(),
            &one_below,
            &terminal
        ));
        assert_eq!(
            capture_execution_error(
                &regex,
                haystack.len(),
                &one_below,
                &terminal,
                "valid direct refusal".to_string(),
            )
            .status,
            Status::Unsupported
        );
        let mut forged_terminal = terminal;
        forged_terminal
            .prefix_class_participation_receipt
            .as_mut()
            .expect("direct terminal receipt")
            .prospective = None;
        assert!(!authenticates_direct_capture_error(
            &regex,
            haystack.len(),
            &one_below,
            &forged_terminal
        ));
        assert_eq!(
            capture_execution_error(
                &regex,
                haystack.len(),
                &one_below,
                &forged_terminal,
                "forged direct refusal".to_string(),
            )
            .status,
            Status::Fault
        );
    }

    #[test]
    fn required_literal_capture_lifecycle_is_single_build_exact_and_bounded() {
        const AWS: &str = r#"(('|")((?:ASIA|AKIA|AROA|AIDA)([A-Z0-7]{16}))('|").*?(\n^.*?){0,4}(('|")[a-zA-Z0-9+/]{40}('|"))+|('|")[a-zA-Z0-9+/]{40}('|").*?(\n^.*?){0,3}('|")((?:ASIA|AKIA|AROA|AIDA)([A-Z0-7]{16}))('|"))+"#;
        let haystack = b"miss\n\xFF no key\n\"AKIAIOSFODNN7EXAMPLE\" \"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"";
        let upstream = rust_compile_options(&[AWS.to_string()], false, false)
            .expect("pinned Rust AWS pattern");
        let expected =
            grep_captures(&upstream, haystack, u64::MAX).expect("Rust AWS grep-captures");
        assert_eq!(expected, 9);
        let mut lifecycle =
            current_fre_rebar_capture_lifecycle("grep-captures", AWS, false, false, haystack.len())
                .expect("required-literal lifecycle");
        assert_eq!(lifecycle.plan(), CURRENT_FRE_CAPTURE_MATERIALIZED_PLAN);
        assert!(is_current_fre_capture_route(
            lifecycle.model(),
            lifecycle.plan()
        ));
        assert_eq!(lifecycle.execute(haystack).expect("first"), expected);
        assert_eq!(lifecycle.execute(haystack).expect("steady"), expected);

        let accounting_regex = capture_grep_regex_one(AWS, false, false, &RunLimits::default())
            .expect("required-literal accounting fixture");
        let accounting_prefilter = active_capture_required_literal_plan(&accounting_regex)
            .expect("AWS required-literal proof");
        for miss in [b"".as_slice(), b"xx\n".as_slice()] {
            let prospective = accounting_prefilter
                .line_partition_prospective(miss.len())
                .expect("small line prospective")
                .expect("AWS literals contain no line terminators");
            let work = miss
                .len()
                .checked_add(prospective.transitions_upper_bound)
                .and_then(|value| value.checked_add(prospective.match_events_upper_bound))
                .expect("small prefilter work");
            let sequential = miss.len().checked_mul(2).expect("small sequential");
            let exact = RunLimits {
                fre_aggregate_operation_work: work,
                fre_aggregate_sequential_bytes: sequential,
                ..RunLimits::default()
            };
            assert_eq!(
                execute_grep_captures_inner(
                    Some(accounting_prefilter),
                    &accounting_regex,
                    miss,
                    &exact,
                )
                .expect("exact generic required-literal execution")
                .count,
                0
            );

            let work_one_below = RunLimits {
                fre_aggregate_operation_work: work
                    .checked_sub(1)
                    .expect("required initial transition"),
                ..exact.clone()
            };
            assert!(
                execute_grep_captures_inner(
                    Some(accounting_prefilter),
                    &accounting_regex,
                    miss,
                    &work_one_below,
                )
                .expect_err("one-below generic work must refuse")
                .message
                .contains("required-literal scans require")
            );
            if sequential > 0 {
                let sequential_one_below = RunLimits {
                    fre_aggregate_sequential_bytes: sequential - 1,
                    ..exact
                };
                assert!(
                    execute_grep_captures_inner(
                        Some(accounting_prefilter),
                        &accounting_regex,
                        miss,
                        &sequential_one_below,
                    )
                    .expect_err("one-below generic sequential budget must refuse")
                    .message
                    .contains("sequential bytes")
                );
            }
        }
    }

    #[test]
    fn required_literal_activation_includes_effective_singletons() {
        let haystack = b"AB\nXAB\nCD\nmiss";
        for pattern in ["(?:(AB)|(AB))", "(?:(AB)|(XAB))"] {
            let generic = capture_grep_regex_one(pattern, false, false, &RunLimits::default())
                .expect("generic effective-singleton capture artifact");
            assert!(active_capture_required_literal_plan(&generic).is_some());
            let upstream = rust_compile_options(&[pattern.to_string()], false, false)
                .expect("pinned Rust redundant capture pattern");
            let expected =
                grep_captures(&upstream, haystack, u64::MAX).expect("Rust redundant grep-captures");
            let mut lifecycle = current_fre_rebar_capture_lifecycle(
                "grep-captures",
                pattern,
                false,
                false,
                haystack.len(),
            )
            .expect("effective singleton required-literal route");
            assert_eq!(lifecycle.plan(), CURRENT_FRE_CAPTURE_MATERIALIZED_PLAN);
            assert_eq!(
                lifecycle.execute(haystack).expect("singleton execution"),
                expected
            );
        }

        let distinct = "(?:(AB)|(CD))";
        let upstream = rust_compile_options(&[distinct.to_string()], false, false)
            .expect("pinned Rust distinct capture pattern");
        let expected =
            grep_captures(&upstream, haystack, u64::MAX).expect("Rust distinct grep-captures");
        let generic = capture_grep_regex_one(distinct, false, false, &RunLimits::default())
            .expect("generic distinct required-literal artifact");
        assert!(active_capture_required_literal_plan(&generic).is_some());
        let mut active = current_fre_rebar_capture_lifecycle(
            "grep-captures",
            distinct,
            false,
            false,
            haystack.len(),
        )
        .expect("distinct effective antichain lifecycle");
        assert_eq!(active.plan(), CURRENT_FRE_CAPTURE_MATERIALIZED_PLAN);
        assert_eq!(
            active.execute(haystack).expect("prefilter execution"),
            expected
        );

        let refused_limits = RunLimits {
            fre_literal_build_needle_bytes: 3,
            ..RunLimits::default()
        };
        let generic_fallback = capture_grep_regex_one(distinct, false, false, &refused_limits)
            .expect("optional generic required-literal refusal");
        assert!(active_capture_required_literal_plan(&generic_fallback).is_none());
        let mut fallback = current_fre_rebar_capture_lifecycle_with_limits(
            "grep-captures",
            distinct,
            false,
            false,
            haystack.len(),
            refused_limits,
        )
        .expect("optional effective-set refusal preserves capture lifecycle");
        assert_eq!(fallback.plan(), CURRENT_FRE_CAPTURE_MATERIALIZED_PLAN);
        assert_eq!(
            fallback
                .execute(haystack)
                .expect("resource fallback execution"),
            expected
        );
    }

    #[test]
    fn materialized_required_literal_prefilter_preserves_three_capture_families() {
        let fixtures: &[(&str, &[u8])] = &[
            (
                r"(?P<head>HEAD)(?P<digits>[0-9]+)?",
                b"miss\nHEAD\nHEAD42\r\nnot HEAD!\n\xFFtail",
            ),
            (
                r"(?:(foo)(bar)|(zip)(zap))",
                b"none\nfoobar\nzipzap\r\nfoo zip\n\xFFfoobar",
            ),
            (
                r"^([a-z]+)::(TOKEN)(?:=([0-9]+))?$",
                b"miss\nalpha::TOKEN\nbeta::TOKEN=17\r\nTOKEN\ngamma::TOKEN=x\n\xFF::TOKEN",
            ),
        ];
        let limits = RunLimits::default();
        for &(pattern, seed) in fixtures {
            let haystack = seed.repeat(64);
            let haystack = haystack.as_slice();
            let regex = capture_grep_regex_one(pattern, false, false, &limits)
                .unwrap_or_else(|error| panic!("pattern={pattern:?}: {}", error.message));
            let prefilter = active_capture_required_literal_plan(&regex)
                .unwrap_or_else(|| panic!("pattern={pattern:?} has no required-literal proof"));
            assert!(
                prefilter
                    .line_partition_prospective(haystack.len())
                    .expect("line-partition prospective")
                    .is_some(),
                "pattern={pattern:?}"
            );
            let run_limits = capture_count_run_limits(&regex, haystack.len(), &limits)
                .expect("materialized run limits")
                .aggregate;
            let baseline = execute_materialized_grep_captures_inner(
                None, &regex, haystack, run_limits, &limits,
            )
            .expect("unfiltered complete materialization");
            let filtered = execute_materialized_grep_captures_inner(
                Some(prefilter),
                &regex,
                haystack,
                run_limits,
                &limits,
            )
            .expect("required-literal complete materialization");
            assert_eq!(filtered.count, baseline.count, "pattern={pattern:?}");
            assert_eq!(filtered.line_domains, baseline.line_domains);
            assert!(filtered.consolidated_prefilter);
            assert!(filtered.candidate_domains > 0, "pattern={pattern:?}");
            assert!(
                filtered.candidate_domains < filtered.line_domains,
                "pattern={pattern:?}"
            );
            assert_eq!(filtered.materialized_domains, filtered.candidate_domains);
            assert_eq!(baseline.materialized_domains, baseline.line_domains);

            // Independently compare every canonical materialized record—not
            // only the scalar reducer—after the same HIR-derived candidate
            // decision. Miss-only lines add no records to the complete oracle.
            let mut all_records = Vec::new();
            let mut candidate_records = Vec::new();
            for line in haystack.lines() {
                let records = regex
                    .captures_iter(line, run_limits)
                    .expect("complete materialized capture report")
                    .captures;
                all_records.extend(records.iter().cloned());
                let decision = prefilter
                    .is_candidate(
                        line,
                        CaptureRequiredLiteralRunLimits {
                            max_transitions: line.len().saturating_add(1),
                        },
                    )
                    .expect("line candidate decision");
                if decision.candidate {
                    candidate_records.extend(records);
                }
            }
            assert_eq!(candidate_records, all_records, "pattern={pattern:?}");
        }
    }

    #[test]
    fn materialized_required_literal_prefilter_cuts_over_dense_and_skips_tiny_sources() {
        let limits = RunLimits::default();
        let pattern = r"(a)(b)?";
        let regex = capture_grep_regex_one(pattern, false, false, &limits)
            .expect("dense materialized capture fixture");
        let prefilter = active_capture_required_literal_plan(&regex)
            .expect("dense fixture required-literal proof");

        let dense = b"ab\n".repeat(1_024);
        let dense_limits = capture_count_run_limits(&regex, dense.len(), &limits)
            .expect("dense materialized limits")
            .aggregate;
        let dense_report = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &dense,
            dense_limits,
            &limits,
        )
        .expect("dense materialized capture execution");
        let dense_baseline =
            execute_materialized_grep_captures_inner(None, &regex, &dense, dense_limits, &limits)
                .expect("dense unfiltered materialization");
        assert_eq!(dense_report.count, dense_baseline.count);
        assert!(dense_report.consolidated_prefilter);
        assert!(dense_report.prefilter_cutover);
        assert_eq!(dense_report.materialized_domains, dense_report.line_domains);

        let tiny = b"ab\nmiss";
        let tiny_limits = capture_count_run_limits(&regex, tiny.len(), &limits)
            .expect("tiny materialized limits")
            .aggregate;
        let tiny_report = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            tiny,
            tiny_limits,
            &limits,
        )
        .expect("tiny materialized capture execution");
        assert!(!tiny_report.consolidated_prefilter);
        assert!(!tiny_report.prefilter_cutover);
        assert_eq!(tiny_report.materialized_domains, tiny_report.line_domains);
    }

    #[test]
    fn materialized_required_literal_prefilter_preflights_one_below_and_refuses_to_fallback() {
        let pattern = r"(TOKEN)([0-9]+)?";
        let haystack = b"miss\n".repeat(512);
        let defaults = RunLimits::default();
        let regex = capture_grep_regex_one(pattern, false, false, &defaults)
            .expect("sparse materialized capture fixture");
        let prefilter = active_capture_required_literal_plan(&regex)
            .expect("sparse fixture required-literal proof");
        let prospective = prefilter
            .line_partition_prospective(haystack.len())
            .expect("sparse prefilter prospective")
            .expect("literal excludes semantic line delimiters");
        let exact_work = haystack
            .len()
            .checked_add(prospective.transitions_upper_bound)
            .and_then(|work| work.checked_add(prospective.match_events_upper_bound))
            .expect("exact scan work");
        let exact_sequential = haystack.len().checked_mul(2).expect("exact scan bytes");
        let exact_limits = RunLimits {
            fre_aggregate_operation_work: exact_work,
            fre_aggregate_sequential_bytes: exact_sequential,
            ..defaults.clone()
        };
        let run_limits = capture_count_run_limits(&regex, haystack.len(), &exact_limits)
            .expect("exact materialized run limits")
            .aggregate;
        let exact = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &haystack,
            run_limits,
            &exact_limits,
        )
        .expect("exact admitted sparse scan");
        assert_eq!(exact.count, 0);
        assert_eq!(exact.candidate_domains, 0);
        assert_eq!(exact.materialized_domains, 0);

        let work_one_below = RunLimits {
            fre_aggregate_operation_work: exact_work - 1,
            ..exact_limits.clone()
        };
        let error = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &haystack,
            run_limits,
            &work_one_below,
        )
        .expect_err("one-below work must refuse before the scan");
        assert_eq!(error.status, Status::Unsupported);
        assert!(error.message.contains("required-literal scans require"));

        let sequential_one_below = RunLimits {
            fre_aggregate_sequential_bytes: exact_sequential - 1,
            ..exact_limits
        };
        let error = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &haystack,
            run_limits,
            &sequential_one_below,
        )
        .expect_err("one-below sequential bytes must refuse before the scan");
        assert_eq!(error.status, Status::Unsupported);
        assert!(error.message.contains("sequential bytes"));

        let refused_limits = RunLimits {
            fre_literal_build_needle_bytes: 1,
            ..defaults
        };
        let fallback = capture_grep_regex_one(pattern, false, false, &refused_limits)
            .expect("optional prefilter refusal retains materialized capture artifact");
        assert!(active_capture_required_literal_plan(&fallback).is_none());
        let fallback_run_limits =
            capture_count_run_limits(&fallback, haystack.len(), &refused_limits)
                .expect("fallback materialized run limits")
                .aggregate;
        let fallback_report = execute_materialized_grep_captures_inner(
            None,
            &fallback,
            &haystack,
            fallback_run_limits,
            &refused_limits,
        )
        .expect("refused prefilter executes complete materialized fallback");
        assert_eq!(
            fallback_report.materialized_domains,
            fallback_report.line_domains
        );
    }

    #[test]
    fn materialized_required_literal_prefilter_closes_combined_operation_ledger() {
        let pattern = r"(TOKEN)([0-9]+)?";
        let mut haystack = b"miss\n".repeat(512);
        haystack.extend_from_slice(b"TOKEN42\n");
        let defaults = RunLimits::default();
        let regex = capture_grep_regex_one(pattern, false, false, &defaults)
            .expect("combined-ledger materialized capture fixture");
        let prefilter = active_capture_required_literal_plan(&regex)
            .expect("combined-ledger fixture required-literal proof");
        let permissive_run_limits = capture_count_run_limits(&regex, haystack.len(), &defaults)
            .expect("permissive combined-ledger run limits")
            .aggregate;
        let permissive = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &haystack,
            permissive_run_limits,
            &defaults,
        )
        .expect("permissive combined-ledger execution");
        assert_eq!(permissive.candidate_domains, 1);
        assert_eq!(permissive.materialized_domains, 1);
        assert!(permissive.materialization.capture_events > 0);
        assert!(
            permissive.materialization.bytes_examined
                <= permissive.materialization.total_state_visits
        );

        let exact_work = permissive
            .selector
            .work
            .checked_add(permissive.materialization_work_high_water)
            .expect("exact combined operation work");
        let exact_sequential = permissive.materialization_sequential_high_water;
        let exact_limits = RunLimits {
            fre_aggregate_operation_work: exact_work,
            fre_aggregate_sequential_bytes: exact_sequential,
            ..defaults
        };
        let exact_run_limits = capture_count_run_limits(&regex, haystack.len(), &exact_limits)
            .expect("exact combined-ledger run limits")
            .aggregate;
        let exact = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &haystack,
            exact_run_limits,
            &exact_limits,
        )
        .expect("exact combined scan and materialization envelope");
        assert_eq!(exact.count, permissive.count);
        assert_eq!(exact.materialization, permissive.materialization);

        let one_below = RunLimits {
            fre_aggregate_operation_work: exact_work - 1,
            ..exact_limits
        };
        let one_below_run_limits = capture_count_run_limits(&regex, haystack.len(), &one_below)
            .expect("one-below outer limits remain representable")
            .aggregate;
        let error = execute_materialized_grep_captures_inner(
            Some(prefilter),
            &regex,
            &haystack,
            one_below_run_limits,
            &one_below,
        )
        .expect_err("one-below combined work must refuse exact materialization");
        assert_eq!(error.status, Status::Unsupported);
        assert!(
            error
                .message
                .contains("materialized capture iteration failed")
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one table-driven test authenticates line semantics, selector cardinality, and exact cumulative boundaries together"
    )]
    fn required_literal_line_stream_preserves_domains_priority_and_accounting() {
        const PATTERN: &str = r"(?:(ABC)|(AB)(C)|(XY))";
        let defaults = RunLimits::default();
        let regex = capture_grep_regex_one(PATTERN, false, false, &defaults)
            .expect("generic variable-participation capture fixture");
        let prefilter = active_capture_required_literal_plan(&regex)
            .expect("fixture has a same-HIR required-literal proof");
        assert_eq!(
            capture_plan_label(&regex),
            CURRENT_FRE_CAPTURE_REQUIRED_LITERAL_PLAN
        );
        let upstream = rust_compile_options(&[PATTERN.to_string()], false, false)
            .expect("pinned Rust source-priority fixture");
        let cases: &[(&[u8], usize, usize, usize)] = &[
            (b"", 0, 0, 0),
            (b"\n", 0, 1, 0),
            (b"\n\n", 0, 2, 0),
            (b"ABC\n", 1, 1, 1),
            (b"ABC\r\n", 1, 1, 1),
            (b"ABC\n\n", 1, 2, 1),
            (b"A\nBC", 0, 2, 0),
            (b"\xFFABC\r\nA\xFFB\nXY\x80", 2, 3, 2),
            (b"ABCABC", 1, 1, 2),
        ];
        for &(haystack, candidate_domains, line_domains, match_events) in cases {
            let expected =
                grep_captures(&upstream, haystack, u64::MAX).expect("Rust grep-captures");
            let mut lifecycle = current_fre_rebar_capture_lifecycle(
                "grep-captures",
                PATTERN,
                false,
                false,
                haystack.len(),
            )
            .expect("strict Rebar capture lifecycle");
            assert_eq!(lifecycle.plan(), CURRENT_FRE_REBAR_GREP_CAPTURES_PLAN);
            assert_eq!(
                lifecycle
                    .execute(haystack)
                    .expect("first strict capture iteration"),
                expected,
                "first batch mismatch for {haystack:?}"
            );
            assert_eq!(
                lifecycle
                    .execute(haystack)
                    .expect("steady strict capture iteration"),
                expected,
                "steady batch mismatch for {haystack:?}"
            );
            let first = execute_grep_captures_inner(Some(prefilter), &regex, haystack, &defaults)
                .expect("first consolidated line execution");
            let steady = execute_grep_captures_inner(Some(prefilter), &regex, haystack, &defaults)
                .expect("steady consolidated line execution");
            assert_eq!(first, steady, "retained execution changed for {haystack:?}");
            assert_eq!(first.count, expected, "semantic mismatch for {haystack:?}");
            assert_eq!(first.line_domains, line_domains, "{haystack:?}");
            assert_eq!(first.candidate_domains, candidate_domains, "{haystack:?}");
            assert_eq!(
                first.selector_executions, candidate_domains,
                "one selector execution is required per surviving domain: {haystack:?}"
            );
            assert!(first.consolidated_prefilter, "{haystack:?}");
            let prospective = prefilter
                .line_partition_prospective(haystack.len())
                .unwrap()
                .unwrap();
            assert_eq!(
                first.prefilter_transitions,
                prospective.transitions_upper_bound
            );
            assert_eq!(first.prefilter_match_events, match_events);
            assert_eq!(
                first.prefilter_match_events_upper_bound,
                prospective.match_events_upper_bound
            );
            assert_eq!(first.prefilter_sequential_bytes, haystack.len());
        }
        assert_eq!(
            execute_grep_captures_inner(Some(prefilter), &regex, b"ABC", &defaults)
                .unwrap()
                .count,
            2,
            "leftmost first arm contributes only overall plus its one capture"
        );
        assert_eq!(
            execute_grep_captures_inner(Some(prefilter), &regex, b"ABCABC", &defaults)
                .unwrap()
                .count,
            4,
            "multiple matches in one line still use one selector operation"
        );

        let miss = b"miss\n";
        let prospective = prefilter
            .line_partition_prospective(miss.len())
            .unwrap()
            .unwrap();
        let exact_work = miss
            .len()
            .checked_add(prospective.transitions_upper_bound)
            .and_then(|work| work.checked_add(prospective.match_events_upper_bound))
            .unwrap();
        let exact = RunLimits {
            fre_aggregate_operation_work: exact_work,
            fre_aggregate_sequential_bytes: miss.len() * 2,
            ..RunLimits::default()
        };
        let exact_report =
            execute_grep_captures_inner(Some(prefilter), &regex, miss, &exact).unwrap();
        assert_eq!(exact_report.count, 0);
        assert_eq!(exact_report.selector_executions, 0);
        assert_eq!(
            exact_report.selector.work,
            exact.fre_aggregate_operation_work
        );
        assert_eq!(
            exact_report.selector.sequential_bytes,
            exact.fre_aggregate_sequential_bytes
        );
        let one_below = RunLimits {
            fre_aggregate_operation_work: exact.fre_aggregate_operation_work - 1,
            ..exact
        };
        let refusal =
            execute_grep_captures_inner(Some(prefilter), &regex, miss, &one_below).unwrap_err();
        assert_eq!(refusal.status, Status::Unsupported);
        assert!(refusal.message.contains("required-literal scans require"));
    }

    #[test]
    fn line_batch_residual_peak_clamps_every_capture_storage_dimension() {
        let original = CaptureRunLimits::default();
        let residual = 17;
        let clipped = capture_run_limits_with_peak(original, residual);
        assert_eq!(
            clipped.selector.max_random_access_bytes,
            original.selector.max_random_access_bytes.min(residual)
        );
        assert_eq!(
            clipped.selector.max_scratch_bytes,
            original.selector.max_scratch_bytes.min(residual)
        );
        assert_eq!(
            clipped.selector.max_log_bytes,
            original.selector.max_log_bytes.min(residual)
        );
        assert_eq!(
            clipped.selector.max_output_bytes,
            original.selector.max_output_bytes.min(residual)
        );
        assert_eq!(
            clipped.selector.max_peak_bytes,
            original.selector.max_peak_bytes.min(residual)
        );
        assert_eq!(
            clipped.aggregate.per_search.max_scratch_bytes,
            original
                .aggregate
                .per_search
                .max_scratch_bytes
                .min(residual)
        );
        assert_eq!(
            clipped.aggregate.max_retained_output_bytes,
            original.aggregate.max_retained_output_bytes.min(residual)
        );
        assert_eq!(
            clipped.aggregate.max_combined_peak_bytes,
            original.aggregate.max_combined_peak_bytes.min(residual)
        );
        assert_eq!(
            clipped.prefix_class_participation.max_operation_bytes,
            original
                .prefix_class_participation
                .max_operation_bytes
                .min(residual)
        );
        assert_eq!(
            clipped.prefix_class_participation.max_scratch_bytes,
            original
                .prefix_class_participation
                .max_scratch_bytes
                .min(residual)
        );
        assert_eq!(
            clipped.prefix_class_participation.max_peak_bytes,
            original
                .prefix_class_participation
                .max_peak_bytes
                .min(residual)
        );
        assert_eq!(
            clipped.max_combined_peak_bytes,
            original.max_combined_peak_bytes.min(residual)
        );
    }

