    // rebar-row:imported/mariomka/ip@rust/regex
    #[test]
    #[ignore = "requires FRE_BOUNDED_SEPARATED_FIELDS_HARD_CORPUS"]
    fn current_fre_bounded_separated_ip_hard_no_clock_canary() {
        const PATTERN: &str = r"(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9])\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9])";
        let path = std::env::var_os("FRE_BOUNDED_SEPARATED_FIELDS_HARD_CORPUS")
            .expect("FRE_BOUNDED_SEPARATED_FIELDS_HARD_CORPUS names the authenticated corpus");
        let haystack = fs::read(path).expect("hard corpus is readable");
        assert_eq!(haystack.len(), 6_839_410);
        assert_eq!(
            sha256(&haystack),
            "7b7f70c9ca999b2bede85b7ed8e37c9193edced196f4aed29651e37ef4f8e979"
        );
        let patterns = [PATTERN.to_string()];
        for limits in [
            RunLimits::default(),
            RunLimits {
                fre_aggregate_operation_work: 533_473_988,
                ..RunLimits::default()
            },
            RunLimits {
                fre_aggregate_sequential_bytes: 341_970_500,
                ..RunLimits::default()
            },
        ] {
            assert_current_fre_execution(
                current_fre("count", &patterns, &haystack, false, false, &limits),
                5,
                "aggregate-bounded-separated-fields",
            );
        }
        let refusal = current_fre(
            "count",
            &patterns,
            &haystack,
            false,
            false,
            &RunLimits {
                fre_aggregate_operation_work: 533_473_987,
                ..RunLimits::default()
            },
        );
        assert!(
            matches!(refusal, CandidateOutcome::Unsupported(ref reason)
                if reason.contains("WorkLimit")
                    && reason.contains("533473988")
                    && reason.contains("533473987")),
            "one-below hard work must be a typed refusal: {refusal:?}"
        );
        let refusal = current_fre(
            "count",
            &patterns,
            &haystack,
            false,
            false,
            &RunLimits {
                fre_aggregate_sequential_bytes: 341_970_499,
                ..RunLimits::default()
            },
        );
        assert!(
            matches!(refusal, CandidateOutcome::Unsupported(ref reason)
                if reason.contains("SequentialLimit")
                    && reason.contains("341970500")
                    && reason.contains("341970499")),
            "one-below hard sequential input access must be a typed refusal: {refusal:?}"
        );
    }

    fn generic_url_aggregate_builder(
        pattern: impl Into<String>,
        case_insensitive: bool,
    ) -> AggregateBuilder {
        AggregateBuilder::new(pattern)
            .profile(rebar_profile())
            .unicode(false)
            .case_insensitive(case_insensitive)
            .limits(AggregateBuildLimits::default())
            .plan_selection(AggregatePlanSelection::Auto)
            .strategy(AggregateStrategy::ReverseSequentialRows)
    }

    fn assert_formal_rebar_quarantines_url_intrinsic_and_matches_oracle() {
        const PATTERN: &str = r"((?:(?:(?:https?|ftp)://(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?))|(?:(?:https?|ftp)://)?(?:[a-z0-9%.]+:[a-z0-9%]+@)?(?:(?:[a-z0-9_~]\-?){0,62}[a-z0-9]\.)*(?:(?:(?:[a-z0-9]\-?){0,62}[a-z0-9])|(?:xn--[a-z0-9\-]+))\.(?:COM|ORG|XN--P1AI))(?::\d{2,5})?(?:/[a-z0-9/\-_%$@&()!?'=~*+:;,.]+)*/?(?:[?#]\S*)*/?)";
        let haystack = b"noise HTTP://1.2.3.4 https://u:p@a.b.org/path?q xn--a.com ftp://a.com:8080/x#y\ninvalid://x.com trailing";
        let oracle = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(false)
            .case_insensitive(true)
            .build()
            .unwrap();
        let expected_count = u64::try_from(oracle.find_iter(haystack).count()).unwrap();
        let expected_span_sum = oracle
            .find_iter(haystack)
            .map(|matched| u64::try_from(matched.end() - matched.start()).unwrap())
            .sum::<u64>();

        let generic = generic_url_aggregate_builder(PATTERN, true)
            .build_count()
            .unwrap();
        assert!(
            generic
                .build_report()
                .build_limits
                .continuation
                .allow_workload_specific_intrinsics
        );
        assert!(
            generic
                .build_report()
                .authenticates_url_aggregate_identity()
        );

        let compile = current_fre_rebar_aggregate_builder(PATTERN, false, true)
            .build_compile()
            .unwrap();
        let count = current_fre_rebar_aggregate_builder(PATTERN, false, true)
            .build_count()
            .unwrap();
        let spans = current_fre_rebar_aggregate_builder(PATTERN, false, true)
            .build_spans()
            .unwrap();
        for report in [
            compile.build_report(),
            count.build_report(),
            spans.build_report(),
        ] {
            assert!(
                !report
                    .build_limits
                    .continuation
                    .allow_workload_specific_intrinsics
            );
            assert!(!report.authenticates_url_aggregate_identity());
            if let AggregateBuildAccounting::Continuation(compile) = report.build {
                assert_eq!(compile.url_aggregate_plans, 0);
            }
        }

        let patterns = [PATTERN.to_string()];
        for (model, expected) in [
            ("compile", expected_count),
            ("count", expected_count),
            ("count-spans", expected_span_sum),
        ] {
            let CandidateOutcome::ExecutedWithPlan { actual, plan } = current_fre(
                model,
                &patterns,
                haystack,
                false,
                true,
                &RunLimits::default(),
            ) else {
                panic!("formal URL {model} did not execute")
            };
            assert_eq!(actual, expected);
            assert!(!plan.contains("aggregate-url"));
        }
    }

    #[test]
    fn formal_rebar_quarantines_url_intrinsic_and_matches_oracle() {
        std::thread::Builder::new()
            .name("formal-rebar-url-quarantine".to_string())
            .stack_size(16 * 1024 * 1024)
            .spawn(assert_formal_rebar_quarantines_url_intrinsic_and_matches_oracle)
            .unwrap()
            .join()
            .unwrap();
    }

    #[test]
    fn formal_rebar_quarantines_multi_pattern_ascii_word_shadow() {
        let patterns = [
            r"(\bif\b)".to_string(),
            r"(\belse\b)".to_string(),
            r"([a-z_][a-z0-9_]*)".to_string(),
        ];
        let haystack = b"if value9 else _tail 7zip";

        let generic = AggregateManyBuilder::new(&patterns)
            .profile(rebar_profile())
            .unicode(false)
            .build_spans()
            .expect("generic ASCII word-shadow build");
        assert!(generic.build_report().ascii_word_shadow.is_some());

        let formal = current_fre_rebar_aggregate_many_builder(&patterns, false, false)
            .build_spans()
            .expect("formal ordered-many complete spans");
        assert!(
            !aggregate_many_build_limits(&RunLimits::default())
                .continuation
                .allow_workload_specific_intrinsics
        );
        assert!(formal.build_report().ascii_word_shadow.is_none());
        assert_eq!(
            formal
                .build_report()
                .composition
                .ascii_word_shadow_proof_work,
            0
        );

        let oracle = regex::bytes::RegexBuilder::new(
            &patterns
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>()
                .join("|"),
        )
        .unicode(false)
        .build()
        .expect("ordered-many oracle");
        let expected = oracle.find_iter(haystack).try_fold(0_u64, |sum, matched| {
            sum.checked_add(u64::try_from(matched.len()).ok()?)
        });
        let expected = expected.expect("oracle span sum fits u64");
        assert_current_fre_execution(
            current_fre(
                "count-spans",
                &patterns,
                haystack,
                false,
                false,
                &RunLimits::default(),
            ),
            expected,
            "aggregate-many-continuation-program",
        );
    }

