    #[test]
    #[ignore = "requires FRE_TEST_URL_PATTERN to name the authenticated Rebar URL pattern"]
    #[allow(
        clippy::too_many_lines,
        reason = "one authenticated URL transaction covers route gating, exported bounds, and typed one-below refusals"
    )]
    fn generic_url_identity_and_route_label_are_fail_closed() {
        let path = std::env::var_os("FRE_TEST_URL_PATTERN")
            .expect("FRE_TEST_URL_PATTERN must name wild/url.txt");
        let source = std::fs::read_to_string(path).unwrap();
        let source = source.trim_end();

        let count = generic_url_aggregate_builder(source, true)
            .build_count()
            .unwrap();
        let count_report = count.build_report();
        assert!(count_report.has_closed_url_aggregate_identity());
        assert!(count_report.authenticates_url_aggregate_identity());
        current_fre_rebar_validate_aggregate_identity(count_report, false, "count").unwrap();
        assert_eq!(
            aggregate_single_plan_label("count", count_report),
            "aggregate-url"
        );

        let complete_spans = generic_url_aggregate_builder(source, true)
            .build_spans()
            .unwrap();
        let complete_spans_report = complete_spans.build_report();
        assert!(complete_spans_report.has_closed_url_aggregate_identity());
        current_fre_rebar_validate_aggregate_identity_with_options(
            complete_spans_report,
            false,
            true,
            "count-spans",
        )
        .unwrap();
        assert_eq!(
            aggregate_single_plan_label("count-spans", complete_spans_report),
            "aggregate-url"
        );

        let compile = generic_url_aggregate_builder(source, true)
            .build_compile()
            .unwrap();
        assert_eq!(
            aggregate_single_plan_label("compile", compile.build_report()),
            "compile-aggregate-url"
        );

        let dormant = generic_url_aggregate_builder(source, true)
            .strategy(AggregateStrategy::FullTable)
            .build_span_sum()
            .unwrap();
        assert!(dormant.build_report().has_closed_url_aggregate_identity());
        assert!(
            dormant
                .build_report()
                .authenticates_url_aggregate_identity()
        );
        assert_eq!(
            aggregate_single_plan_label("count-spans", dormant.build_report()),
            "aggregate-continuation-program"
        );

        let mut long_segment = vec![b'a'; 600 * 1_024];
        long_segment.extend_from_slice(b".com");
        let upper = fre::url_aggregate_reduce_upper_bounds(long_segment.len()).unwrap();
        let visitor_upper = fre::url_aggregate_span_visit_upper_bounds(long_segment.len()).unwrap();
        let policy = RunLimits::default();
        let count_limits = aggregate_run_limits(long_segment.len(), count_report, &policy).unwrap();
        let complete_spans_limits =
            aggregate_run_limits(long_segment.len(), complete_spans_report, &policy).unwrap();
        let specialized = url_aggregate_operation_limits(long_segment.len(), &policy).unwrap();
        let visitor_specialized =
            url_aggregate_span_visit_operation_limits(long_segment.len(), &policy).unwrap();
        assert_eq!(count_limits.continuation, specialized);
        assert_eq!(complete_spans_limits.continuation, visitor_specialized);
        assert_eq!(
            visitor_specialized.max_sequential_bytes,
            visitor_upper.sequential_bytes
        );
        assert_eq!(visitor_upper.sequential_bytes, long_segment.len() * 5);
        assert_ne!(complete_spans_limits.continuation, specialized);

        let AggregateBuildAccounting::Continuation(count_compile) = count_report.build else {
            panic!("URL count must retain continuation compile accounting");
        };
        let generic = continuation_operation_limits(
            long_segment.len(),
            ContinuationProgramShape::from(count_compile),
            &policy,
        )
        .unwrap();
        assert!(
            generic.max_random_access_bytes < specialized.max_random_access_bytes,
            "generic continuation storage {} must not authorize URL workspace {}",
            generic.max_random_access_bytes,
            specialized.max_random_access_bytes
        );

        let dormant_limits =
            aggregate_run_limits(long_segment.len(), dormant.build_report(), &policy).unwrap();
        let AggregateBuildAccounting::Continuation(dormant_compile) = dormant.build_report().build
        else {
            panic!("dormant URL plan must retain continuation compile accounting");
        };
        let mut dormant_shape = ContinuationProgramShape::from(dormant_compile);
        dormant_shape.required_internal_anchors = 0;
        dormant_shape.required_internal_anchor_bytes = 0;
        dormant_shape.required_internal_anchor_optional_stages = 0;
        dormant_shape.required_internal_anchor_persistent_bytes = 0;
        assert_eq!(
            dormant_limits.continuation,
            continuation_operation_limits(long_segment.len(), dormant_shape, &policy).unwrap()
        );
        assert_ne!(dormant_limits.continuation, specialized);

        let compile_limits =
            aggregate_run_limits(long_segment.len(), compile.build_report(), &policy).unwrap();
        let AggregateBuildAccounting::Continuation(compile_accounting) =
            compile.build_report().build
        else {
            panic!("URL compile route must retain continuation compile accounting");
        };
        let mut compile_shape = ContinuationProgramShape::from(compile_accounting);
        compile_shape.required_internal_anchors = 0;
        compile_shape.required_internal_anchor_bytes = 0;
        compile_shape.required_internal_anchor_optional_stages = 0;
        compile_shape.required_internal_anchor_persistent_bytes = 0;
        assert_eq!(
            compile_limits.continuation,
            continuation_operation_limits(long_segment.len(), compile_shape, &policy).unwrap()
        );
        assert_ne!(compile_limits.continuation, specialized);

        let result = count.count(&long_segment, count_limits).unwrap();
        let AggregateExecutionDetails::Continuation {
            certificate,
            accounting,
        } = result.report().details()
        else {
            panic!("URL count must publish continuation execution details");
        };
        assert_eq!(
            certificate.random_access_bytes,
            upper.random_access_storage_bytes
        );
        assert_eq!(certificate.scratch_bytes, upper.scratch_bytes);
        assert_eq!(certificate.peak_bytes, upper.peak_bytes);
        assert_eq!(certificate.sequential_bytes_bound, upper.sequential_bytes);
        assert_eq!(
            accounting.random_access_peak_bytes,
            upper.random_access_storage_bytes
        );
        assert_eq!(accounting.scratch_peak_bytes, upper.scratch_bytes);
        assert_eq!(accounting.peak_bytes, upper.peak_bytes);
        assert_eq!(accounting.sequential_bytes_read, upper.sequential_bytes);

        let mut generic_limits = count_limits;
        generic_limits.continuation = generic;
        let error = count.count(&long_segment, generic_limits).unwrap_err();
        assert!(matches!(
            error.source,
            AggregateExecutionSource::Continuation(AggregateEngineError::ResourceLimit {
                resource: AggregateResource::RandomAccessBytes,
                ..
            })
        ));

        for (resource, one_below) in [
            (
                AggregateResource::RandomAccessBytes,
                AggregateOperationLimits {
                    max_random_access_bytes: upper.random_access_storage_bytes - 1,
                    ..specialized
                },
            ),
            (
                AggregateResource::ScratchBytes,
                AggregateOperationLimits {
                    max_scratch_bytes: upper.scratch_bytes - 1,
                    ..specialized
                },
            ),
            (
                AggregateResource::PeakBytes,
                AggregateOperationLimits {
                    max_peak_bytes: upper.peak_bytes - 1,
                    ..specialized
                },
            ),
            (
                AggregateResource::SequentialBytes,
                AggregateOperationLimits {
                    max_sequential_bytes: upper.sequential_bytes - 1,
                    ..specialized
                },
            ),
        ] {
            let mut limits = count_limits;
            limits.continuation = one_below;
            let error = count.count(&long_segment, limits).unwrap_err();
            assert!(matches!(
                error.source,
                AggregateExecutionSource::Continuation(AggregateEngineError::ResourceLimit {
                    resource: actual,
                    required,
                    limit,
                }) if actual == resource && required == limit + 1
            ));
        }

        for field in 0..5 {
            let mut forged = count_report.clone();
            let AggregateBuildAccounting::Continuation(ref mut accounting) = forged.build else {
                panic!("URL route must retain continuation accounting");
            };
            match field {
                0 => accounting.url_aggregate_plans += 1,
                1 => accounting.url_aggregate_tlds += 1,
                2 => accounting.url_aggregate_tld_bytes += 1,
                3 => accounting.url_aggregate_build_work += 1,
                4 => accounting.url_aggregate_persistent_bytes += 1,
                _ => unreachable!(),
            }
            assert!(!forged.has_closed_url_aggregate_identity());
            assert!(!forged.authenticates_url_aggregate_identity());
            assert!(
                current_fre_rebar_validate_aggregate_identity(&forged, false, "count").is_err()
            );
            assert!(aggregate_run_limits(128, &forged, &RunLimits::default()).is_err());
        }

        let mut capacity_forgery = count_report.clone();
        capacity_forgery.retained_capacity_bytes += 1;
        assert!(!capacity_forgery.has_closed_url_aggregate_identity());

        let mut semantics_forgery = count_report.clone();
        let AggregatePlanIdentity::Continuation(ref mut identity) = semantics_forgery.plan_identity
        else {
            panic!("URL route must retain a continuation identity");
        };
        identity.semantics = AggregateContinuationSemantics::UnicodeOnUtf8ScalarHir;
        assert!(!semantics_forgery.has_closed_url_aggregate_identity());

        let absent = generic_url_aggregate_builder("abc", false)
            .build_count()
            .unwrap();
        assert!(absent.build_report().has_closed_url_aggregate_identity());
        assert!(!absent.build_report().authenticates_url_aggregate_identity());
        let absent_continuation = generic_url_aggregate_builder("a.*b", false)
            .build_count()
            .unwrap();
        assert!(matches!(
            absent_continuation.build_report().build,
            AggregateBuildAccounting::Continuation(_)
        ));
        assert!(
            absent_continuation
                .build_report()
                .has_closed_url_aggregate_identity()
        );
        assert!(
            !absent_continuation
                .build_report()
                .authenticates_url_aggregate_identity()
        );
    }

    #[test]
    fn reverse_inner_adapter_closes_independent_and_both_v2_union_receipts() {
        let independent = current_fre_rebar_aggregate_builder(r"[a-zλ]+ab[a-zλ]+", true, false)
            .build_count()
            .expect("independent reverse-inner plan");
        let distinct = current_fre_rebar_aggregate_builder(r"[a-zλ]+(?:ab|cd)[a-zλ]+", true, false)
            .build_count()
            .expect("distinct-root reverse-inner plan");
        let grouped =
            current_fre_rebar_aggregate_builder(r"[a-zλ]+(?:aab|abb)[a-zλ]+", true, false)
                .build_count()
                .expect("grouped reverse-inner plan");

        for plan in [&independent, &distinct, &grouped] {
            current_fre_rebar_validate_aggregate_identity(plan.build_report(), true, "count")
                .expect("reverse-inner receipt closes");
        }
        assert_eq!(
            aggregate_single_plan_label("count", independent.build_report()),
            "aggregate-reverse-inner-independent-v1"
        );
        assert_eq!(
            aggregate_single_plan_label("compile", independent.build_report()),
            "compile-aggregate-reverse-inner-independent-v1"
        );
        assert_eq!(
            aggregate_single_plan_label("count", distinct.build_report()),
            "aggregate-reverse-inner-adaptive-union-v2"
        );
        assert_eq!(
            aggregate_single_plan_label("compile", distinct.build_report()),
            "compile-aggregate-reverse-inner-adaptive-union-v2"
        );
        assert_eq!(
            aggregate_single_plan_label("count", grouped.build_report()),
            "aggregate-reverse-inner-grouped-union-v2"
        );
        assert_eq!(
            aggregate_single_plan_label("compile", grouped.build_report()),
            "compile-aggregate-reverse-inner-grouped-union-v2"
        );

        let AggregateBuildAccounting::ReverseInner(distinct_build) = distinct.build_report().build
        else {
            panic!("distinct-root plan retained another receipt");
        };
        let AggregateBuildAccounting::ReverseInner(grouped_build) = grouped.build_report().build
        else {
            panic!("grouped plan retained another receipt");
        };
        assert_eq!(
            distinct_build.union_mode,
            ReverseInnerUnionMode::AdaptiveFirstByte
        );
        assert!(distinct_build.adaptive_union);
        assert_eq!(
            grouped_build.union_mode,
            ReverseInnerUnionMode::GroupedFixedColumn
        );
        assert!(!grouped_build.adaptive_union);

        let AggregatePlanIdentity::ReverseInner(grouped_identity) =
            grouped.build_report().plan_identity
        else {
            panic!("grouped plan retained another identity");
        };
        assert_eq!(
            grouped_identity.kernel.union_receipt_digest,
            grouped_build.union_receipt_digest()
        );

        macro_rules! assert_grouped_field_forgery_rejected {
            ($field:ident) => {{
                let mut forged = grouped.build_report().clone();
                let AggregateBuildAccounting::ReverseInner(ref mut build) = forged.build else {
                    panic!("grouped plan retained another receipt");
                };
                build.$field = build
                    .$field
                    .checked_add(1)
                    .expect("small grouped receipt field increment");
                let forged_digest = build.union_receipt_digest();
                let AggregatePlanIdentity::ReverseInner(identity) = forged.plan_identity else {
                    panic!("grouped plan retained another identity");
                };
                assert_ne!(
                    identity.kernel.union_receipt_digest,
                    forged_digest,
                    "{} escaped the union receipt digest",
                    stringify!($field)
                );
                assert!(
                    current_fre_rebar_validate_aggregate_identity(&forged, true, "count").is_err(),
                    "{} forgery authenticated",
                    stringify!($field)
                );
            }};
        }
        assert_grouped_field_forgery_rejected!(union_anchor_offset);
        assert_grouped_field_forgery_rejected!(union_anchor_distinct_bytes);
        assert_grouped_field_forgery_rejected!(union_anchor_max_bucket_literals);
        assert_grouped_field_forgery_rejected!(union_anchor_max_bucket_verification_work);
        assert_grouped_field_forgery_rejected!(union_anchor_collision_pairs);
        assert_grouped_field_forgery_rejected!(union_anchor_selection_work);
        assert_grouped_field_forgery_rejected!(distinct_literal_first_bytes);

        let mut forged_legacy_summary = grouped.build_report().clone();
        let AggregateBuildAccounting::ReverseInner(ref mut build) = forged_legacy_summary.build
        else {
            panic!("grouped plan retained another receipt");
        };
        build.adaptive_union = true;
        let forged_legacy_digest = build.union_receipt_digest();
        let AggregatePlanIdentity::ReverseInner(identity) = forged_legacy_summary.plan_identity
        else {
            panic!("grouped plan retained another identity");
        };
        assert_ne!(identity.kernel.union_receipt_digest, forged_legacy_digest);
        assert!(
            current_fre_rebar_validate_aggregate_identity(&forged_legacy_summary, true, "count",)
                .is_err()
        );

        let mut transplanted_adaptive = grouped.build_report().clone();
        let AggregateBuildAccounting::ReverseInner(ref mut build) = transplanted_adaptive.build
        else {
            panic!("grouped plan retained another receipt");
        };
        build.distinct_literal_first_bytes = distinct_build.distinct_literal_first_bytes;
        build.union_anchor_offset = distinct_build.union_anchor_offset;
        build.union_anchor_distinct_bytes = distinct_build.union_anchor_distinct_bytes;
        build.union_anchor_max_bucket_literals = distinct_build.union_anchor_max_bucket_literals;
        build.union_anchor_max_bucket_verification_work =
            distinct_build.union_anchor_max_bucket_verification_work;
        build.union_anchor_collision_pairs = distinct_build.union_anchor_collision_pairs;
        build.union_anchor_selection_work = distinct_build.union_anchor_selection_work;
        build.adaptive_union = distinct_build.adaptive_union;
        build.union_mode = distinct_build.union_mode;
        let transplanted_digest = build.union_receipt_digest();
        let AggregatePlanIdentity::ReverseInner(ref mut identity) =
            transplanted_adaptive.plan_identity
        else {
            panic!("grouped plan retained another identity");
        };
        identity.kernel.plan_id = REVERSE_INNER_UNION_PLAN_ID;
        identity.kernel.accounting_id = REVERSE_INNER_UNION_ACCOUNTING_ID;
        assert_eq!(
            build.distinct_literal_first_bytes, build.literal_count,
            "the transplanted adaptive receipt must carry a coherent first-byte census"
        );
        assert_eq!(
            transplanted_digest,
            distinct_build.union_receipt_digest(),
            "the forged receipt must coherently reproduce the adaptive union summary"
        );
        assert_ne!(identity.kernel.union_receipt_digest, transplanted_digest);
        assert!(
            current_fre_rebar_validate_aggregate_identity(&transplanted_adaptive, true, "count")
                .is_err()
        );
    }

