    #[test]
    fn rebar_count_spans_streams_bounds_instead_of_using_total_byte_cover() {
        let patterns = [
            r"(?:ab|a)",
            r"(?:\r\n|\r|\n)",
            r"(?-u:[\x00-\x09\x0B-\xFF])",
        ]
        .into_iter()
        .map(str::to_owned)
        .collect::<Vec<_>>();
        let haystack = b"\x00aab\r\nb\xFF";

        let generic = current_fre_rebar_aggregate_many_builder(&patterns, false, false)
            .build_span_sum()
            .expect("generic span-sum remains available");
        assert_eq!(
            generic.build_report().plan,
            AggregateManyPlanKind::TotalByteCoverSpanSum
        );
        let generic_limits =
            current_fre_rebar_aggregate_many_run_limits(haystack.len(), generic.build_report())
                .expect("generic total-cover limits");
        assert_eq!(
            generic
                .span_sum_value(haystack, generic_limits)
                .expect("generic total-cover value"),
            u64::try_from(haystack.len()).unwrap()
        );

        assert_current_fre_execution(
            current_fre(
                "count-spans",
                &patterns,
                haystack,
                false,
                false,
                &RunLimits::default(),
            ),
            u64::try_from(haystack.len()).unwrap(),
            "aggregate-many-continuation-program",
        );

        let lifecycle = current_fre_rebar_aggregate_operation_lifecycle(
            "count-spans",
            &patterns,
            false,
            false,
            haystack.len(),
        )
        .expect("Rebar complete-spans lifecycle");
        assert_eq!(lifecycle.plan(), "aggregate-many-continuation-program");
        let CurrentFreAggregateOperationInner::StreamingSpansMany(regex, limits, _) =
            &lifecycle.inner
        else {
            panic!("Rebar count-spans selected something other than streamed complete multi spans")
        };
        assert_eq!(
            regex.build_report().operation,
            AggregateManyOperation::Spans
        );
        assert_eq!(
            regex.build_report().plan,
            AggregateManyPlanKind::ContinuationProgram
        );
        assert_eq!(limits.continuation.max_output_bytes, 0);
        assert_eq!(
            lifecycle.execute(haystack).expect("complete-spans value"),
            u64::try_from(haystack.len()).unwrap()
        );
    }

    #[test]
    fn rebar_streamed_many_count_spans_preserves_nullable_empty_progress() {
        let patterns = vec![String::new(), "a".to_string()];
        let haystack = b"aa";
        let regex = current_fre_rebar_aggregate_many_builder(&patterns, false, false)
            .build_spans()
            .expect("nullable multi complete-spans artifact");
        let limits = current_fre_rebar_aggregate_many_streaming_run_limits(
            haystack.len(),
            regex.build_report(),
        )
        .expect("nullable streamed complete-spans limits");
        assert_eq!(limits.continuation.max_output_bytes, 0);
        assert_eq!(limits.continuation.max_output_matches, haystack.len() + 1);

        let mut spans = Vec::new();
        let visited = regex
            .visit_spans(haystack, limits, |matched| {
                spans.push((matched.start(), matched.end()));
            })
            .expect("nullable streamed complete-spans execution");
        assert_eq!(spans, [(0, 0), (1, 1), (2, 2)]);
        assert_eq!(visited.len(), spans.len());
        assert_eq!(visited.span_sum(), 0);
        assert_eq!(
            rebar_sum_streamed_many_match_bounds(&regex, haystack, limits)
                .expect("authenticated nullable Rebar reduction"),
            0
        );
    }

    #[test]
    fn current_fre_one_pattern_aggregate_models_cover_adversarial_semantics() {
        let limits = RunLimits::default();
        let late = vec![r"(?:a+b|a)".to_string()];
        assert_current_fre_execution(
            current_fre("count", &late, b"aaaa", false, false, &limits),
            4,
            "aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre("count", &late, b"aaaab", false, false, &limits),
            1,
            "aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre("count-spans", &late, b"aaaa", false, false, &limits),
            4,
            "aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre("count-spans", &late, b"aaaab", false, false, &limits),
            5,
            "aggregate-continuation-program",
        );

        let empty = vec![String::new()];
        assert_current_fre_execution(
            current_fre("count", &empty, b"ab", false, false, &limits),
            3,
            "aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre("count-spans", &empty, b"ab", false, false, &limits),
            0,
            "aggregate-continuation-program",
        );
        let nullable = vec![r"(?:(?:|a){1,2}?b?)*".to_string()];
        let reference = compile_for("count", &nullable[0]);
        let expected = count_matches(&reference, b"aab", 100).unwrap();
        assert_current_fre_execution(
            current_fre("count", &nullable, b"aab", false, false, &limits),
            expected,
            "aggregate-continuation-program",
        );

        let absolute = vec![r"\Afoo\z".to_string()];
        assert_current_fre_execution(
            current_fre("count", &absolute, b"xxfoo", false, false, &limits),
            0,
            "aggregate-continuation-program",
        );
        let end = vec![r"foo\z".to_string()];
        assert_current_fre_execution(
            current_fre("count", &end, b"xxfoo", false, false, &limits),
            1,
            "aggregate-continuation-program",
        );
        let assertion_cases: [(&str, &[u8], u64, u64); 2] = [
            (r"\b[a-z]+\b", b"_alpha beta!gamma42 \xFFdelta", 2, 9),
            (r"(?m:sherlock$)", b"sherlock\nnot\nsherlock", 2, 16),
        ];
        for (pattern, haystack, count, span_sum) in assertion_cases {
            let patterns = [pattern.to_string()];
            assert_current_fre_execution(
                current_fre("count", &patterns, haystack, false, false, &limits),
                count,
                "aggregate-continuation-program",
            );
            assert_current_fre_execution(
                current_fre("count-spans", &patterns, haystack, false, false, &limits),
                span_sum,
                "aggregate-continuation-program",
            );
        }
        let captured = vec![r"(?P<outer>(?P<inner>a))".to_string()];
        assert_current_fre_execution(
            current_fre("count", &captured, b"baab", false, false, &limits),
            2,
            "aggregate-continuation-program",
        );
        let folded = vec!["sherlock".to_string()];
        assert_current_fre_execution(
            current_fre("count", &folded, b"SHERLOCK sherlock", false, true, &limits),
            2,
            "aggregate-continuation-program",
        );

        // These are canonical leftmost-first results. The pinned Rust meta
        // adapter's reverse-suffix optimization incorrectly returns 2; exact
        // report generation deliberately retains those reference failures.
        for (pattern, plan) in [
            (r".abb|b", "aggregate-continuation-program"),
            (r"(?:[A-Za-z]ab)?b", "aggregate-continuation-program"),
        ] {
            assert_current_fre_execution(
                current_fre(
                    "count",
                    &[pattern.to_string()],
                    b"zabb",
                    false,
                    false,
                    &limits,
                ),
                1,
                plan,
            );
        }
    }

    #[test]
    fn current_fre_grep_reuses_k0_workspace_across_lines() {
        let patterns = vec![r"\b[0-9A-Za-z_]{2,}\b".to_string()];
        assert_current_fre_execution(
            current_fre(
                "grep",
                &patterns,
                b"--\nalpha\n-\nxy\n\xFF\n",
                false,
                false,
                &RunLimits::default(),
            ),
            2,
            CURRENT_FRE_REBAR_GREP_PLAN,
        );
        let unicode_lines = format!("short\n{}\n{}\n", "α".repeat(25), "β".repeat(24));
        assert_current_fre_execution(
            current_fre(
                "grep",
                &[r"\b\w{25,}\b".to_string()],
                unicode_lines.as_bytes(),
                true,
                false,
                &RunLimits::default(),
            ),
            1,
            CURRENT_FRE_REBAR_GREP_PLAN,
        );
        assert_current_fre_execution(
            current_fre(
                "grep",
                &[r"^[ \t\f]*#.*?coding[:=][ \t]*utf-?8".to_string()],
                b"# coding: utf-8\nx # coding: utf-8\n\xFF\n",
                true,
                false,
                &RunLimits::default(),
            ),
            1,
            CURRENT_FRE_REBAR_GREP_PLAN,
        );
    }

    #[test]
    fn prepared_is_match_token_is_differential_plan_bound_and_assertion_safe() {
        let pattern = r"((?:ASIA|AKIA|AROA|AIDA)([A-Z0-7]{16}))";
        let regex = current_fre_rebar_portable_builder(pattern, false, false)
            .unwrap()
            .build()
            .unwrap();
        assert_eq!(regex.runtime_implementation_id(), "k0");
        let limits = SearchLimits {
            max_work: 1_000_000_000,
            max_scratch_bytes: 512 * 1024 * 1024,
        };
        let mut search = regex
            .search_session(SearchSessionLimits {
                max_setup_work: limits.max_work,
                max_scratch_bytes: limits.max_scratch_bytes,
            })
            .unwrap();
        let token = search.prepare_is_match_value_token(4_096, limits);
        assert!(token.uses_prepared_route());
        assert!(token.uses_literal_prefix_class_route());
        assert!(!token.uses_k0_warm_route());
        assert!(!formal_rebar_prepared_is_match_token(token));
        assert!(token.maximum_warm_input_bytes().unwrap() >= 4_096);
        let mut generic_search = regex
            .search_session(SearchSessionLimits {
                max_setup_work: limits.max_work,
                max_scratch_bytes: limits.max_scratch_bytes,
            })
            .unwrap();
        let generic_token = generic_search.prepare_k0_warm_is_match_value_token(4_096, limits);
        assert!(generic_token.uses_k0_warm_route());
        assert!(formal_rebar_prepared_is_match_token(generic_token));
        assert!(generic_token.maximum_warm_input_bytes().unwrap() >= 4_096);

        let lines: [&[u8]; 6] = [
            b"plain text",
            b"AKIA0123456789ABCDEF",
            b"prefix ASIAABCDEFGHIJKLMNOP suffix",
            b"AROA0000000000000000",
            b"\xFFAKIA0123456789ABCDEF\xFE",
            b"",
        ];
        for _ in 0..2 {
            for line in lines {
                let expected = regex.is_match_value(line, limits).unwrap();
                assert_eq!(
                    search.is_match_value_prepared(line, token).unwrap(),
                    expected,
                    "prepared result differed for {line:?}",
                );
                assert_eq!(
                    generic_search
                        .is_match_value_prepared(line, generic_token)
                        .unwrap(),
                    expected,
                    "generic K0 warm result differed for {line:?}",
                );
            }
        }

        // The source-free work certificate has a sharp finite boundary for
        // this complete input. At the exact admitted budget the direct route
        // executes; one unit below it must replay the incumbent, preserving
        // that invocation's value or typed refusal exactly.
        let finite_line = b"AKIA01234567ABCDEFGH";
        let admits = |work| {
            let token = search.prepare_is_match_value_token(
                finite_line.len(),
                SearchLimits {
                    max_work: work,
                    max_scratch_bytes: usize::MAX,
                },
            );
            token.uses_literal_prefix_class_route()
                && token
                    .maximum_warm_input_bytes()
                    .is_some_and(|maximum| maximum >= finite_line.len())
        };
        let mut upper = 1_u64;
        while !admits(upper) {
            upper = upper.checked_mul(2).expect("finite admission boundary");
        }
        let mut lower = 0_u64;
        while lower + 1 < upper {
            let middle = lower + (upper - lower) / 2;
            if admits(middle) {
                upper = middle;
            } else {
                lower = middle;
            }
        }
        let exact_limits = SearchLimits {
            max_work: upper,
            max_scratch_bytes: usize::MAX,
        };
        let exact_admitted = admits(upper);
        let one_below_admitted = admits(upper - 1);
        let exact_token = search.prepare_is_match_value_token(finite_line.len(), exact_limits);
        assert!(exact_admitted);
        assert_eq!(
            search.is_match_value_prepared(finite_line, exact_token),
            regex.is_match_value(finite_line, exact_limits),
        );
        let one_below = SearchLimits {
            max_work: upper - 1,
            max_scratch_bytes: usize::MAX,
        };
        let one_below_token = search.prepare_is_match_value_token(finite_line.len(), one_below);
        assert!(!one_below_admitted);
        assert_eq!(
            search.is_match_value_prepared(finite_line, one_below_token),
            regex.is_match_value(finite_line, one_below),
        );

        // The formal public grep route retains one ordinary semantic matcher
        // invocation for every ByteSlice::lines domain; the narrow prepared
        // recognizer remains available only through the generic API above.
        let haystack = b"plain\r\nAKIA01234567ABCDEFGH\n\xffAIDA01234567ABCDEFGH\xfe\nlast";
        let rust = rust_compile_options(&[pattern.to_string()], false, false).unwrap();
        let expected = grep(&rust, haystack, RunLimits::default().reducer_steps).unwrap();
        let mut grep_session = current_fre_rebar_grep_session(&regex, haystack.len()).unwrap();
        assert!(!grep_session.uses_prepared_literal_prefix_class_is_match());
        assert_eq!(grep_session.execute(haystack).unwrap(), expected);
        assert!(!grep_session.uses_prepared_literal_prefix_class_is_match());
        assert!(grep_session.uses_prepared_k0_is_match());

        // A token from a separately built, semantically equal matcher must
        // replay the incumbent rather than authenticating another automaton's
        // retained workspace.
        let other = current_fre_rebar_portable_builder(pattern, false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits {
                max_setup_work: limits.max_work,
                max_scratch_bytes: limits.max_scratch_bytes,
            })
            .unwrap();
        assert_eq!(
            other_search
                .is_match_value_prepared(b"AKIA0123456789ABCDEF", token)
                .unwrap(),
            other
                .is_match_value(b"AKIA0123456789ABCDEF", limits)
                .unwrap(),
        );
        assert_eq!(
            other_search
                .is_match_value_prepared(b"AKIA0123456789ABCDEF", generic_token)
                .unwrap(),
            other
                .is_match_value(b"AKIA0123456789ABCDEF", limits)
                .unwrap(),
        );

        let asserted = current_fre_rebar_portable_builder(
            r"^[ \t\x0C]*#.*?coding[:=][ \t]*utf-?8",
            true,
            false,
        )
        .unwrap()
        .build()
        .unwrap();
        let mut asserted_search = asserted
            .search_session(SearchSessionLimits {
                max_setup_work: limits.max_work,
                max_scratch_bytes: limits.max_scratch_bytes,
            })
            .unwrap();
        let asserted_token = asserted_search.prepare_is_match_value_token(4_096, limits);
        assert!(!asserted_token.uses_k0_warm_route());
        let asserted_generic = asserted_search.prepare_k0_warm_is_match_value_token(4_096, limits);
        assert!(!asserted_generic.uses_prepared_route());
        for line in [b"# coding: utf-8".as_slice(), b"x # coding: utf-8"] {
            assert_eq!(
                asserted_search
                    .is_match_value_prepared(line, asserted_token)
                    .unwrap(),
                asserted.is_match_value(line, limits).unwrap(),
            );
        }
    }

    #[test]
    fn prepared_is_match_token_preserves_exact_and_one_below_refusals() {
        let regex = current_fre_rebar_portable_builder(
            r"((?:ASIA|AKIA|AROA|AIDA)([A-Z0-7]{16}))",
            false,
            false,
        )
        .unwrap()
        .build()
        .unwrap();
        let setup_limits = SearchSessionLimits::unlimited();
        let line = b"ordinary line without a cloud credential";

        let mut work_search = regex.search_session(setup_limits).unwrap();
        work_search
            .is_match(line, SearchLimits::unlimited())
            .unwrap();
        let (_, accounting) = work_search
            .is_match(line, SearchLimits::unlimited())
            .unwrap();
        let exact_work = accounting.work_or_linear_terms();
        assert!(exact_work > 0);
        let exact = SearchLimits {
            max_work: exact_work,
            max_scratch_bytes: usize::MAX,
        };
        let exact_token = work_search.prepare_is_match_value_token(line.len(), exact);
        assert_eq!(
            work_search.is_match_value_prepared(line, exact_token),
            work_search.is_match_value(line, exact),
        );

        let one_below_work = SearchLimits {
            max_work: exact_work - 1,
            max_scratch_bytes: usize::MAX,
        };
        let one_below_token = work_search.prepare_is_match_value_token(line.len(), one_below_work);
        let prepared_error = work_search
            .is_match_value_prepared(line, one_below_token)
            .unwrap_err();
        let incumbent_error = work_search
            .is_match_value(line, one_below_work)
            .unwrap_err();
        assert_eq!(prepared_error, incumbent_error);

        let mut scratch_search = regex.search_session(setup_limits).unwrap();
        let retained = scratch_search
            .workspace_setup_accounting()
            .unwrap()
            .retained_bytes();
        assert!(retained > 0);
        let one_below_scratch = SearchLimits {
            max_work: u64::MAX,
            max_scratch_bytes: retained - 1,
        };
        let scratch_token =
            scratch_search.prepare_k0_warm_is_match_value_token(line.len(), one_below_scratch);
        assert!(!scratch_token.uses_k0_warm_route());
        let prepared_error = scratch_search
            .is_match_value_prepared(line, scratch_token)
            .unwrap_err();
        let incumbent_error = scratch_search
            .is_match_value(line, one_below_scratch)
            .unwrap_err();
        assert_eq!(prepared_error, incumbent_error);
    }

    #[test]
    fn prepared_byte_class_delimiter_is_differential_bounded_and_strictly_line_scoped() {
        let pattern = r"([^ @]+)@([^ @]+)";
        let limits = SearchLimits::unlimited();
        let regex = current_fre_rebar_portable_builder(pattern, false, false)
            .unwrap()
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        let mut search = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let token = search.prepare_is_match_value_token(32, limits);
        assert!(token.uses_prepared_route());
        assert!(token.uses_byte_class_delimiter_route());
        assert!(!token.uses_k0_warm_route());
        assert!(formal_rebar_prepared_is_match_token(token));
        assert_eq!(token.maximum_warm_input_bytes(), Some(32));
        let bound = search
            .bind_byte_class_delimiter_is_match_value_token(token)
            .expect("token must bind to its construction owner");

        let mut corpus = vec![Vec::new()];
        let mut frontier = vec![Vec::new()];
        for _ in 0..7 {
            let mut next = Vec::new();
            for prefix in frontier {
                for byte in [b'a', b'b', b'@', b' ', 0xFF] {
                    let mut candidate = prefix.clone();
                    candidate.push(byte);
                    next.push(candidate);
                }
            }
            corpus.extend(next.iter().cloned());
            frontier = next;
        }
        for line in &corpus {
            assert_eq!(
                search.is_match_value_prepared(line, token),
                regex.is_match_value(line, limits),
                "prepared byte-class delimiter differed for {line:?}",
            );
            assert_eq!(
                bound.try_is_match(line),
                Some(regex.is_match_value(line, limits).unwrap()),
                "bound byte-class delimiter differed for {line:?}",
            );
        }

        // A token from another exact delimiter language and an input beyond
        // the certified envelope both replay the ordinary finite-limit path.
        let other = current_fre_rebar_portable_builder(r"([^ :]+):([^ :]+)", false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(
            other_search
                .bind_byte_class_delimiter_is_match_value_token(token)
                .is_none()
        );
        assert_eq!(
            other_search.is_match_value_prepared(b"a:b", token),
            other.is_match_value(b"a:b", limits),
        );
        let over = vec![b'a'; 33];
        assert_eq!(bound.try_is_match(&over), None);
        assert_eq!(
            search.is_match_value_prepared(&over, token),
            regex.is_match_value(&over, limits),
        );

        let finite = SearchLimits {
            max_work: 8,
            max_scratch_bytes: usize::MAX,
        };
        let mut finite_prepared = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let finite_token = finite_prepared.prepare_is_match_value_token(16, finite);
        assert_eq!(finite_token.maximum_warm_input_bytes(), Some(2));
        let mut finite_incumbent = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(
            finite_prepared
                .is_match_value_prepared(b"a@b", finite_token)
                .is_err()
        );
        assert!(finite_incumbent.is_match_value(b"a@b", finite).is_err());

        // The formal route still invokes the retained matcher exactly once
        // for each ByteSlice::lines domain, including CRLF and malformed
        // bytes. Only the implementation of that one call changes.
        let haystack = b"a@b\r\nmiss\n\xFF@\xFE\nleft@\n@right\nlast";
        let rust = rust_compile_options(&[pattern.to_string()], false, false).unwrap();
        let expected = grep(&rust, haystack, RunLimits::default().reducer_steps).unwrap();
        let mut session = current_fre_rebar_grep_session(&regex, haystack.len()).unwrap();
        assert!(!session.uses_prepared_byte_class_delimiter_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
        assert!(session.uses_prepared_byte_class_delimiter_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);

        let unicode = current_fre_rebar_portable_builder(pattern, true, false)
            .unwrap()
            .build()
            .unwrap();
        let unicode_search = unicode
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let unicode_token = unicode_search.prepare_is_match_value_token(32, limits);
        assert!(!unicode_token.uses_byte_class_delimiter_route());
    }

    #[test]
    fn prepared_uri_like_is_differential_bounded_and_strictly_line_scoped() {
        let uri = r"([a-zA-Z][a-zA-Z0-9]*)://([^ /]+)(/[^ ]*)?";
        let capture_free = r"[a-zA-Z][a-zA-Z0-9]*://[^ /]+(?:/[^ ]*)?";
        let either = format!(r"{uri}|([^ @]+)@([^ @]+)");
        let limits = SearchLimits::unlimited();
        for pattern in [uri, capture_free, either.as_str()] {
            let regex = current_fre_rebar_portable_builder(pattern, false, false)
                .unwrap()
                .build()
                .unwrap();
            assert_eq!(regex.build_report().plan, PlanKind::K0);
            let mut search = regex
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            let token = search.prepare_is_match_value_token(32, limits);
            assert!(token.uses_prepared_route());
            assert!(token.uses_uri_like_route());
            assert!(!formal_rebar_prepared_is_match_token(token));
            assert_eq!(
                token.uses_fused_uri_like_composite_route(),
                pattern == either
            );
            assert!(!token.uses_k0_warm_route());
            assert_eq!(token.maximum_warm_input_bytes(), Some(32));
            let mut generic_search = regex
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            let generic_token = generic_search.prepare_k0_warm_is_match_value_token(32, limits);
            assert!(generic_token.uses_k0_warm_route());
            assert!(formal_rebar_prepared_is_match_token(generic_token));
            assert_eq!(generic_token.maximum_warm_input_bytes(), Some(32));

            let mut corpus = vec![Vec::new()];
            let mut frontier = vec![Vec::new()];
            for _ in 0..6 {
                let mut next = Vec::new();
                for prefix in frontier {
                    for byte in [b'a', b'1', b':', b'/', b'@', b' ', 0xFF] {
                        let mut candidate = prefix.clone();
                        candidate.push(byte);
                        next.push(candidate);
                    }
                }
                corpus.extend(next.iter().cloned());
                frontier = next;
            }
            for line in &corpus {
                assert_eq!(
                    search.is_match_value_prepared(line, token),
                    regex.is_match_value(line, limits),
                    "prepared URI predicate differed for {pattern:?} over {line:?}",
                );
                assert_eq!(
                    generic_search.is_match_value_prepared(line, generic_token),
                    regex.is_match_value(line, limits),
                    "generic K0 warm URI result differed for {pattern:?} over {line:?}",
                );
            }

            let finite = SearchLimits {
                max_work: 39,
                max_scratch_bytes: usize::MAX,
            };
            let finite_token = search.prepare_is_match_value_token(32, finite);
            let expected_maximum = if pattern == either { 4 } else { 6 };
            assert_eq!(
                finite_token.maximum_warm_input_bytes(),
                Some(expected_maximum),
            );
            let over = b"http://x";
            assert!(search.is_match_value_prepared(over, finite_token).is_err());
            assert!(regex.is_match_value(over, finite).is_err());
        }

        // The composite keeps its prior 9N prospective work envelope. At the
        // exact boundary the fused token executes directly; one unit below it
        // refuses that input length and replays the unchanged finite semantic
        // search rather than publishing a result from the fused route.
        let composite = current_fre_rebar_portable_builder(&either, false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut composite_search = composite
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let exact_limits = SearchLimits {
            max_work: 27,
            max_scratch_bytes: usize::MAX,
        };
        let exact_token = composite_search.prepare_is_match_value_token(3, exact_limits);
        assert!(exact_token.uses_fused_uri_like_composite_route());
        assert_eq!(exact_token.maximum_warm_input_bytes(), Some(3));
        assert!(
            composite_search
                .is_match_value_prepared(b"1@b", exact_token)
                .unwrap()
        );
        let one_below_limits = SearchLimits {
            max_work: 26,
            max_scratch_bytes: usize::MAX,
        };
        let one_below_token = composite_search.prepare_is_match_value_token(3, one_below_limits);
        assert_eq!(one_below_token.maximum_warm_input_bytes(), Some(2));
        assert!(
            composite_search
                .is_match_value_prepared(b"1@b", one_below_token)
                .is_err()
        );
        assert!(composite.is_match_value(b"1@b", one_below_limits).is_err());

        // The formal route invokes the ordinary retained semantic matcher for
        // every LF/CRLF domain, including malformed bytes.
        let regex = current_fre_rebar_portable_builder(&either, false, false)
            .unwrap()
            .build()
            .unwrap();
        let haystack = b"http://x\r\nmiss\n\xFF://\xFE\na@b\n123://x\nlast";
        let rust = rust_compile_options(&[either], false, false).unwrap();
        let expected = grep(&rust, haystack, RunLimits::default().reducer_steps).unwrap();
        let mut session = current_fre_rebar_grep_session(&regex, haystack.len()).unwrap();
        assert!(!session.uses_prepared_uri_like_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
        assert!(!session.uses_prepared_uri_like_is_match());
        assert!(!session.uses_prepared_fused_uri_like_composite_is_match());
        assert!(session.uses_prepared_k0_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);

        // A token scratch-envelope decline, cross-plan token use and nearby
        // HIRs all replay the incumbent finite-limit search rather than
        // publishing a direct result under a mismatched proof.
        let uri_regex = current_fre_rebar_portable_builder(uri, false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut scratch_search = uri_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let retained = scratch_search
            .workspace_setup_accounting()
            .unwrap()
            .retained_bytes();
        assert!(retained > 0);
        let scratch_limits = SearchLimits {
            max_work: u64::MAX,
            max_scratch_bytes: retained - 1,
        };
        let scratch_token = scratch_search.prepare_is_match_value_token(32, scratch_limits);
        assert!(!scratch_token.uses_uri_like_route());
        let mut ordinary_scratch_search = uri_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            scratch_search.is_match_value_prepared(b"http://x", scratch_token),
            ordinary_scratch_search.is_match_value(b"http://x", scratch_limits),
        );

        let source_search = uri_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let source_token = source_search.prepare_is_match_value_token(32, limits);
        let other = current_fre_rebar_portable_builder(r"[A-Z][A-Z0-9]*=>[^ ]+", false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            other_search.is_match_value_prepared(b"A=>x", source_token),
            other.is_match_value(b"A=>x", limits),
        );

        for nearby in [
            r"[a-z][a-z0-9]+://[^ /]+",
            r"[a-z][a-z0-9]*a[^ /]+",
            r"^[a-z][a-z0-9]*://[^ /]+",
        ] {
            let nearby = current_fre_rebar_portable_builder(nearby, false, false)
                .unwrap()
                .build()
                .unwrap();
            let nearby_search = nearby
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            assert!(
                !nearby_search
                    .prepare_is_match_value_token(32, limits)
                    .uses_uri_like_route()
            );
        }

        let unicode = current_fre_rebar_portable_builder(uri, true, false)
            .unwrap()
            .build()
            .unwrap();
        let unicode_search = unicode
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let unicode_token = unicode_search.prepare_is_match_value_token(32, limits);
        assert!(!unicode_token.uses_uri_like_route());
    }

    #[test]
    fn prepared_anchored_scalar_corridor_is_exact_bounded_and_line_scoped() {
        const PATTERN: &str = r"^[ \t\x0C]*#.*?coding[:=][ \t]*utf-?8";
        let limits = SearchLimits::unlimited();
        let fre_regex = current_fre_rebar_portable_builder(PATTERN, true, false)
            .unwrap()
            .build()
            .unwrap();
        assert_eq!(fre_regex.build_report().plan, PlanKind::K0);
        let mut search = fre_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let token = search.prepare_is_match_value_token(256, limits);
        assert!(token.uses_prepared_route());
        assert!(token.uses_anchored_scalar_corridor_route());
        assert!(!token.uses_k0_warm_route());
        assert!(!formal_rebar_prepared_is_match_token(token));
        assert_eq!(token.maximum_warm_input_bytes(), Some(256));

        let oracle = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(true)
            .build()
            .unwrap();
        let directed: &[&[u8]] = &[
            b"",
            b"# coding: utf-8",
            b" # coding=utf8 suffix",
            b"\t\x0c# -*- coding: utf-8 -*-",
            b"x # coding: utf-8",
            b"# coding! coding: utf-8",
            b"# coding: utf--8",
            b"# coding: utf-",
            b"# \xffcoding: utf-8",
            b"# \xce\xb1 coding: utf-8",
            b"# before\ncoding: utf-8",
            b"# coding: utf-8\xff",
            b"\xff# coding: utf-8",
            b"# coding: \xffutf-8",
        ];
        for &line in directed {
            assert_eq!(
                search.is_match_value_prepared(line, token).unwrap(),
                oracle.is_match(line),
                "anchored scalar corridor differed for {line:?}",
            );
        }

        let leading: &[&[u8]] = &[b"", b" ", b"\t\x0c", b"x", b"\xff"];
        let corridor: &[&[u8]] = &[b"", b"x", b"coding! ", b"\xce\xb1", b"\xff", b"x\n"];
        let separator: &[&[u8]] = &[b":", b"=", b"!", b"\xff"];
        let spacing: &[&[u8]] = &[b"", b" ", b"\t ", b"x"];
        let ending: &[&[u8]] = &[b"utf8", b"utf-8", b"utf--8", b"utf-", b"utf9"];
        for &left in leading {
            for &middle in corridor {
                for &delimiter in separator {
                    for &space in spacing {
                        for &end in ending {
                            let mut line = Vec::new();
                            line.extend_from_slice(left);
                            line.push(b'#');
                            line.extend_from_slice(middle);
                            line.extend_from_slice(b"coding");
                            line.extend_from_slice(delimiter);
                            line.extend_from_slice(space);
                            line.extend_from_slice(end);
                            assert_eq!(
                                search.is_match_value_prepared(&line, token).unwrap(),
                                oracle.is_match(&line),
                                "anchored scalar corridor differed for {line:?}",
                            );
                        }
                    }
                }
            }
        }

        // Byte mode accepts malformed corridor bytes exactly as the original
        // bytes regex does; Unicode mode stops at the first malformed scalar.
        let byte_regex = current_fre_rebar_portable_builder(PATTERN, false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut byte_search = byte_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let byte_token = byte_search.prepare_is_match_value_token(64, limits);
        assert!(byte_token.uses_anchored_scalar_corridor_route());
        assert!(
            byte_search
                .is_match_value_prepared(b"# \xffcoding: utf-8", byte_token)
                .unwrap()
        );

        // Exact and one-below linear envelopes either take the direct route
        // or replay the unchanged finite-limit incumbent.
        let exact_limits = SearchLimits {
            max_work: 10 * 32,
            max_scratch_bytes: usize::MAX,
        };
        let exact_token = search.prepare_is_match_value_token(10, exact_limits);
        assert_eq!(exact_token.maximum_warm_input_bytes(), Some(10));
        let one_below_limits = SearchLimits {
            max_work: 10 * 32 - 1,
            max_scratch_bytes: usize::MAX,
        };
        let one_below_token = search.prepare_is_match_value_token(10, one_below_limits);
        assert_eq!(one_below_token.maximum_warm_input_bytes(), Some(9));
        let ten_bytes = b"#coding:ux";
        let mut one_below_prepared = fre_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let one_below_token = one_below_prepared.prepare_is_match_value_token(10, one_below_limits);
        let mut one_below_incumbent = fre_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            one_below_prepared.is_match_value_prepared(ten_bytes, one_below_token),
            one_below_incumbent.is_match_value(ten_bytes, one_below_limits),
        );

        // A token never authenticates a different structural plan, and nearby
        // HIRs that invalidate an exact proof retain the incumbent route.
        let other_pattern = r"^[ ]*!.*?needle[;][ ]*ok_?x";
        let other = current_fre_rebar_portable_builder(other_pattern, true, false)
            .unwrap()
            .build()
            .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let other_line = b"! needle; ok_x";
        assert_eq!(
            other_search.is_match_value_prepared(other_line, token),
            other.is_match_value(other_line, limits),
        );
        for nearby in [
            r"(?m:^[ \t\x0C]*#.*?coding[:=][ \t]*utf-?8)",
            r"^[ #]*#.*?coding[:=][ ]*utf-?8",
            r"^[ ]*#[^\r]*?coding[:=][ ]*utf-?8",
            r"^[ ]*#.*?coc[:=][ ]*utf-?8",
            r"^[ ]*#.*?coding[:=][ c]*utf-?8",
            r"^[ α]*#.*?coding[:=][ ]*utf-?8",
            r"^[ ]*#.*?coding[:=][ ]*utf-{0,2}8",
        ] {
            let nearby = current_fre_rebar_portable_builder(nearby, true, false)
                .unwrap()
                .build()
                .unwrap();
            let nearby_search = nearby
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            assert!(
                !nearby_search
                    .prepare_is_match_value_token(64, limits)
                    .uses_anchored_scalar_corridor_route(),
                "nearby HIR unexpectedly admitted: {nearby}",
            );
        }

        // The formal adapter invokes the ordinary retained semantic matcher on
        // every exact ByteSlice::lines domain, including CRLF and malformed
        // domains.
        let haystack =
            b"# coding: utf-8\r\nx # coding: utf-8\n# \xffcoding: utf-8\n# coding=utf8\nlast";
        let rust = rust_compile_options(&[PATTERN.to_string()], true, false).unwrap();
        let expected = grep(&rust, haystack, RunLimits::default().reducer_steps).unwrap();
        let mut session = current_fre_rebar_grep_session(&fre_regex, haystack.len()).unwrap();
        assert!(!session.uses_prepared_anchored_scalar_corridor_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
        assert!(!session.uses_prepared_anchored_scalar_corridor_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
    }

    #[test]
    fn prepared_bounded_delimited_fields_are_exact_bounded_and_line_scoped() {
        const PATTERN: &str = r"([0-9][0-9]?)/([0-9][0-9]?)/([0-9][0-9]([0-9][0-9])?)";
        let limits = SearchLimits::unlimited();
        let fre_regex = current_fre_rebar_portable_builder(PATTERN, false, false)
            .unwrap()
            .build()
            .unwrap();
        assert_eq!(fre_regex.build_report().plan, PlanKind::K0);
        let mut search = fre_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let token = search.prepare_is_match_value_token(256, limits);
        assert!(token.uses_prepared_route());
        assert!(token.uses_bounded_delimited_route());
        assert!(!token.uses_k0_warm_route());
        assert!(!formal_rebar_prepared_is_match_token(token));
        assert_eq!(token.maximum_warm_input_bytes(), Some(256));

        let oracle = regex::bytes::RegexBuilder::new(PATTERN)
            .unicode(false)
            .build()
            .unwrap();
        for line in [
            b"".as_slice(),
            b"1/2/34",
            b"12/34/5678",
            b"prefix 12/3/45 suffix",
            b"1/2/345",
            b"1//23",
            b"111/2/34",
            b"\xff12/3/45\xfe",
            b"12/3/45\n",
        ] {
            assert_eq!(
                search.is_match_value_prepared(line, token).unwrap(),
                oracle.is_match(line),
                "bounded delimited result differed for {line:?}",
            );
        }
        let mut frontier = vec![Vec::new()];
        for _ in 0..=7 {
            for line in &frontier {
                assert_eq!(
                    search.is_match_value_prepared(line, token).unwrap(),
                    oracle.is_match(line),
                    "bounded delimited result differed for exhaustive bytes {line:?}",
                );
            }
            let mut next = Vec::new();
            for prefix in frontier {
                for byte in [b'0', b'/', b'x', 0xff] {
                    let mut line = prefix.clone();
                    line.push(byte);
                    next.push(line);
                }
            }
            frontier = next;
        }

        // One byte beyond the linear envelope and a token from a different
        // matcher both replay the unchanged finite-limit facade.
        let finite = SearchLimits {
            max_work: 48 * 10 - 1,
            max_scratch_bytes: usize::MAX,
        };
        let over = b"12/34/5678";
        let mut prepared = fre_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let finite_token = prepared.prepare_is_match_value_token(over.len(), finite);
        assert_eq!(finite_token.maximum_warm_input_bytes(), Some(9));
        let mut incumbent = fre_regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            prepared.is_match_value_prepared(over, finite_token),
            incumbent.is_match_value(over, finite),
        );

        let other =
            current_fre_rebar_portable_builder(r"[A-F]{1,2}:[A-F]{1,2}:[A-F]{2}", false, false)
                .unwrap()
                .build()
                .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            other_search.is_match_value_prepared(b"A:B:CD", token),
            other.is_match_value(b"A:B:CD", limits),
        );

        for nearby in [
            r"[0-9]+/[0-9]{1,2}/[0-9]{2}",
            r"[0-9]{1,2}-[0-9]{1,2}/[0-9]{2}",
            r"[0-9]{1,2}/[0-9A-F]{1,2}/[0-9]{2}",
            r"^[0-9]{1,2}/[0-9]{1,2}/[0-9]{2}",
        ] {
            let nearby = current_fre_rebar_portable_builder(nearby, false, false)
                .unwrap()
                .build()
                .unwrap();
            let nearby_search = nearby
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            assert!(
                !nearby_search
                    .prepare_is_match_value_token(64, limits)
                    .uses_bounded_delimited_route(),
                "nearby HIR unexpectedly admitted: {nearby}",
            );
        }

        // The adapter makes one ordinary retained semantic matcher call on
        // every ByteSlice::lines domain, including CRLF and malformed data.
        let haystack = b"1/2/34\r\nmiss\n\xff12/3/45\xfe\n1/2/345\nlast";
        let rust = rust_compile_options(&[PATTERN.to_string()], false, false).unwrap();
        let expected = grep(&rust, haystack, RunLimits::default().reducer_steps).unwrap();
        let mut session = current_fre_rebar_grep_session(&fre_regex, haystack.len()).unwrap();
        assert!(!session.uses_prepared_bounded_delimited_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
        assert!(!session.uses_prepared_bounded_delimited_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
    }

    #[test]
    fn prepared_unicode_word_run_is_differential_bounded_and_strictly_line_scoped() {
        let pattern = r"\b\w{3,}\b";
        let limits = SearchLimits {
            max_work: 64,
            max_scratch_bytes: 0,
        };
        let regex = current_fre_rebar_portable_builder(pattern, true, false)
            .unwrap()
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::UnicodeWordRun);
        let mut search = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let token = search.prepare_is_match_value_token(32, limits);
        assert!(token.uses_prepared_route());
        assert!(token.uses_unicode_word_run_route());
        assert!(!token.uses_k0_warm_route());
        assert!(formal_rebar_prepared_is_match_token(token));
        assert_eq!(token.maximum_warm_input_bytes(), Some(32));

        let cases: &[&[u8]] = &[
            b"",
            b"ab",
            b"abc",
            "--αβγ--".as_bytes(),
            "aβ_".as_bytes(),
            b"ab\xFFcde\xFE",
            b"a-b-c",
        ];
        for _ in 0..2 {
            for &line in cases {
                assert_eq!(
                    search.is_match_value_prepared(line, token),
                    regex.is_match_value(line, limits),
                    "prepared Unicode word run differed for {line:?}",
                );
            }
        }

        let mut corpus = vec![Vec::new()];
        let mut frontier = vec![Vec::new()];
        for _ in 0..5 {
            let mut next = Vec::new();
            for prefix in frontier {
                for byte in [b'a', b'-', 0xFF, 0xCE, 0xB1] {
                    let mut word = prefix.clone();
                    word.push(byte);
                    next.push(word);
                }
            }
            corpus.extend(next.iter().cloned());
            frontier = next;
        }
        for line in &corpus {
            let expected = regex.is_match_value(line, limits);
            assert_eq!(
                search.is_match_value_prepared(line, token),
                expected,
                "prepared Unicode word run differed for exhaustive bytes {line:?}",
            );
            let (_, accounting) = regex
                .is_match(line, SearchLimits::unlimited())
                .expect("unlimited Unicode word run");
            assert!(
                accounting.work_or_linear_terms()
                    <= u64::try_from(line.len()).unwrap().saturating_mul(2),
                "Unicode word-run work exceeded the prepared envelope for {line:?}",
            );
        }

        // A differently shaped word-run token and an input beyond the proved
        // work envelope both replay the ordinary finite-limit operation.
        let other = current_fre_rebar_portable_builder(r"\b\w{4,}\b", true, false)
            .unwrap()
            .build()
            .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            other_search.is_match_value_prepared("αβγδ".as_bytes(), token),
            other.is_match_value("αβγδ".as_bytes(), limits),
        );
        let over = vec![b'a'; 33];
        assert_eq!(
            search.is_match_value_prepared(&over, token),
            regex.is_match_value(&over, limits),
        );

        let refusal_line = b"---";
        let one_below = SearchLimits {
            max_work: 2,
            max_scratch_bytes: 0,
        };
        let refusal_token = search.prepare_is_match_value_token(refusal_line.len(), one_below);
        assert_eq!(refusal_token.maximum_warm_input_bytes(), Some(1));
        assert_eq!(
            search.is_match_value_prepared(refusal_line, refusal_token),
            regex.is_match_value(refusal_line, one_below),
        );

        // The formal route still invokes the retained semantic matcher once
        // for every exact ByteSlice::lines domain, including malformed bytes.
        let haystack = b"ab\r\nabc\n\xFFcde\xFE\nlast";
        let rust = rust_compile_options(&[pattern.to_string()], true, false).unwrap();
        let expected = grep(&rust, haystack, RunLimits::default().reducer_steps).unwrap();
        let mut session = current_fre_rebar_grep_session(&regex, haystack.len()).unwrap();
        assert!(!session.uses_prepared_unicode_word_run_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);
        assert!(session.uses_prepared_unicode_word_run_is_match());
        assert_eq!(session.execute(haystack).unwrap(), expected);

        // The optimized ASCII run scanner remains on its incumbent path.
        let ascii = current_fre_rebar_portable_builder(pattern, false, false)
            .unwrap()
            .build()
            .unwrap();
        let ascii_search = ascii
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let ascii_token = ascii_search.prepare_is_match_value_token(32, limits);
        assert!(!ascii_token.uses_prepared_route());
    }

    #[test]
    fn strict_rebar_line_models_match_rust_on_crlf_misses_and_optional_groups() {
        let limits = RunLimits::default();
        let grep_pattern = r"^ab$";
        let grep_haystack = b"ab\r\nmiss\nab\nlast";
        let rust_grep = rust_compile_options(&[grep_pattern.to_string()], false, false)
            .expect("Rust grep reference");
        let expected_grep =
            grep(&rust_grep, grep_haystack, limits.reducer_steps).expect("Rust grep reducer");
        assert_current_fre_execution(
            current_fre(
                "grep",
                &[grep_pattern.to_string()],
                grep_haystack,
                false,
                false,
                &limits,
            ),
            expected_grep,
            CURRENT_FRE_REBAR_GREP_PLAN,
        );

        let capture_pattern = r"(a)(b)?";
        let capture_haystack = b"a\r\nab\n\xFFmiss\naba";
        let rust_captures = rust_compile_options(&[capture_pattern.to_string()], false, false)
            .expect("Rust capture reference");
        let expected_captures =
            grep_captures(&rust_captures, capture_haystack, limits.reducer_steps)
                .expect("Rust grep-captures reducer");
        assert_current_fre_execution(
            current_fre(
                "grep-captures",
                &[capture_pattern.to_string()],
                capture_haystack,
                false,
                false,
                &limits,
            ),
            expected_captures,
            CURRENT_FRE_REBAR_GREP_CAPTURES_PLAN,
        );
        let mut lifecycle = current_fre_rebar_capture_lifecycle(
            "grep-captures",
            capture_pattern,
            false,
            false,
            capture_haystack.len(),
        )
        .expect("strict capture lifecycle");
        assert_eq!(lifecycle.plan(), CURRENT_FRE_REBAR_GREP_CAPTURES_PLAN);
        assert_eq!(
            lifecycle.execute(capture_haystack).expect("first"),
            expected_captures
        );
        assert_eq!(
            lifecycle.execute(capture_haystack).expect("steady"),
            expected_captures
        );

        let count_haystack = b"a ab miss aba";
        let expected_count = count_captures(&rust_captures, count_haystack, limits.reducer_steps)
            .expect("Rust count-captures reducer");
        assert_current_fre_execution(
            current_fre(
                "count-captures",
                &[capture_pattern.to_string()],
                count_haystack,
                false,
                false,
                &limits,
            ),
            expected_count,
            CURRENT_FRE_REBAR_COUNT_CAPTURES_PLAN,
        );
        let mut count_lifecycle = current_fre_rebar_capture_lifecycle(
            "count-captures",
            capture_pattern,
            false,
            false,
            count_haystack.len(),
        )
        .expect("strict count-captures lifecycle");
        assert_eq!(
            count_lifecycle.plan(),
            CURRENT_FRE_REBAR_COUNT_CAPTURES_PLAN
        );
        assert_eq!(
            count_lifecycle.execute(count_haystack).expect("first"),
            expected_count
        );
        assert_eq!(
            count_lifecycle.execute(count_haystack).expect("steady"),
            expected_count
        );
    }

