    #[test]
    fn strict_rebar_descending_class_records_match_rust_and_refuse_nearby_shapes() {
        let pattern = r"([A-Za-z]{5})|([A-Za-z]{3})|([A-Za-z]{2})";
        let haystack = b"abcdef x ab\r\n\xffaabaa\nzzzzz\n";
        let rust = rust_compile_options(&[pattern.to_string()], false, false)
            .expect("Rust descending-class capture reference");
        let expected = grep_captures(&rust, haystack, u64::MAX)
            .expect("Rust descending-class grep-captures reducer");
        let mut lifecycle = current_fre_rebar_capture_lifecycle(
            "grep-captures",
            pattern,
            false,
            false,
            haystack.len(),
        )
        .expect("strict descending-class record lifecycle");
        assert!(matches!(
            &lifecycle.regex,
            CurrentFreCaptureRegex::General(_)
        ));
        assert!(matches!(
            &lifecycle.preparation,
            CurrentFreCapturePreparation::MaterializedLines(_)
        ));
        assert_eq!(lifecycle.plan(), CURRENT_FRE_REBAR_GREP_CAPTURES_PLAN);
        assert_eq!(lifecycle.execute(haystack).expect("first"), expected);
        assert_eq!(lifecycle.execute(haystack).expect("steady"), expected);

        for (control, unicode, case_insensitive) in [
            (r"([A-Za-z]{2})|([A-Za-z]{3})", false, false),
            (
                r"\b(?:([A-Za-z]{5})|([A-Za-z]{3})|([A-Za-z]{2}))\b",
                false,
                false,
            ),
            (pattern, true, false),
            (pattern, false, true),
        ] {
            let control_lifecycle = current_fre_rebar_capture_lifecycle(
                "grep-captures",
                control,
                unicode,
                case_insensitive,
                haystack.len(),
            )
            .expect("nearby control remains on exact general records");
            assert!(matches!(
                &control_lifecycle.regex,
                CurrentFreCaptureRegex::General(_)
            ));
            assert!(matches!(
                &control_lifecycle.preparation,
                CurrentFreCapturePreparation::MaterializedLines(_)
            ));
        }
    }

    #[test]
    fn strict_rebar_descending_class_record_slots_match_rust_exhaustively() {
        let pattern = r"([ab]{5})|([ab]{3})|([ab]{2})";
        let plan = CaptureRunAlternationBuilder::new(pattern)
            .profile(rebar_profile())
            .unicode(false)
            .build()
            .unwrap();
        let oracle = regex::bytes::RegexBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        let alphabet = [b'a', b'b', b'x', b'\r', 0xff];
        for length in 0..=6_usize {
            let variants = alphabet.len().pow(u32::try_from(length).unwrap());
            let upper = plan.run_upper_bounds(length).unwrap();
            let run_limits = CaptureRunAlternationRunLimits {
                max_input_bytes: upper.input_bytes,
                max_source_reads: upper.source_reads,
                max_decoded_units: upper.decoded_units,
                max_class_comparisons: upper.class_comparisons,
                max_run_events: upper.run_events,
                max_matches: upper.matches,
                max_capture_count: upper.capture_count,
                max_work: upper.work,
                max_sequential_bytes: upper.sequential_bytes,
                max_peak_bytes: upper.peak_bytes,
            };
            for mut encoded in 0..variants {
                let mut haystack = vec![0_u8; length];
                for byte in &mut haystack {
                    *byte = alphabet[encoded % alphabet.len()];
                    encoded /= alphabet.len();
                }
                let expected = oracle
                    .captures_iter(&haystack)
                    .map(|captures| {
                        captures
                            .iter()
                            .map(|matched| matched.map(|span| (span.start(), span.end())))
                            .collect::<Vec<_>>()
                    })
                    .collect::<Vec<_>>();
                let mut actual = Vec::new();
                let result = plan
                    .visit_exact_byte_class_records(&haystack, run_limits, |record| {
                        actual.push(
                            (0..record.len())
                                .map(|group| record.span(group).map(|span| (span.start, span.end)))
                                .collect::<Vec<_>>(),
                        );
                        assert!(record.span(record.len()).is_none());
                    })
                    .unwrap();
                assert_eq!(actual, expected, "haystack {haystack:?}");
                assert_eq!(result.actual.matches, actual.len());
            }
        }

        let haystack = b"aabaa";
        let upper = plan.run_upper_bounds(haystack.len()).unwrap();
        let mut one_below = CaptureRunAlternationRunLimits {
            max_input_bytes: upper.input_bytes,
            max_source_reads: upper.source_reads,
            max_decoded_units: upper.decoded_units,
            max_class_comparisons: upper.class_comparisons,
            max_run_events: upper.run_events,
            max_matches: upper.matches,
            max_capture_count: upper.capture_count,
            max_work: upper.work,
            max_sequential_bytes: upper.sequential_bytes,
            max_peak_bytes: upper.peak_bytes,
        };
        one_below.max_input_bytes -= 1;
        let mut callbacks = 0_usize;
        let error = plan
            .visit_exact_byte_class_records(haystack, one_below, |_| callbacks += 1)
            .unwrap_err();
        assert_eq!(callbacks, 0);
        assert!(matches!(
            error,
            CaptureRunAlternationRunError::Resource {
                resource: fre::CaptureRunAlternationRunResource::InputBytes,
                ..
            }
        ));
    }

    #[test]
    fn retained_capture_record_visitor_refuses_before_callbacks() {
        for (pattern, anchored) in [(r"(a)", false), (r"^(a)", true)] {
            let regex = CaptureBuilder::new(pattern)
                .unicode(false)
                .build()
                .expect("capture build");
            let mut session = regex
                .prepare_capture_record_visitor(1, CaptureSearchLimits::default(), usize::MAX)
                .expect("retained record visitor");
            assert_eq!(session.is_absolute_start_anchored(), anchored);
            assert_eq!(session.uses_absolute_fixed_onepass(), anchored);
            let mut run_limits = CaptureRunLimits::default();
            run_limits.aggregate.per_search.max_state_visits = 0;
            let mut callbacks = 0_usize;
            let error = session
                .visit_records(b"a", run_limits, |_| callbacks += 1)
                .expect_err("one-below state admission must refuse");
            assert!(matches!(
                error,
                CaptureRecordVisitError::Replay(CaptureSearchError::Resource { .. })
            ));
            assert_eq!(callbacks, 0);
        }

        let pattern = r"(\s*)((?:# [Nn][Oo][Qq][Aa])(?::\s?(([A-Z]+[0-9]+(?:[,\s]+)?)+))?)";
        let haystack = b" # noqa";
        let regex = CaptureBuilder::new(pattern)
            .unicode(false)
            .build()
            .expect("generic History capture build");
        let mut session = regex
            .prepare_capture_record_visitor(
                haystack.len(),
                CaptureSearchLimits::default(),
                usize::MAX,
            )
            .expect("retained History record visitor");
        assert!(!session.uses_fixed_byte_sequence());
        assert!(!session.uses_absolute_fixed_onepass());
        assert!(!session.uses_absolute_full_onepass());
        let mut run_limits = CaptureRunLimits::default();
        run_limits.aggregate.per_search.max_state_visits = 0;
        let mut callbacks = 0_usize;
        let error = session
            .visit_records(haystack, run_limits, |_| callbacks += 1)
            .expect_err("retained History admission must refuse before callbacks");
        assert!(matches!(
            error,
            CaptureRecordVisitError::Replay(CaptureSearchError::Resource { .. })
        ));
        assert_eq!(callbacks, 0);
    }

    #[test]
    fn retained_capture_record_visitor_directly_replays_absolute_fixed_width_onepass() {
        let pattern = r"^([A-Z]{2})([0-9])\b";
        let cases: &[&[u8]] = &[b"AB1 ", b"AB1", b"AB1x", b"A", b"\xFFAB1 ", b"ZZ9-"];
        let rust = rust_compile_options(&[pattern.to_string()], false, false)
            .expect("Rust fixed-width capture reference");
        let regex = CaptureBuilder::new(pattern)
            .unicode(false)
            .build()
            .expect("FRE fixed-width capture build");
        let mut session = regex
            .prepare_capture_record_visitor(6, CaptureSearchLimits::default(), usize::MAX)
            .expect("fixed-width retained record visitor");
        assert!(session.is_absolute_start_anchored());
        assert!(session.uses_absolute_fixed_onepass());
        let persistent_bytes = session.persistent_bytes();
        assert!(persistent_bytes > 0);
        let persistent_refusal = regex
            .prepare_capture_record_visitor(6, CaptureSearchLimits::default(), persistent_bytes - 1)
            .expect_err("one-below direct persistent bytes must refuse");
        assert!(matches!(
            persistent_refusal,
            CaptureRecordVisitError::Replay(CaptureSearchError::Resource { .. })
        ));

        let short_report = session
            .visit_records(b"A", CaptureRunLimits::default(), |_| {
                panic!("short fixed-width domain cannot publish a record")
            })
            .expect("short fixed-width proof miss");
        assert!(short_report.peak_scratch_bytes > 0);
        let mut scratch_one_below = CaptureRunLimits::default();
        scratch_one_below.aggregate.per_search.max_scratch_bytes =
            short_report.peak_scratch_bytes - 1;
        let short_refusal = session
            .visit_records(b"A", scratch_one_below, |_| {
                panic!("scratch refusal cannot publish a record")
            })
            .expect_err("one-below direct scratch must refuse a short domain");
        assert!(matches!(
            short_refusal,
            CaptureRecordVisitError::Replay(CaptureSearchError::Resource { .. })
        ));

        for &haystack in cases {
            let expected = rust
                .captures_iter(Input::new(haystack))
                .map(|captures| {
                    (0..captures.group_len())
                        .map(|index| captures.get_group(index).map(|span| (span.start, span.end)))
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let mut actual = Vec::new();
            let report = session
                .visit_records(haystack, CaptureRunLimits::default(), |groups| {
                    actual.push(
                        groups
                            .iter()
                            .map(|group| group.span().map(|span| (span.start, span.end)))
                            .collect::<Vec<_>>(),
                    );
                })
                .expect("fixed-width exact record visit");
            assert_eq!(actual, expected, "{haystack:?}");
            assert_eq!(report.matches, expected.len());
            assert_eq!(report.searches, 1);
            assert_eq!(report.total_history_nodes, 0);
            assert_eq!(report.total_history_walk, 0);
        }

        for pattern in [r"^([A-Z]+)", r"([A-Z]{2})([0-9])"] {
            let regex = CaptureBuilder::new(pattern)
                .unicode(false)
                .build()
                .expect("FRE refusal-case capture build");
            let session = regex
                .prepare_capture_record_visitor(5, CaptureSearchLimits::default(), usize::MAX)
                .expect("fallback retained record visitor");
            assert!(!session.uses_absolute_fixed_onepass(), "{pattern:?}");
        }
    }

    #[test]
    fn retained_capture_record_visitor_directly_replays_absolute_full_domain_onepass() {
        let pattern = r"^([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z)\t(\w+)\t(\w+)\t([^\t]+)(?:\t(.+))?$";
        let cases: &[&[u8]] = &[
            b"2022-07-27T00:18:48Z\tinfo\ttls\tcleaning storage unit\t{\"description\": \"FileStorage:/root/.local/share/caddy\"}",
            b"2022-07-27T00:18:48Z\tinfo\ttls\tcleaning storage unit",
            b"2022-07-27T00:18:48Z\tinfo\ttls\tcleaning storage unit\t\xff",
            b"2022-07-27T00:18:48Z\tinfo\ttls\t",
            b"x2022-07-27T00:18:48Z\tinfo\ttls\tcleaning storage unit",
            b"2022-07-27T00:18:48Z\tinfo\ttls\tcleaning storage unit\n",
            b"",
        ];
        let rust = rust_compile_options(&[pattern.to_string()], false, false)
            .expect("Rust full-domain capture reference");
        let regex = CaptureBuilder::new(pattern)
            .unicode(false)
            .build()
            .expect("FRE full-domain capture build");
        let maximum = cases.iter().map(|haystack| haystack.len()).max().unwrap();
        let mut session = regex
            .prepare_capture_record_visitor(maximum, CaptureSearchLimits::default(), usize::MAX)
            .expect("full-domain retained record visitor");
        assert!(session.is_absolute_start_anchored());
        assert!(!session.uses_absolute_fixed_onepass());
        assert!(session.uses_absolute_full_onepass());

        let persistent_bytes = session.persistent_bytes();
        let persistent_refusal = regex
            .prepare_capture_record_visitor(
                maximum,
                CaptureSearchLimits::default(),
                persistent_bytes - 1,
            )
            .expect_err("one-below direct persistent bytes must refuse");
        assert!(matches!(
            persistent_refusal,
            CaptureRecordVisitError::Replay(CaptureSearchError::Resource { .. })
        ));

        for &haystack in cases {
            let expected = rust
                .captures_iter(Input::new(haystack))
                .map(|captures| {
                    (0..captures.group_len())
                        .map(|index| captures.get_group(index).map(|span| (span.start, span.end)))
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let mut actual = Vec::new();
            let report = session
                .visit_records(haystack, CaptureRunLimits::default(), |groups| {
                    actual.push(
                        groups
                            .iter()
                            .map(|group| group.span().map(|span| (span.start, span.end)))
                            .collect::<Vec<_>>(),
                    );
                })
                .expect("full-domain exact record visit");
            assert_eq!(actual, expected, "{haystack:?}");
            assert_eq!(report.matches, expected.len());
            assert_eq!(report.searches, 1);
            assert_eq!(report.total_history_nodes, 0);
            assert_eq!(report.total_history_walk, 0);
        }

        let public = cases[0];
        let scratch = session
            .visit_records(public, CaptureRunLimits::default(), |_| {})
            .expect("full-domain scratch accounting")
            .peak_scratch_bytes;
        assert!(scratch > 0);
        let mut one_below = CaptureRunLimits::default();
        one_below.aggregate.per_search.max_scratch_bytes = scratch - 1;
        let mut callbacks = 0_usize;
        let error = session
            .visit_records(public, one_below, |_| callbacks += 1)
            .expect_err("one-below full-domain scratch must refuse");
        assert!(matches!(
            error,
            CaptureRecordVisitError::Replay(CaptureSearchError::Resource { .. })
        ));
        assert_eq!(callbacks, 0);

        for pattern in [r"^([A-Z]+)", r"([A-Z]+)$", r"(?m:^([A-Z]+)$)"] {
            let regex = CaptureBuilder::new(pattern)
                .unicode(false)
                .build()
                .expect("full-domain refusal-case capture build");
            let session = regex
                .prepare_capture_record_visitor(8, CaptureSearchLimits::default(), usize::MAX)
                .expect("fallback retained record visitor");
            assert!(!session.uses_absolute_full_onepass(), "{pattern:?}");
        }
    }

    #[test]
    fn retained_capture_record_visitor_anchors_only_canonical_absolute_start_prefixes() {
        for (pattern, unicode, haystack) in [
            (r"^((a)?)(b?)", false, b"ab\xFF".as_slice()),
            (r"^(?:(β)|())", true, b"\xCE\xB2x\x80".as_slice()),
            (r"^(?:(β)|())", true, b"\xFF\xCE\xB2".as_slice()),
        ] {
            let rust = rust_compile_options(&[pattern.to_string()], unicode, false)
                .expect("Rust absolute-start capture reference");
            let expected = rust
                .captures_iter(Input::new(haystack))
                .map(|captures| {
                    (0..captures.group_len())
                        .map(|index| captures.get_group(index).map(|span| (span.start, span.end)))
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let regex = CaptureBuilder::new(pattern)
                .unicode(unicode)
                .build()
                .expect("FRE absolute-start capture build");
            let mut session = regex
                .prepare_capture_record_visitor(
                    haystack.len(),
                    CaptureSearchLimits::default(),
                    usize::MAX,
                )
                .expect("absolute-start retained record visitor");
            assert!(session.is_absolute_start_anchored());
            let mut actual = Vec::new();
            let report = session
                .visit_records(haystack, CaptureRunLimits::default(), |groups| {
                    actual.push(
                        groups
                            .iter()
                            .map(|group| group.span().map(|span| (span.start, span.end)))
                            .collect::<Vec<_>>(),
                    );
                })
                .expect("absolute-start exact record visit");
            assert_eq!(actual, expected);
            assert_eq!(report.matches, expected.len());
            assert_eq!(report.searches, 1);
        }

        for pattern in [r"(?:^((a)?)|z)", r"(?m:^((a)?))"] {
            let regex = CaptureBuilder::new(pattern)
                .unicode(false)
                .build()
                .expect("non-absolute-start capture build");
            let session = regex
                .prepare_capture_record_visitor(8, CaptureSearchLimits::default(), usize::MAX)
                .expect("non-absolute-start retained record visitor");
            assert!(!session.is_absolute_start_anchored(), "{pattern:?}");
        }
    }

