    #[test]
    fn plain_grep_required_literal_sidecar_preserves_lines_and_reuses_k0() {
        const PATTERN: &str = r"(?:ABC.*Z\z|XY.+Q)";
        let regex = current_fre_rebar_portable_builder(PATTERN, false, false)
            .expect("portable builder")
            .build()
            .expect("portable K0");
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        let search_limits = current_fre_rebar_search_limits();
        let cases: &[&[u8]] = &[
            b"",
            b"\n",
            b"miss\nABCZ\nXYxQ",
            b"ABCZ\r\nmiss\nXY\xFFQ\n",
            b"AB\nCZ\nX\nYxQ",
            b"ABCZ\n\nXYxQ\n",
            b"ABCZ\r",
        ];
        for &haystack in cases {
            let expected = haystack
                .lines()
                .map(|line| {
                    regex
                        .is_match_value(line, search_limits)
                        .expect("line reference")
                })
                .filter(|matched| *matched)
                .count();
            let expected = u64::try_from(expected).expect("line count");
            let mut session = current_fre_rebar_grep_session(&regex, haystack.len())
                .expect("required-literal grep session");
            assert!(!session.has_reusable_k0_workspace());
            assert!(!session.has_required_literal_prefilter());
            assert!(!session.uses_required_literal_prefilter());
            assert_eq!(session.execute(haystack).expect("first"), expected);
            assert!(session.has_reusable_k0_workspace());
            assert_eq!(session.execute(haystack).expect("steady"), expected);
        }

        let mut sparse =
            b"miss\n".repeat(CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES.div_ceil(b"miss\n".len()));
        sparse.extend_from_slice(b"ABCZ\nXYxQ\r\n");
        let mut sparse_session = current_fre_rebar_grep_session(&regex, sparse.len())
            .expect("large sparse required-literal grep session");
        assert!(!sparse_session.has_reusable_k0_workspace());
        assert!(!sparse_session.has_required_literal_prefilter());
        assert!(!sparse_session.uses_required_literal_prefilter());
        assert_eq!(sparse_session.execute(&sparse).expect("sparse first"), 2);
        assert!(sparse_session.has_reusable_k0_workspace());
        assert_eq!(sparse_session.execute(&sparse).expect("sparse steady"), 2);

        for (length, expected_prefilter) in [
            (CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES - 1, false),
            (CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES, false),
        ] {
            let boundary = vec![b'x'; length];
            let mut boundary_session = current_fre_rebar_grep_session(&regex, boundary.len())
                .expect("boundary required-literal grep session");
            assert_eq!(
                boundary_session.uses_required_literal_prefilter(),
                expected_prefilter
            );
            assert_eq!(boundary_session.execute(&boundary).expect("boundary"), 0);
        }
    }

    #[test]
    fn plain_grep_line_total_hir_uses_retained_matcher_token_on_every_line() {
        let regex = current_fre_rebar_portable_builder(r"(?m)^.*$", false, false)
            .expect("portable builder")
            .build()
            .expect("portable line-total K0");
        assert_eq!(regex.build_report().plan, PlanKind::K0);
        assert!(regex.has_line_total_grep_plan());
        let source = b"\r\nalpha\n\xff\rz\nlast\r";
        let mut session =
            current_fre_rebar_grep_session(&regex, source.len()).expect("line-total grep session");
        assert!(!session.uses_line_total_stream());
        assert!(!session.has_reusable_k0_workspace());
        assert!(!session.has_required_literal_prefilter());
        assert!(!session.uses_required_literal_prefilter());
        assert_eq!(session.execute(source).expect("first"), 4);
        assert!(session.has_reusable_k0_workspace());
        assert!(session.uses_prepared_k0_is_match());
        assert_eq!(session.execute(source).expect("steady"), 4);
    }

    #[test]
    fn line_total_match_token_validates_lf_free_domains_and_replays_mismatches() {
        let limits = SearchLimits::unlimited();
        let regex = current_fre_rebar_portable_builder(r"^.*$", false, false)
            .unwrap()
            .build()
            .unwrap();
        assert!(regex.has_line_total_grep_plan());
        let mut search = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let token = search.prepare_is_match_value_token(64, limits);
        assert!(token.uses_k0_warm_route());
        assert!(formal_rebar_prepared_is_match_token(token));
        for line in [
            b"".as_slice(),
            b"plain bytes",
            b"trailing CR\r",
            b"malformed \xFF UTF-8",
        ] {
            assert_eq!(
                search.is_match_value_prepared(line, token).unwrap(),
                regex.is_match_value(line, limits).unwrap(),
            );
        }

        // The structural theorem is line-domain specific. An LF forces the
        // same ordinary semantic matcher path, where absolute anchors reject
        // this multi-line input.
        let multi_line = b"left\nright";
        assert!(!regex.is_match_value(multi_line, limits).unwrap());
        assert!(!search.is_match_value_prepared(multi_line, token).unwrap());

        // A token with no admitted work cannot turn an incumbent refusal into
        // a successful constant result.
        let none = SearchLimits {
            max_work: 0,
            max_scratch_bytes: usize::MAX,
        };
        let refused = search.prepare_is_match_value_token(64, none);
        assert!(!refused.uses_k0_warm_route());
        assert_eq!(
            search.is_match_value_prepared(b"line", refused),
            search.is_match_value(b"line", none),
        );

        // Another matcher cannot consume the proof even when handed the
        // opaque token directly.
        let other = current_fre_rebar_portable_builder(r"^z+$", false, false)
            .unwrap()
            .build()
            .unwrap();
        let mut other_search = other
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            other_search
                .is_match_value_prepared(b"plain bytes", token)
                .unwrap(),
            other.is_match_value(b"plain bytes", limits).unwrap(),
        );
    }

    #[test]
    fn plain_grep_singleton_and_best_concat_prefilters_match_rust_regex() {
        let cases = [
            (
                r"([0-9][0-9]?)/([0-9][0-9]?)/([0-9][0-9]([0-9][0-9])?)",
                false,
                b"published 12/31/2026\n".as_slice(),
            ),
            (
                r"([^ @]+)@([^ @]+)",
                false,
                b"name@example.com\n".as_slice(),
            ),
            (
                r"([a-zA-Z][a-zA-Z0-9]*)://([^ /]+)(/[^ ]*)?",
                false,
                b"visit https://example.com/path\n".as_slice(),
            ),
            (
                r"^[ \t\f]*#.*?coding[:=][ \t]*utf-?8",
                true,
                b"# coding: utf-8\n".as_slice(),
            ),
        ];
        for (pattern, unicode, matching_line) in cases {
            let mut haystack = b"ordinary source line without the delimiter\n".repeat(64);
            haystack.extend_from_slice(matching_line);
            haystack.extend_from_slice(b"another ordinary source line\n");
            assert!(haystack.len() >= CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES);

            let regex = current_fre_rebar_portable_builder(pattern, unicode, false)
                .expect("portable builder")
                .build()
                .expect("portable K0");
            assert_eq!(regex.build_report().plan, PlanKind::K0, "{pattern}");
            let mut session = current_fre_rebar_grep_session(&regex, haystack.len())
                .expect("singleton/best-concat grep session");
            assert!(!session.has_required_literal_prefilter(), "{pattern}");
            assert!(!session.uses_required_literal_prefilter(), "{pattern}");

            let reference = rust_regex_reference_operation_lifecycle(
                "grep",
                &[pattern.to_string()],
                unicode,
                false,
                haystack.len(),
            )
            .expect("pinned Rust regex reference");
            let expected = reference.execute(&haystack).expect("Rust regex grep");
            assert_eq!(session.execute(&haystack).expect("FRE first"), expected);
            assert_eq!(session.execute(&haystack).expect("FRE steady"), expected);
        }
    }

    #[test]
    fn plain_grep_required_literal_admission_is_exact_and_delimiters_fall_back() {
        const SAFE: &str = r"(?:ABC.*Z|XY.+Q)";
        const DELIMITER: &str = r"(?:AB\r.*Z|XY.+Q)";
        let mut haystack =
            b"miss\n".repeat(CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES.div_ceil(b"miss\n".len()));
        haystack.extend_from_slice(b"ABCZ\r\nXYxQ\n");
        let defaults = RunLimits::default();
        let regex = current_fre_rebar_portable_builder(SAFE, false, false)
            .expect("portable builder")
            .build()
            .expect("portable K0");
        let profile = match regex.profile() {
            CompatibilityProfile::RustBytes(profile) => profile.clone(),
            CompatibilityProfile::RustText(_) | CompatibilityProfile::Re2(_) => {
                panic!("portable bytes profile")
            }
        };
        let prefilter_build = capture_required_literal_build_limits(&defaults);
        let mut capture_limits = capture_build_limits(&defaults);
        capture_limits.required_literal = Some(prefilter_build);
        let prefilter = CaptureBuilder::new(SAFE)
            .profile(profile)
            .limits(capture_limits)
            .build_required_literal_plan()
            .expect("sidecar build")
            .expect("sidecar plan");
        let prospective = prefilter
            .line_partition_prospective(haystack.len())
            .expect("line prospective")
            .expect("delimiter-safe proof");
        let exact_work = haystack
            .len()
            .checked_add(prospective.transitions_upper_bound)
            .and_then(|work| work.checked_add(prospective.match_events_upper_bound))
            .expect("exact prefilter work");
        let exact_sequential = haystack.len().checked_mul(2).expect("exact sequential");
        let exact = RunLimits {
            fre_aggregate_operation_work: exact_work,
            fre_aggregate_sequential_bytes: exact_sequential,
            ..defaults.clone()
        };
        let mut exact_session =
            current_fre_rebar_grep_session_with_limits(&regex, haystack.len(), &exact)
                .expect("exact session");
        assert!(!exact_session.uses_required_literal_prefilter());
        assert_eq!(
            exact_session.execute(&haystack).expect("exact operation"),
            2
        );

        let one_below = RunLimits {
            fre_aggregate_operation_work: exact_work - 1,
            ..exact
        };
        let mut refused =
            current_fre_rebar_grep_session_with_limits(&regex, haystack.len(), &one_below)
                .expect("one-below construction");
        assert!(!refused.has_required_literal_prefilter());
        assert!(!refused.uses_required_literal_prefilter());
        assert_eq!(refused.execute(&haystack).expect("one-below fallback"), 2);

        let delimiter_regex = current_fre_rebar_portable_builder(DELIMITER, false, false)
            .expect("delimiter builder")
            .build()
            .expect("delimiter K0");
        assert_eq!(delimiter_regex.build_report().plan, PlanKind::K0);
        let delimiter_source = b"AB\r\nZ\nXYxQ";
        let expected = delimiter_source
            .lines()
            .map(|line| {
                delimiter_regex
                    .is_match_value(line, current_fre_rebar_search_limits())
                    .expect("delimiter line reference")
            })
            .filter(|matched| *matched)
            .count();
        let mut delimiter_session =
            current_fre_rebar_grep_session(&delimiter_regex, delimiter_source.len())
                .expect("delimiter-sensitive session");
        assert!(!delimiter_session.has_required_literal_prefilter());
        assert!(!delimiter_session.uses_required_literal_prefilter());
        assert_eq!(
            delimiter_session
                .execute(delimiter_source)
                .expect("delimiter fallback"),
            u64::try_from(expected).expect("delimiter line count")
        );
    }

    #[test]
    fn plain_grep_required_literal_dense_prefix_cuts_over_to_k0() {
        const PATTERN: &str = r"(?:ABC.*Z|XY.+Q)";
        let regex = current_fre_rebar_portable_builder(PATTERN, false, false)
            .expect("portable builder")
            .build()
            .expect("portable K0");
        let lines = CURRENT_FRE_GREP_PREFILTER_DENSITY_MIN_LINES * 16;
        let haystack = b"ABCZ\n".repeat(lines);
        assert!(haystack.len() >= CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES);
        let mut session = current_fre_rebar_grep_session(&regex, haystack.len())
            .expect("dense required-literal grep session");
        assert!(!session.uses_required_literal_prefilter());
        assert_eq!(
            session.execute(&haystack).expect("dense first"),
            u64::try_from(lines).expect("dense line count")
        );
        assert_eq!(
            session.execute(&haystack).expect("dense steady"),
            u64::try_from(lines).expect("dense line count")
        );

        let minimum = CURRENT_FRE_GREP_PREFILTER_DENSITY_MIN_LINES;
        assert!(!current_fre_grep_should_cut_over_prefilter(
            minimum - 1,
            minimum - 1
        ));
        assert!(!current_fre_grep_should_cut_over_prefilter(
            minimum,
            minimum * 3 / 4 - 1
        ));
        assert!(current_fre_grep_should_cut_over_prefilter(
            minimum,
            minimum * 3 / 4
        ));
        assert!(!current_fre_grep_should_cut_over_prefilter(17, 12));
        assert!(current_fre_grep_should_cut_over_prefilter(17, 13));
    }

    #[test]
    fn plain_grep_required_literal_cutover_preserves_mixed_tail() {
        const PATTERN: &str = r"(?:ABC.*Z|XY.+Q)";
        let regex = current_fre_rebar_portable_builder(PATTERN, false, false)
            .expect("portable builder")
            .build()
            .expect("portable K0");
        let mut haystack = Vec::new();
        for line in 0..CURRENT_FRE_GREP_PREFILTER_DENSITY_MIN_LINES {
            if line % 2 == 0 {
                haystack.extend_from_slice(b"ABCZ\r\n");
            } else {
                haystack.extend_from_slice(b"XYxQ\n");
            }
        }
        for _ in 0..64 {
            haystack.extend_from_slice(b"miss\r\n");
            haystack.extend_from_slice(b"ABC-but-no-uppercase-z\n");
            haystack.extend_from_slice(b"XYxQ\n");
            haystack.extend_from_slice(b"ABC-and-Z\n");
        }
        assert!(haystack.len() >= CURRENT_FRE_GREP_PREFILTER_MIN_SOURCE_BYTES);
        let expected = haystack
            .lines()
            .map(|line| {
                regex
                    .is_match_value(line, current_fre_rebar_search_limits())
                    .expect("line reference")
            })
            .filter(|matched| *matched)
            .count();
        let expected = u64::try_from(expected).expect("mixed-tail line count");
        let mut session = current_fre_rebar_grep_session(&regex, haystack.len())
            .expect("mixed-tail required-literal grep session");
        assert!(!session.uses_required_literal_prefilter());
        assert_eq!(
            session.execute(&haystack).expect("mixed-tail first"),
            expected
        );
        assert_eq!(
            session.execute(&haystack).expect("mixed-tail steady"),
            expected
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the single/ordered compile routing and refusal matrix shares one identity setup"
    )]
    fn current_fre_compile_constructs_fresh_single_and_ordered_many_artifacts() {
        let limits = RunLimits::default();
        assert_current_fre_execution(
            current_fre(
                "compile",
                &["aba".to_string()],
                b"abaaba",
                false,
                false,
                &limits,
            ),
            2,
            "compile-aggregate-exact-literal",
        );
        assert_current_fre_execution(
            current_fre(
                "compile",
                &[r"(?:a+b|a)".to_string()],
                b"aaaab",
                false,
                false,
                &limits,
            ),
            1,
            "compile-aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre(
                "compile",
                &[r"(?P<word>[a-z]+)".to_string()],
                b"Ab C",
                false,
                true,
                &limits,
            ),
            2,
            "compile-aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre(
                "compile",
                &["雪+".to_string()],
                "雪雪".as_bytes(),
                true,
                false,
                &limits,
            ),
            1,
            "compile-aggregate-continuation-program",
        );
        assert_current_fre_execution(
            current_fre(
                "compile",
                &[r"\pL".to_string()],
                "雪".as_bytes(),
                true,
                false,
                &limits,
            ),
            1,
            "compile-aggregate-unicode-scalar-class",
        );

        assert_current_fre_execution(
            current_fre(
                "compile",
                &["ab".to_string(), "a".to_string()],
                b"ab a",
                false,
                false,
                &limits,
            ),
            2,
            "compile-many-ordered-literal",
        );
        assert_current_fre_execution(
            current_fre(
                "compile",
                &[r"a+".to_string(), "a".to_string()],
                b"aa",
                false,
                false,
                &limits,
            ),
            1,
            "compile-many-continuation-program",
        );

        let unicode_profile_refusal = current_fre(
            "compile",
            &["snow".to_string(), r"\w+".to_string()],
            "snow 雪".as_bytes(),
            true,
            false,
            &limits,
        );
        assert!(
            matches!(unicode_profile_refusal, CandidateOutcome::Unsupported(ref reason) if reason.contains("Unicode ordered build-many pattern 1")),
            "unexpected Unicode compile-many outcome: {unicode_profile_refusal:?}"
        );

        let mut bounded = limits;
        bounded.patterns_per_job = 1;
        let resource_refusal = current_fre(
            "compile",
            &["a".to_string(), "(".to_string()],
            b"a",
            false,
            false,
            &bounded,
        );
        assert!(
            matches!(resource_refusal, CandidateOutcome::Unsupported(ref reason) if reason.contains("needs 2 patterns, limit is 1")),
            "unexpected compile-many resource outcome: {resource_refusal:?}"
        );

        let wrong_profile_patterns = vec!["snow".to_string(), "雪".to_string()];
        let wrong_profile = AggregateManyBuilder::new(&wrong_profile_patterns)
            .profile(rebar_profile())
            .unicode(false)
            .build_compile()
            .unwrap();
        let profile_request = CandidateRequest {
            model: "compile",
            patterns: &wrong_profile_patterns,
            haystack: "snow雪".as_bytes(),
            unicode: true,
            case_insensitive: false,
        };
        let mismatch = require_aggregate_many_identity(
            profile_request,
            wrong_profile.build_report(),
            AggregateManyOperation::Compile,
        )
        .unwrap_err();
        assert_eq!(Status::Fault, mismatch.status);
        assert!(
            mismatch
                .message
                .contains("profile/operation identity mismatch")
        );

        assert_current_fre_execution(
            current_fre(
                "compile",
                &[r"[A-Za-z0-9_-]{20,1024}".to_string(), "never".to_string()],
                b"TWITTER_API_KEY",
                false,
                false,
                &RunLimits::default(),
            ),
            0,
            "compile-many-continuation-program",
        );
    }

    #[test]
    fn rust_reference_lifecycles_separate_fresh_compile_from_same_artifact_operations() {
        let patterns = vec![r"(a)(b)?".to_string()];
        let haystack = b"ab a\nzz\nab\n";
        let compile =
            rust_regex_reference_compile_lifecycle(&patterns, false, false, haystack.len())
                .expect("Rust reference compile lifecycle");
        let first_artifact = compile.construct().expect("first fresh Rust artifact");
        assert_eq!(
            first_artifact
                .verify(&compile, haystack)
                .expect("first compile verification"),
            3
        );
        let second_artifact = compile.construct().expect("second fresh Rust artifact");
        assert_eq!(
            second_artifact
                .verify(&compile, haystack)
                .expect("second compile verification"),
            3
        );
        assert!(second_artifact.verify(&compile, b"ab").is_err());

        for (model, expected) in [
            ("count", 3),
            ("count-spans", 5),
            ("count-captures", 8),
            ("grep", 2),
            ("grep-captures", 8),
        ] {
            let lifecycle = rust_regex_reference_operation_lifecycle(
                model,
                &patterns,
                false,
                false,
                haystack.len(),
            )
            .expect("Rust reference operation lifecycle");
            assert_eq!(lifecycle.model(), model);
            assert_eq!(
                lifecycle.execute(haystack).expect("first operation"),
                expected
            );
            assert_eq!(
                lifecycle.execute(haystack).expect("steady operation"),
                expected
            );
            assert!(lifecycle.execute(b"ab").is_err());
        }

        let unicode_patterns = vec![r"\pL+".to_string()];
        let unicode = rust_regex_reference_operation_lifecycle(
            "count",
            &unicode_patterns,
            true,
            true,
            "雪 SNOW".len(),
        )
        .expect("Unicode case-insensitive reference lifecycle");
        assert_eq!(
            unicode
                .execute("雪 SNOW".as_bytes())
                .expect("Unicode reference operation"),
            2
        );

        assert!(rust_regex_reference_compile_lifecycle(&[], false, false, 0).is_err());
        assert!(
            rust_regex_reference_operation_lifecycle(
                "compile",
                &patterns,
                false,
                false,
                haystack.len(),
            )
            .is_err()
        );
        assert!(
            rust_regex_reference_operation_lifecycle("count", &["(".to_string()], false, false, 0,)
                .is_err()
        );
    }

    #[test]
    fn aggregate_lifecycles_separate_construction_from_same_artifact_operations() {
        let haystack = b"aba aba";
        let single_patterns = vec!["aba".to_string()];
        let compile = current_fre_rebar_aggregate_compile_lifecycle(
            &single_patterns,
            false,
            false,
            haystack.len(),
        )
        .expect("single compile lifecycle");
        let first_artifact = compile.construct().expect("first fresh compile artifact");
        assert_eq!(
            first_artifact.plan(&compile).expect("single compile plan"),
            "compile-aggregate-exact-literal"
        );
        let single_verifier = first_artifact
            .complete_match_verifier(&compile)
            .expect("formal complete-match verifier");
        assert_eq!(single_verifier.plan(), "aggregate-continuation-program");
        assert!(matches!(
            &single_verifier.inner,
            CurrentFreAggregateOperationInner::CompleteMatchCountSingle(_, _)
        ));
        assert_eq!(
            first_artifact
                .retained_count(&compile, haystack)
                .expect("retained single compile artifact"),
            2
        );
        assert_eq!(
            first_artifact
                .verify(&compile, haystack)
                .expect("single compile verification"),
            2
        );
        assert_eq!(
            first_artifact
                .retained_count(&compile, b"abb abb")
                .expect("retained same-length compile artifact"),
            0
        );
        assert_eq!(
            first_artifact
                .verify(&compile, b"abb abb")
                .expect("same-length held-out compile verification"),
            0
        );
        let second_artifact = compile.construct().expect("second fresh compile artifact");
        assert_eq!(
            second_artifact
                .verify(&compile, haystack)
                .expect("second compile verification"),
            2
        );
        assert!(second_artifact.verify(&compile, b"aba").is_err());

        let continuation_patterns = vec!["a+".to_string(), "b+".to_string()];
        let continuation_haystack = b"aa bbb";
        let compile_many = current_fre_rebar_aggregate_compile_lifecycle(
            &continuation_patterns,
            false,
            false,
            continuation_haystack.len(),
        )
        .expect("compile-many lifecycle");
        let artifact = compile_many.construct().expect("compile-many artifact");
        assert_eq!(
            artifact.plan(&compile_many).expect("compile-many plan"),
            "compile-many-continuation-program"
        );
        assert_eq!(
            artifact
                .retained_count(&compile_many, continuation_haystack)
                .expect("retained compile-many artifact"),
            2
        );
        assert_eq!(
            artifact
                .verify(&compile_many, continuation_haystack)
                .expect("compile-many verification"),
            2
        );

        let count = current_fre_rebar_aggregate_operation_lifecycle(
            "count",
            &continuation_patterns,
            false,
            false,
            continuation_haystack.len(),
        )
        .expect("count-many lifecycle");
        assert_eq!(count.model(), "count");
        assert_eq!(count.plan(), "aggregate-many-continuation-program");
        assert_eq!(
            count
                .execute(continuation_haystack)
                .expect("first count operation"),
            2
        );
        assert_eq!(
            count
                .execute(continuation_haystack)
                .expect("steady count operation"),
            2
        );
        assert!(count.execute(b"aa").is_err());

        let span_sum = current_fre_rebar_aggregate_operation_lifecycle(
            "count-spans",
            &single_patterns,
            false,
            false,
            haystack.len(),
        )
        .expect("single span-sum lifecycle");
        assert_eq!(span_sum.model(), "count-spans");
        assert_eq!(span_sum.plan(), "aggregate-continuation-program");
        assert!(matches!(
            &span_sum.inner,
            CurrentFreAggregateOperationInner::CompleteSpansSingle(_, _)
        ));
        assert_eq!(span_sum.execute(haystack).expect("span-sum operation"), 6);
        assert!(current_fre_rebar_aggregate_compile_lifecycle(&[], false, false, 0).is_err());
        assert!(
            current_fre_rebar_aggregate_operation_lifecycle(
                "compile",
                &single_patterns,
                false,
                false,
                haystack.len(),
            )
            .is_err()
        );
    }

    #[test]
    fn formal_single_count_spans_streams_every_forced_continuation_bound() {
        std::thread::Builder::new()
            .name("formal-single-count-spans-differential".to_string())
            .stack_size(32 * 1024 * 1024)
            .spawn(formal_single_count_spans_streams_every_forced_continuation_bound_inner)
            .expect("spawn forced-continuation span differential")
            .join()
            .expect("forced-continuation span differential thread");
    }

    fn formal_single_count_spans_streams_every_forced_continuation_bound_inner() {
        let cases: &[(&str, bool, bool, &[u8])] = &[
            ("a*", false, false, b"aba\xFFa"),
            ("a|ab", false, false, b"ababa"),
            (r"(?P<whole>a+)|b", false, false, b"aa b a\xFF"),
            (r"(?m)^.*$", false, false, b"one\n\xFF\ntwo\n"),
            (r"\pL", true, false, "A雪 z".as_bytes()),
            (r"[a-z]+", false, true, b"AA zz \xFF Q"),
        ];

        for &(pattern, unicode, case_insensitive, haystack) in cases {
            let materialized =
                current_fre_rebar_complete_spans_builder(pattern, unicode, case_insensitive)
                    .build_spans()
                    .unwrap_or_else(|error| panic!("materialized {pattern:?}: {error}"));
            let visitor =
                current_fre_rebar_complete_spans_builder(pattern, unicode, case_insensitive)
                    .build_span_visitor()
                    .unwrap_or_else(|error| panic!("visitor {pattern:?}: {error}"));
            assert_eq!(materialized.build_report(), visitor.build_report());
            let materialized_limits = aggregate_run_limits(
                haystack.len(),
                materialized.build_report(),
                &RunLimits::default(),
            )
            .unwrap_or_else(|error| panic!("materialized limits {pattern:?}: {}", error.message));
            let visitor_limits = complete_spans_run_limits_with_policy(
                haystack.len(),
                &visitor,
                &RunLimits::default(),
            )
            .unwrap_or_else(|error| panic!("visitor limits {pattern:?}: {}", error.message));
            assert_eq!(visitor_limits, materialized_limits);

            let expected = materialized
                .spans(haystack, materialized_limits)
                .unwrap_or_else(|error| panic!("materialized execute {pattern:?}: {error}"));
            let expected_bounds = expected.iter().collect::<Vec<_>>();
            let mut actual_bounds = Vec::new();
            let visited = visitor
                .visit_spans(haystack, visitor_limits, |matched| {
                    actual_bounds.push(matched);
                })
                .unwrap_or_else(|error| panic!("visitor execute {pattern:?}: {error}"));
            assert_eq!(actual_bounds, expected_bounds, "pattern={pattern:?}");
            assert_eq!(visited.len(), expected.len(), "pattern={pattern:?}");
            assert_eq!(
                visited.span_sum(),
                usize::try_from(rebar_sum_match_bounds(&expected).unwrap()).unwrap(),
                "pattern={pattern:?}",
            );
            assert!(rebar_streamed_single_span_accounting_closes(
                &visitor,
                haystack.len(),
                &visitor_limits,
                &visited,
            ));

            let lifecycle = current_fre_rebar_aggregate_operation_lifecycle(
                "count-spans",
                &[pattern.to_string()],
                unicode,
                case_insensitive,
                haystack.len(),
            )
            .unwrap_or_else(|error| panic!("lifecycle {pattern:?}: {error}"));
            assert_eq!(lifecycle.plan(), "aggregate-continuation-program");
            let expected_sum = u64::try_from(visited.span_sum()).unwrap();
            assert_eq!(lifecycle.execute(haystack).unwrap(), expected_sum);
            assert_eq!(lifecycle.execute(haystack).unwrap(), expected_sum);
        }
    }

    #[test]
    fn formal_single_count_spans_resource_refusal_precedes_callbacks() {
        std::thread::Builder::new()
            .name("formal-single-count-spans-resource".to_string())
            .stack_size(32 * 1024 * 1024)
            .spawn(formal_single_count_spans_resource_refusal_precedes_callbacks_inner)
            .expect("spawn forced-continuation span resource test")
            .join()
            .expect("forced-continuation span resource thread");
    }

    fn formal_single_count_spans_resource_refusal_precedes_callbacks_inner() {
        let haystack = b"aaaaa";
        let regex = current_fre_rebar_complete_spans_builder("a+", false, false)
            .build_span_visitor()
            .expect("forced continuation visitor");
        let limits =
            complete_spans_run_limits_with_policy(haystack.len(), &regex, &RunLimits::default())
                .expect("exact visitor limits");
        let mut refused = limits;
        refused.continuation.max_match_events = 0;
        refused.continuation.max_output_matches = 0;
        let mut callbacks = 0_usize;
        assert!(
            regex
                .visit_spans(haystack, refused, |_| callbacks += 1)
                .is_err()
        );
        assert_eq!(callbacks, 0);

        let mut replayed = Vec::new();
        let visited = regex
            .visit_spans(haystack, limits, |matched| replayed.push(matched))
            .expect("visitor remains reusable after refusal");
        assert_eq!(
            replayed
                .iter()
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>(),
            [(0, haystack.len())],
        );
        assert_eq!(visited.len(), 1);
        assert_eq!(visited.span_sum(), haystack.len());
    }

    #[test]
    fn portable_complete_spans_streams_bounds_and_reuses_the_prepared_session() {
        let haystack = b"aba\xFFa";
        let regex = current_fre_rebar_complete_spans_regex("a*", false, true)
            .expect("portable complete-spans matcher");
        assert!(
            regex
                .plan()
                .starts_with(CURRENT_FRE_REBAR_COMPLETE_SPANS_PLAN_PREFIX)
        );
        let runtime = regex.runtime_implementation_id();
        let mut session = regex
            .session(haystack.len())
            .expect("retained complete-spans session");
        assert_eq!(session.runtime_implementation_id(), runtime);
        session
            .validate_haystack(haystack)
            .expect("fixed input validation");

        // Rust byte iteration selects `a`, empty, `a`, empty, `a`, empty.
        // Both endpoints of every complete match are read; empty matches add
        // zero while still exercising byte-wise progress.
        assert_eq!(session.execute_prevalidated(haystack).unwrap(), 3);
        assert_eq!(session.execute_prevalidated(haystack).unwrap(), 3);
        assert!(session.execute(b"x").is_err());
    }

    #[test]
    fn portable_complete_spans_routes_exact_literals_through_fresh_and_retained_visitors() {
        let cases: &[(&str, &[u8])] = &[
            ("", b"ab\xFF"),
            ("a", b"baaa\xFF"),
            ("aa", b"aaaaa"),
            ("aba", b"abababa"),
            (r"\xFF", b"a\xFF\xFFb"),
            ("needle", b"no match"),
        ];
        for &(pattern, haystack) in cases {
            let oracle = regex::bytes::RegexBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            let expected = oracle
                .find_iter(haystack)
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>();
            let expected_sum = expected.iter().try_fold(0_u64, |sum, &(start, end)| {
                sum.checked_add(u64::try_from(end - start).ok()?)
            });
            let expected_sum = expected_sum.expect("oracle span sum");

            // Exercise the public fresh facade directly, including invalid
            // bytes, empty progression, overlap, and no-match behavior.
            let portable = fre::PortableBuilder::new(pattern)
                .unicode(false)
                .build()
                .unwrap();
            assert_eq!(portable.build_report().plan, fre::PlanKind::ExactLiteral);
            assert_eq!(
                portable.span_visit_runtime_implementation_id(),
                Some(fre::LITERAL_SPAN_VISIT_OPERATION_ID)
            );
            let mut fresh = Vec::new();
            let result = portable
                .try_visit_spans(
                    haystack,
                    fre::PortableSpanVisitLimits::unlimited(),
                    |matched| fresh.push((matched.start(), matched.end())),
                )
                .unwrap()
                .expect("exact literal has a direct visitor");
            assert_eq!(fresh, expected, "fresh pattern={pattern:?}");
            assert_eq!(result.matches, expected.len());
            assert_eq!(result.span_sum, expected_sum);
            assert!(matches!(
                result.accounting,
                fre::PortableSpanVisitAccounting::ExactLiteral(_)
            ));

            // The retained facade must replay the same result repeatedly.
            let mut retained = portable
                .search_session(fre::SearchSessionLimits::unlimited())
                .unwrap();
            for pass in 0..2 {
                let mut spans = Vec::new();
                let result = retained
                    .try_visit_spans(
                        haystack,
                        fre::PortableSpanVisitLimits::unlimited(),
                        |matched| spans.push((matched.start(), matched.end())),
                    )
                    .unwrap()
                    .expect("retained exact literal has a direct visitor");
                assert_eq!(spans, expected, "retained pass={pass} pattern={pattern:?}");
                assert_eq!(result.matches, expected.len());
                assert_eq!(result.span_sum, expected_sum);
            }

            // At the formal Rebar boundary, zero ordinary search work proves
            // that first and steady execution use the direct visitor.
            let regex = current_fre_rebar_complete_spans_regex(pattern, false, false)
                .expect("Rebar exact-literal matcher");
            assert_eq!(
                regex.plan(),
                format!(
                    "{CURRENT_FRE_REBAR_COMPLETE_SPANS_PORTABLE_VISIT_PLAN_PREFIX}-exact-literal-{}",
                    fre::LITERAL_SPAN_VISIT_OPERATION_ID
                )
            );
            let mut session = regex
                .session_with_limits(
                    haystack.len(),
                    &RunLimits {
                        fre_search_work: 0,
                        ..RunLimits::default()
                    },
                )
                .unwrap();
            assert_eq!(
                session.execute_prevalidated(haystack).unwrap(),
                expected_sum
            );
            assert_eq!(
                session.execute_prevalidated(haystack).unwrap(),
                expected_sum
            );
        }

        // A supported direct refusal is pre-callback and terminal. The same
        // retained facade session remains reusable after that refusal.
        let portable = fre::PortableBuilder::new("aa")
            .unicode(false)
            .build()
            .unwrap();
        let mut retained = portable
            .search_session(fre::SearchSessionLimits::unlimited())
            .unwrap();
        let mut callbacks = 0usize;
        let mut refused_limits = fre::PortableSpanVisitLimits::unlimited();
        refused_limits.exact_literal.max_match_events = 1;
        let error = retained
            .try_visit_spans(b"aaaaa", refused_limits, |_| callbacks += 1)
            .unwrap_err();
        assert_eq!(callbacks, 0);
        assert!(matches!(
            error,
            fre::PortableSpanVisitError::ExactLiteral(
                fre::LiteralSpanVisitError::MatchEventLimit {
                    needed: 2,
                    limit: 1
                }
            )
        ));
        let mut replayed = Vec::new();
        retained
            .try_visit_spans(
                b"aaaaa",
                fre::PortableSpanVisitLimits::unlimited(),
                |matched| replayed.push((matched.start(), matched.end())),
            )
            .unwrap()
            .unwrap();
        assert_eq!(replayed, [(0, 2), (2, 4)]);

        let regex = current_fre_rebar_complete_spans_regex("aa", false, false).unwrap();
        let mut refused = regex
            .session_with_limits(
                5,
                &RunLimits {
                    fre_aggregate_operation_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        let error = refused.execute_prevalidated(b"aaaaa").unwrap_err();
        assert!(error.0.contains("direct traversal failed"));
        assert!(!error.0.contains("iteration failed"));
    }

    #[test]
    fn portable_complete_spans_selects_only_nontrivial_two_byte_anchored_fixed_predicates() {
        let pattern = "the";
        let haystack = b"THEtheThE\xFFthee";
        let oracle = regex::bytes::RegexBuilder::new(pattern)
            .unicode(false)
            .case_insensitive(true)
            .build()
            .unwrap();
        let expected = oracle
            .find_iter(haystack)
            .map(|matched| (matched.start(), matched.end()))
            .collect::<Vec<_>>();
        let expected_sum = expected
            .iter()
            .map(|&(start, end)| u64::try_from(end - start).unwrap())
            .sum::<u64>();

        let portable = fre::PortableBuilder::new(pattern)
            .unicode(false)
            .case_insensitive(true)
            .build()
            .unwrap();
        assert_eq!(
            portable.build_report().plan,
            fre::PlanKind::FixedPredicateWord64
        );
        assert_eq!(portable.span_visit_runtime_implementation_id(), None);
        let identity = portable
            .fixed_predicate_span_visit_operation_identity()
            .expect("fixed-predicate visitor identity");
        assert_eq!(identity.width, 3);
        assert_eq!(identity.reducer, FixedPredicateWord64Reducer::TwoByteAnchor);
        assert_eq!(
            identity.operation_id,
            FIXED_PREDICATE_WORD64_SPAN_VISIT_OPERATION_ID
        );
        let mut retained = portable
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let mut actual = Vec::new();
        let result = retained
            .try_visit_fixed_predicate_spans(
                haystack,
                FixedPredicateWord64ReduceLimits::unlimited(),
                |matched| actual.push((matched.start(), matched.end())),
            )
            .unwrap()
            .expect("fixed predicate has a direct visitor");
        assert_eq!(actual, expected);
        assert_eq!(result.matches, expected.len());
        assert_eq!(result.span_sum, expected_sum);

        let regex = current_fre_rebar_complete_spans_regex(pattern, false, true).unwrap();
        assert_eq!(
            regex.plan(),
            format!(
                "{CURRENT_FRE_REBAR_COMPLETE_SPANS_PORTABLE_VISIT_PLAN_PREFIX}-fixed-predicate-word64-{FIXED_PREDICATE_WORD64_SPAN_VISIT_OPERATION_ID}"
            )
        );
        let mut session = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_search_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        assert_eq!(
            session.execute_prevalidated(haystack).unwrap(),
            expected_sum
        );
        assert_eq!(
            session.execute_prevalidated(haystack).unwrap(),
            expected_sum
        );

        let mut refused_limits = FixedPredicateWord64ReduceLimits::unlimited();
        refused_limits.max_match_events = expected.len() - 1;
        let mut callbacks = 0_usize;
        assert!(matches!(
            retained.try_visit_fixed_predicate_spans(haystack, refused_limits, |_| callbacks += 1),
            Err(FixedPredicateWord64ReduceError::MatchEventsLimit { .. })
        ));
        assert_eq!(callbacks, 0);

        let width_two = current_fre_rebar_complete_spans_regex(".y", false, false).unwrap();
        assert!(
            width_two
                .plan()
                .starts_with("rebar-complete-spans-portable-find-v2-fixed-predicate-word64-")
        );
        let broad_width_five =
            current_fre_rebar_complete_spans_regex("[a-z][a-z][a-z][a-z][a-z]", false, false)
                .unwrap();
        assert!(
            broad_width_five
                .plan()
                .starts_with("rebar-complete-spans-portable-find-v2-fixed-predicate-word64-")
        );

        let ordinary = portable
            .find_iter(haystack, fre::PortableFindIterLimits::unlimited())
            .unwrap()
            .map(|matched| matched.unwrap())
            .map(|matched| (matched.start(), matched.end()))
            .collect::<Vec<_>>();
        assert_eq!(ordinary, expected);
    }

    #[test]
    fn portable_complete_spans_routes_literal_class_runs_through_the_direct_visitor() {
        let haystack = b"ab cd!ab   cd";
        let regex = current_fre_rebar_complete_spans_regex(r"ab[ ]+cd", false, false)
            .expect("portable direct complete-spans matcher");
        assert_eq!(
            regex.plan(),
            format!(
                "{CURRENT_FRE_REBAR_COMPLETE_SPANS_PORTABLE_VISIT_PLAN_PREFIX}-literal-class-run-literal-{LITERAL_CLASS_RUN_LITERAL_SPAN_VISIT_OPERATION_ID}"
            )
        );
        assert_eq!(
            regex.runtime_implementation_id(),
            LITERAL_CLASS_RUN_LITERAL_SPAN_VISIT_OPERATION_ID
        );

        // A zero search-work allowance makes the repeated-find fallback
        // unusable while leaving the direct operation's independent budget.
        let mut session = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_search_work: 0,
                    ..RunLimits::default()
                },
            )
            .expect("portable direct complete-spans session");
        assert_eq!(session.execute(haystack).unwrap(), 12);
        assert_eq!(session.execute(haystack).unwrap(), 12);

        // A supported visitor refusal is terminal; only `Ok(None)` may use
        // the repeated-find fallback.
        let mut refused = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_aggregate_operation_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        let error = refused.execute(haystack).unwrap_err();
        assert!(error.0.contains("direct traversal failed"));
        assert!(!error.0.contains("callback before refusal"));
        assert!(!error.0.contains("iteration failed"));
    }

