    #[test]
    fn complete_spans_routes_guarded_word_sets_through_endpoint_visitors() {
        let pattern = r"(?:\b(as)\b)|(?:\b(break)\b)|(?:\b(const)\b)|(?:\b(Self)\b)";
        let haystack = b"as break \xCE\xB2as as\xCE\xB2 const Self _as as\xFFbreak";
        for unicode in [false, true] {
            let oracle = regex::bytes::RegexBuilder::new(pattern)
                .unicode(unicode)
                .build()
                .unwrap();
            let expected = oracle
                .find_iter(haystack)
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>();
            let expected_sum = expected
                .iter()
                .map(|&(start, end)| u64::try_from(end - start).unwrap())
                .sum::<u64>();

            let materializer = current_fre_rebar_aggregate_builder(pattern, unicode, false)
                .build_spans()
                .unwrap();
            assert!(!matches!(
                materializer.build_report().plan,
                AggregatePlanKind::GuardedAsciiWordDictionary
                    | AggregatePlanKind::GuardedUnicodeWordLiteralSet
            ));

            let regex = current_fre_rebar_complete_spans_regex(pattern, unicode, false).unwrap();
            let (plan_prefix, runtime_id, plan_kind) = if unicode {
                (
                    CURRENT_FRE_REBAR_COMPLETE_SPANS_GUARDED_UNICODE_WORD_PLAN,
                    fre::guarded_unicode_word::SPAN_VISIT_OPERATION_ID,
                    AggregatePlanKind::GuardedUnicodeWordLiteralSet,
                )
            } else {
                (
                    CURRENT_FRE_REBAR_COMPLETE_SPANS_GUARDED_ASCII_WORD_PLAN,
                    guarded_ascii_word::SPAN_VISIT_OPERATION_ID,
                    AggregatePlanKind::GuardedAsciiWordDictionary,
                )
            };
            assert_eq!(regex.plan(), format!("{plan_prefix}-{runtime_id}"));
            assert_eq!(regex.runtime_implementation_id(), runtime_id);
            let CurrentFreCompleteSpansRegexInner::Aggregate(aggregate) = &regex.inner else {
                panic!("guarded word visitor retained the portable fallback");
            };
            assert_eq!(aggregate.build_report().plan, plan_kind);

            let mut session = regex.session(haystack.len()).unwrap();
            let direct_limits = session.aggregate_limits.unwrap();
            let mut visited = Vec::new();
            let visit = aggregate
                .visit_spans(haystack, direct_limits, |matched| {
                    visited.push((matched.start(), matched.end()));
                })
                .unwrap();
            assert_eq!(visited, expected, "unicode={unicode}");
            assert_eq!(visit.span_sum(), usize::try_from(expected_sum).unwrap());
            assert_eq!(
                session.execute_prevalidated(haystack).unwrap(),
                expected_sum
            );
            assert_eq!(
                session.execute_prevalidated(haystack).unwrap(),
                expected_sum
            );

            let mut direct_refusal_limits = direct_limits;
            direct_refusal_limits.finite_literal.max_span_sum = 0;
            let mut callbacks = 0;
            aggregate
                .visit_spans(haystack, direct_refusal_limits, |_| callbacks += 1)
                .unwrap_err();
            assert_eq!(callbacks, 0);
        }

        for near_miss in [
            r"(?:\b(as))|(?:\b(break))",
            r"(?i:(?:\b(as)\b)|(?:\b(break)\b))",
        ] {
            let regex = current_fre_rebar_complete_spans_regex(near_miss, false, false).unwrap();
            assert_ne!(
                regex.runtime_implementation_id(),
                guarded_ascii_word::SPAN_VISIT_OPERATION_ID
            );
        }
    }

    #[test]
    fn complete_spans_routes_fixed_absolute_end_patterns_through_the_span_visitor() {
        let pattern = r"[ -~]*ABCDEFGHIJKLMNOPQRSTUVWXYZ$";
        let mut haystack = vec![0_u8];
        haystack.extend(std::iter::repeat_n(b'x', 1_024));
        haystack.extend_from_slice(b"ABCDEFGHIJKLMNOPQRSTUVWXYZ");

        let regex = current_fre_rebar_complete_spans_regex(pattern, false, false)
            .expect("fixed absolute complete-spans matcher");
        assert_eq!(
            regex.plan(),
            format!(
                "{CURRENT_FRE_REBAR_COMPLETE_SPANS_FIXED_ABSOLUTE_PLAN}-{}",
                fre::FIXED_ABSOLUTE_DOMAIN_SPANS_OPERATION_ID
            )
        );
        assert_eq!(
            regex.runtime_implementation_id(),
            fre::FIXED_ABSOLUTE_DOMAIN_SPANS_OPERATION_ID
        );

        let mut session = regex.session(haystack.len()).unwrap();
        session.validate_haystack(&haystack).unwrap();
        let expected = u64::try_from(haystack.len() - 1).unwrap();
        assert_eq!(session.execute_prevalidated(&haystack).unwrap(), expected);
        assert_eq!(session.execute_prevalidated(&haystack).unwrap(), expected);

        let mut no_match = haystack.clone();
        *no_match.last_mut().unwrap() = b'x';
        assert_eq!(session.execute_prevalidated(&no_match).unwrap(), 0);

        let start_haystack = b"zbcd-tail";
        let start = current_fre_rebar_complete_spans_regex(r"^zbc(d|e)", false, false)
            .expect("start fixed absolute complete-spans matcher");
        let mut start_session = start.session(start_haystack.len()).unwrap();
        assert!(start_session.fixed_absolute_value_success);
        assert_eq!(
            start_session.execute_prevalidated(start_haystack).unwrap(),
            4
        );
        assert_eq!(start_session.execute_prevalidated(b"zbca-tail").unwrap(), 0);

        // The fixed kernel accounts one reducer step even on a no-match. A
        // zero-step policy therefore refuses both sources and is replayed
        // through the receipt-bearing path rather than silently succeeding.
        let mut zero_reducer = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    reducer_steps: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        assert!(zero_reducer.execute_prevalidated(&haystack).is_err());
        assert!(zero_reducer.execute_prevalidated(&no_match).is_err());

        // A non-reducer fixed resource refusal is likewise replayed through
        // the ordinary operation so its exact lifecycle error remains
        // observable and no portable fallback can run.
        let mut refused = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_aggregate_operation_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        let error = refused.execute_prevalidated(&haystack).unwrap_err();
        assert!(error.0.contains("complete-spans lifecycle"));
        assert!(refused.search.is_none());
    }

    #[test]
    fn complete_spans_routes_literal_assertions_through_the_span_visitor() {
        let pattern = r"(?m)^Sherlock Holmes|Sherlock Holmes$";
        let haystack = b"Sherlock Holmes begins\ninside Sherlock Holmes\nSherlock Holmes\nno match\nends Sherlock Holmes";
        let oracle = regex::bytes::RegexBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        let expected = oracle
            .find_iter(haystack)
            .map(|matched| (matched.start(), matched.end()))
            .collect::<Vec<_>>();
        let expected_sum = expected
            .iter()
            .map(|&(start, end)| u64::try_from(end - start).unwrap())
            .sum::<u64>();

        // Materializing complete spans deliberately retain the continuation
        // path; only the allocation-free visitor may select this reducer.
        let materializer = current_fre_rebar_aggregate_builder(pattern, false, false)
            .build_spans()
            .unwrap();
        assert_eq!(
            materializer.build_report().plan,
            AggregatePlanKind::ContinuationProgram
        );
        let materializer_limits = aggregate_run_limits(
            haystack.len(),
            materializer.build_report(),
            &RunLimits::default(),
        )
        .unwrap();
        assert_eq!(
            materializer
                .spans(haystack, materializer_limits)
                .unwrap()
                .iter()
                .map(|matched| (matched.start(), matched.end()))
                .collect::<Vec<_>>(),
            expected
        );

        let regex = current_fre_rebar_complete_spans_regex(pattern, false, false).unwrap();
        assert_eq!(
            regex.plan(),
            format!(
                "{CURRENT_FRE_REBAR_COMPLETE_SPANS_LITERAL_ASSERTIONS_PLAN}-{LITERAL_ASSERTIONS_SPAN_VISIT_OPERATION_ID}"
            )
        );
        assert_eq!(
            regex.runtime_implementation_id(),
            LITERAL_ASSERTIONS_SPAN_VISIT_OPERATION_ID
        );
        let CurrentFreCompleteSpansRegexInner::Aggregate(aggregate) = &regex.inner else {
            panic!("literal-assertions visitor retained the portable fallback");
        };
        assert_eq!(
            aggregate.build_report().plan,
            AggregatePlanKind::LiteralAssertions
        );

        let mut session = regex.session(haystack.len()).unwrap();
        let direct_limits = session.aggregate_limits.unwrap();
        let mut visited = Vec::new();
        let result = aggregate
            .visit_spans(haystack, direct_limits, |matched| {
                visited.push((matched.start(), matched.end()));
            })
            .unwrap();
        assert_eq!(visited, expected);
        assert_eq!(result.span_sum(), usize::try_from(expected_sum).unwrap());
        assert_eq!(
            session.execute_prevalidated(haystack).unwrap(),
            expected_sum
        );
        assert_eq!(
            session.execute_prevalidated(haystack).unwrap(),
            expected_sum
        );

        // Every limit is admitted before the first callback. The immutable
        // visitor remains reusable after a typed direct refusal.
        let mut direct_refusal_limits = direct_limits;
        direct_refusal_limits.literal_assertions.max_work = 0;
        let mut callbacks = 0_usize;
        aggregate
            .visit_spans(haystack, direct_refusal_limits, |_| callbacks += 1)
            .unwrap_err();
        assert_eq!(callbacks, 0);
        let replay = aggregate
            .visit_spans(haystack, direct_limits, |_| {})
            .unwrap();
        assert_eq!(replay.span_sum(), usize::try_from(expected_sum).unwrap());

        let mut refused = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_aggregate_operation_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        let error = refused.execute_prevalidated(haystack).unwrap_err();
        assert!(error.0.contains("complete-spans lifecycle"));
        assert!(refused.search.is_none());
    }

    fn assert_sparse_public_dictionary_complete_spans_route() {
        const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        let mut pattern = String::from("(?:");
        for index in 0..8_192 {
            if index != 0 {
                pattern.push('|');
            }
            let prefix = char::from(ALPHABET[index % ALPHABET.len()]);
            write!(&mut pattern, "{prefix}term{index:05}").unwrap();
        }
        pattern.push(')');
        let haystack = b"xxAterm00000--Bterm00001--Aterm00062!";

        let regex = current_fre_rebar_complete_spans_regex(&pattern, true, false)
            .expect("sparse dictionary complete-spans matcher");
        assert_eq!(
            regex.plan(),
            format!(
                "{CURRENT_FRE_REBAR_COMPLETE_SPANS_SPARSE_FINITE_PLAN}-{}",
                fre::SPARSE_ORDERED_LITERAL_TRACE_ALGORITHM_ID
            )
        );
        assert_eq!(
            regex.runtime_implementation_id(),
            fre::SPARSE_ORDERED_LITERAL_TRACE_ALGORITHM_ID
        );
        let CurrentFreCompleteSpansRegexInner::Aggregate(aggregate) = &regex.inner else {
            panic!("sparse dictionary retained the portable fallback");
        };
        assert!(matches!(
            aggregate.build_report().build,
            AggregateBuildAccounting::SparseFiniteLiteral(_)
        ));

        let mut session = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_search_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap();
        assert_eq!(
            session.runtime_implementation_id(),
            regex.runtime_implementation_id()
        );
        assert!(session.aggregate_span_visit_workspace.is_some());
        session.validate_haystack(haystack).unwrap();
        assert_eq!(session.execute_prevalidated(haystack).unwrap(), 30);
        assert_eq!(session.execute_prevalidated(haystack).unwrap(), 30);

        let refused = regex
            .session_with_limits(
                haystack.len(),
                &RunLimits {
                    fre_aggregate_operation_work: 0,
                    ..RunLimits::default()
                },
            )
            .unwrap_err();
        assert!(refused.0.contains("trace workspace preparation refused"));
    }

