    #[test]
    fn unicode_scalar_run_limits_project_the_retained_owner_envelope() {
        let upper = fre::UnicodeScalarAggregateUpperBounds {
            input_bytes: 10,
            ascii_block_classifications: 0,
            ascii_block_classification_bytes: 0,
            ascii_block_lookahead_bytes: 0,
            decode_byte_checks: 40,
            membership_tests: 10,
            range_comparisons: 30,
            binary_search_comparisons_per_scalar: 3,
            reducer_steps: 0,
            match_events: 10,
            count: 10,
            span_sum: 10,
            work: 80,
            scratch_bytes: 0,
            persistent_bytes: 123,
            peak_bytes: 123,
        };
        let derived = unicode_scalar_operation_limits(upper, &RunLimits::default()).unwrap();
        assert_eq!(derived.max_input_bytes, 10);
        assert_eq!(derived.max_decode_byte_checks, 40);
        assert_eq!(derived.max_membership_tests, 10);
        // Five retained ranges need at most three binary-search comparisons
        // per decoded scalar. The byte length is a safe upper bound on the
        // number of decoded scalars, including invalid one-byte advances.
        assert_eq!(derived.max_range_comparisons, 30);
        assert_eq!(derived.max_reducer_steps, 0);
        assert_eq!(derived.max_match_events, 10);
        assert_eq!(derived.max_count, 10);
        assert_eq!(derived.max_span_sum, 10);
        assert_eq!(derived.max_work, 80);
        assert_eq!(derived.max_scratch_bytes, 0);
        assert_eq!(derived.max_peak_bytes, 123);

        let run_upper = fre::UnicodeScalarAggregateUpperBounds {
            range_comparisons: 50,
            binary_search_comparisons_per_scalar: 5,
            reducer_steps: 11,
            work: 111,
            ..upper
        };
        let run = unicode_scalar_operation_limits(run_upper, &RunLimits::default()).unwrap();
        // Run plans may probe the cached non-ASCII range and its monotone
        // successor before falling back to the bounded binary search.
        assert_eq!(run.max_range_comparisons, 50);
        assert_eq!(run.max_reducer_steps, 11);
        assert_eq!(run.max_work, 111);

        let capped = unicode_scalar_operation_limits(
            run_upper,
            &RunLimits {
                reducer_steps: 4,
                ..RunLimits::default()
            },
        )
        .unwrap();
        assert_eq!(capped.max_match_events, 4);
        assert_eq!(capped.max_count, 4);
        assert_eq!(capped.max_reducer_steps, 4);
        assert_eq!(capped.max_range_comparisons, 50);
        assert_eq!(capped.max_work, 111);
    }

    #[test]
    fn bounded_context_run_limits_bind_the_retained_owner_operation() {
        let count = fre::BoundedContextUpperBounds {
            input_bytes: 10,
            literal_bytes: 2,
            interval_records: 3,
            interval_bytes: 24,
            inspections: 20,
            branches: 30,
            comparisons: 40,
            state_writes: 50,
            work: 140,
            match_events: 4,
            count: 4,
            scratch_bytes: 24,
            persistent_bytes: 16,
            peak_bytes: 40,
        };
        let span_sum = fre::BoundedContextSpanSumUpperBounds {
            input_bytes: 10,
            literal_bytes: 2,
            interval_records: 3,
            interval_bytes: 24,
            inspections: 20,
            branches: 30,
            comparisons: 40,
            state_writes: 50,
            work: 140,
            match_events: 4,
            span_sum: 20,
            scratch_bytes: 24,
            persistent_bytes: 16,
            peak_bytes: 40,
        };
        let defaults = RunLimits::default();

        for operation in [AggregateOperation::Compile, AggregateOperation::Count] {
            let derived = bounded_context_operation_limits(
                operation,
                fre::AggregateRetainedFullWindowUpperBounds::BoundedContextCount(count),
                &defaults,
            )
            .expect("compile/count retain the count envelope");
            assert_eq!(derived.max_count, count.count);
        }
        let derived = bounded_context_operation_limits(
            AggregateOperation::SpanSum,
            fre::AggregateRetainedFullWindowUpperBounds::BoundedContextSpanSum(span_sum),
            &defaults,
        )
        .expect("span-sum retains the span-sum envelope");
        assert_eq!(derived.max_count, span_sum.span_sum);

        assert!(
            bounded_context_operation_limits(
                AggregateOperation::SpanSum,
                fre::AggregateRetainedFullWindowUpperBounds::BoundedContextCount(count),
                &defaults,
            )
            .is_err()
        );
        assert!(
            bounded_context_operation_limits(
                AggregateOperation::Count,
                fre::AggregateRetainedFullWindowUpperBounds::BoundedContextSpanSum(span_sum),
                &defaults,
            )
            .is_err()
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one retained-artifact matrix binds every repaired direct family to its executable limits"
    )]
    fn retained_direct_owner_limits_project_actual_selected_artifacts() {
        let defaults = RunLimits::default();

        let prefix_haystack = b"abcz--xy7";
        let prefix = current_fre_rebar_aggregate_builder(r"ab[a-z]+|xy[0-9]+", false, false)
            .build_count()
            .expect("prefix/class count artifact");
        assert_eq!(
            prefix.build_report().plan,
            AggregatePlanKind::PrefixClassAlternation
        );
        let Some(fre::AggregateRetainedFullWindowUpperBounds::PrefixClassAlternation(prefix_upper)) =
            prefix
                .retained_full_window_upper_bounds(prefix_haystack.len())
                .expect("prefix/class retained envelope")
        else {
            panic!("prefix/class artifact lost its retained envelope");
        };
        let prefix_limits =
            current_fre_rebar_count_run_limits(prefix_haystack.len(), &prefix).unwrap();
        assert_eq!(
            prefix_limits.prefix_class_alternation.max_work,
            prefix_upper.work
        );
        assert_eq!(
            prefix.count_value(prefix_haystack, prefix_limits).unwrap(),
            2
        );
        assert!(
            current_fre_rebar_aggregate_run_limits(prefix_haystack.len(), prefix.build_report())
                .is_err()
        );
        let prefix_one_below = count_run_limits_with_policy(
            prefix_haystack.len(),
            &prefix,
            &RunLimits {
                fre_aggregate_operation_work: prefix_upper.work - 1,
                ..defaults.clone()
            },
        )
        .unwrap();
        assert!(
            prefix
                .count_value(prefix_haystack, prefix_one_below)
                .is_err()
        );

        let literal_haystack = b"Sherlock Holmes--Sherlock\tHolmes";
        let literal = current_fre_rebar_aggregate_builder(r"Sherlock\s+Holmes", false, false)
            .build_count()
            .expect("literal/class-run/literal count artifact");
        assert_eq!(
            literal.build_report().plan,
            AggregatePlanKind::LiteralClassRunLiteral
        );
        let Some(fre::AggregateRetainedFullWindowUpperBounds::LiteralClassRunLiteral(
            literal_upper,
        )) = literal
            .retained_full_window_upper_bounds(literal_haystack.len())
            .expect("literal/class-run/literal retained envelope")
        else {
            panic!("literal/class-run/literal artifact lost its retained envelope");
        };
        let literal_limits =
            current_fre_rebar_count_run_limits(literal_haystack.len(), &literal).unwrap();
        assert_eq!(
            literal_limits.literal_class_run_literal.max_source_reads,
            literal_upper.source_reads
        );
        assert_eq!(
            literal
                .count_value(literal_haystack, literal_limits)
                .unwrap(),
            2
        );
        let literal_one_below = count_run_limits_with_policy(
            literal_haystack.len(),
            &literal,
            &RunLimits {
                fre_aggregate_operation_work: literal_upper.work - 1,
                ..defaults.clone()
            },
        )
        .unwrap();
        assert!(
            literal
                .count_value(literal_haystack, literal_one_below)
                .is_err()
        );

        let literal_span = current_fre_rebar_aggregate_builder(r"Sherlock\s+Holmes", false, false)
            .build_span_sum()
            .expect("literal/class-run/literal span-sum artifact");
        let Some(fre::AggregateRetainedFullWindowUpperBounds::LiteralClassRunLiteral(
            literal_span_upper,
        )) = literal_span
            .retained_full_window_upper_bounds(literal_haystack.len())
            .expect("literal/class-run/literal span-sum retained envelope")
        else {
            panic!("literal/class-run/literal span-sum artifact lost its retained envelope");
        };
        let literal_span_limits =
            current_fre_generic_span_sum_run_limits(literal_haystack.len(), &literal_span).unwrap();
        assert_eq!(
            literal_span_limits.literal_class_run_literal.max_span_sum,
            literal_span_upper.span_sum
        );
        assert_eq!(
            literal_span
                .span_sum_value(literal_haystack, literal_span_limits)
                .unwrap(),
            30
        );

        let bounded_haystack = b" ing  walking\t thing\n";
        let bounded = current_fre_rebar_aggregate_builder(r"\s[A-Za-z]{0,12}ing\s", false, false)
            .build_count()
            .expect("bounded-context count artifact");
        assert_eq!(
            bounded.build_report().plan,
            AggregatePlanKind::BoundedContext
        );
        let Some(fre::AggregateRetainedFullWindowUpperBounds::BoundedContextCount(bounded_upper)) =
            bounded
                .retained_full_window_upper_bounds(bounded_haystack.len())
                .expect("bounded-context retained envelope")
        else {
            panic!("bounded-context artifact lost its retained envelope");
        };
        let bounded_limits =
            current_fre_rebar_count_run_limits(bounded_haystack.len(), &bounded).unwrap();
        assert_eq!(bounded_limits.bounded_context.max_work, bounded_upper.work);
        assert_eq!(
            bounded
                .count_value(bounded_haystack, bounded_limits)
                .unwrap(),
            3
        );
        let bounded_one_below = count_run_limits_with_policy(
            bounded_haystack.len(),
            &bounded,
            &RunLimits {
                fre_aggregate_operation_work: bounded_upper.work - 1,
                ..defaults.clone()
            },
        )
        .unwrap();
        assert!(
            bounded
                .count_value(bounded_haystack, bounded_one_below)
                .is_err()
        );

        let bounded_span =
            current_fre_rebar_aggregate_builder(r"\s[A-Za-z]{0,12}ing\s", false, false)
                .build_span_sum()
                .expect("bounded-context span-sum artifact");
        let Some(fre::AggregateRetainedFullWindowUpperBounds::BoundedContextSpanSum(
            bounded_span_upper,
        )) = bounded_span
            .retained_full_window_upper_bounds(bounded_haystack.len())
            .expect("bounded-context span-sum retained envelope")
        else {
            panic!("bounded-context span-sum artifact lost its retained envelope");
        };
        let bounded_span_limits =
            current_fre_generic_span_sum_run_limits(bounded_haystack.len(), &bounded_span).unwrap();
        assert_eq!(
            bounded_span_limits.bounded_context.max_count,
            bounded_span_upper.span_sum
        );
        assert_eq!(
            bounded_span
                .span_sum_value(bounded_haystack, bounded_span_limits)
                .unwrap(),
            21
        );
    }

    #[test]
    fn aggregate_operation_limits_are_fully_derived_and_quota_capped() {
        let mut run = RunLimits::default();
        let sweep = fre::continuation_sweep_upper_bounds(5).unwrap();
        let derived = continuation_operation_limits_with_sweep(
            10,
            conservative_continuation_shape(5).unwrap(),
            Some(sweep),
            AggregateOperation::SpanSum,
            &run,
        )
        .unwrap();
        let runtime = fre::continuation_sweep_run_upper_bounds(sweep, 10, 15).unwrap();
        let count_policy = RunLimits {
            fre_aggregate_sequential_bytes: runtime.count_sequential_bytes,
            fre_aggregate_operation_work: sweep.preparation_work
                + runtime.count_work
                + sweep.learning_work,
            ..RunLimits::default()
        };
        let count_specific = continuation_operation_limits_with_sweep(
            10,
            conservative_continuation_shape(5).unwrap(),
            Some(sweep),
            AggregateOperation::Count,
            &count_policy,
        )
        .unwrap();
        assert_eq!(count_specific.max_table_cells, sweep.table_cells);
        let span_under_count_policy = continuation_operation_limits_with_sweep(
            10,
            conservative_continuation_shape(5).unwrap(),
            Some(sweep),
            AggregateOperation::SpanSum,
            &count_policy,
        )
        .unwrap();
        assert_eq!(span_under_count_policy.max_table_cells, sweep.table_cells);
        let cached_frontier = cached_frontier_limits(5, 11, 1).unwrap();
        assert_eq!(cached_frontier.random, 2_162_704);
        assert_eq!(cached_frontier.scratch, 2_162_704);
        assert_eq!(cached_frontier.log, 22);
        assert_eq!(cached_frontier.sequential, 88);
        assert_eq!(cached_frontier.peak, 2_162_726);
        assert!(cached_frontier_initialization_work(5, 11).unwrap() > 429);
        assert_eq!(derived.max_boundaries, 11);
        assert_eq!(derived.max_table_cells, sweep.table_cells);
        assert_eq!(derived.max_random_access_bytes, sweep.workspace_bytes);
        assert_eq!(derived.max_scratch_bytes, sweep.workspace_bytes);
        assert_eq!(derived.max_log_bytes, 11);
        assert_eq!(
            derived.max_sequential_bytes,
            run.fre_aggregate_sequential_bytes
        );
        assert_eq!(derived.max_match_events, 22);
        assert_eq!(derived.max_output_matches, 11);
        assert_eq!(derived.max_output_bytes, 0);
        assert_eq!(derived.max_span_sum, 10);
        assert_eq!(derived.max_peak_bytes, sweep.workspace_bytes);
        assert_eq!(derived.max_work, run.fre_aggregate_operation_work);

        assert!(
            continuation_operation_limits_with_sweep(
                10,
                ContinuationProgramShape {
                    requires_utf8_validation: true,
                    ..conservative_continuation_shape(5).unwrap()
                },
                Some(sweep),
                AggregateOperation::SpanSum,
                &run,
            )
            .is_err()
        );

        for policy in [
            RunLimits {
                fre_aggregate_sequential_bytes: derived.max_sequential_bytes - 1,
                ..RunLimits::default()
            },
            RunLimits {
                fre_aggregate_operation_work: derived.max_work - 1,
                ..RunLimits::default()
            },
        ] {
            let observed = continuation_operation_limits_with_sweep(
                10,
                conservative_continuation_shape(5).unwrap(),
                Some(sweep),
                AggregateOperation::SpanSum,
                &policy,
            )
            .unwrap();
            assert_eq!(observed.max_table_cells, sweep.table_cells);
            assert_eq!(
                observed.max_sequential_bytes,
                policy.fre_aggregate_sequential_bytes
            );
            assert_eq!(observed.max_work, policy.fre_aggregate_operation_work);
        }

        let one_below_fixed_policies = [
            RunLimits {
                fre_aggregate_random_access_bytes: derived.max_random_access_bytes - 1,
                ..RunLimits::default()
            },
            RunLimits {
                fre_aggregate_scratch_bytes: derived.max_scratch_bytes - 1,
                ..RunLimits::default()
            },
            RunLimits {
                fre_aggregate_peak_bytes: derived.max_peak_bytes - 1,
                ..RunLimits::default()
            },
        ];
        for policy in one_below_fixed_policies {
            let one_below = continuation_operation_limits_with_sweep(
                10,
                conservative_continuation_shape(5).unwrap(),
                Some(sweep),
                AggregateOperation::SpanSum,
                &policy,
            )
            .unwrap();
            let incumbent_under_policy = continuation_operation_limits(
                10,
                conservative_continuation_shape(5).unwrap(),
                &policy,
            )
            .unwrap();
            assert_eq!(one_below.max_table_cells, 0);
            assert_eq!(one_below, incumbent_under_policy);
        }

        run.fre_aggregate_random_access_bytes = 7;
        run.fre_aggregate_scratch_bytes = 6;
        run.fre_aggregate_log_bytes = 5;
        run.fre_aggregate_sequential_bytes = 4;
        run.fre_aggregate_peak_bytes = 3;
        run.fre_aggregate_operation_work = 2;
        let capped = continuation_operation_limits_with_sweep(
            10,
            conservative_continuation_shape(5).unwrap(),
            Some(sweep),
            AggregateOperation::SpanSum,
            &run,
        )
        .unwrap();
        assert_eq!(capped.max_random_access_bytes, 7);
        assert_eq!(capped.max_scratch_bytes, 6);
        assert_eq!(capped.max_log_bytes, 5);
        assert_eq!(capped.max_sequential_bytes, 4);
        assert_eq!(capped.max_peak_bytes, 3);
        assert_eq!(capped.max_work, 2);
    }

    #[test]
    fn retained_value_artifact_authenticates_sweep_limits_without_widening_report_only_routes() {
        let policy = RunLimits::default();
        let eligible = AggregateBuilder::new(r"(?:abcdefghijklmnopq|qrstuvwxyzabcdefg)+z")
            .profile(rebar_profile())
            .unicode(false)
            .limits(aggregate_build_limits(&policy))
            .plan_selection(AggregatePlanSelection::ForceContinuation)
            .strategy(AggregateStrategy::ReverseSequentialRows)
            .build_count()
            .unwrap();
        let sweep = eligible
            .continuation_sweep_upper_bounds()
            .unwrap()
            .expect("large byte continuation must publish its sweep envelope");
        assert_eq!(sweep.minimum_match_bytes, Some(18));
        let retained = count_run_limits_with_policy(4_096, &eligible, &policy).unwrap();
        assert_eq!(retained.continuation.max_table_cells, sweep.table_cells);
        assert_eq!(
            retained.continuation.max_random_access_bytes,
            sweep.workspace_bytes
        );

        let report_only = aggregate_run_limits(4_096, eligible.build_report(), &policy).unwrap();
        assert_eq!(report_only.continuation.max_table_cells, 0);
        assert!(
            report_only.continuation.max_random_access_bytes
                < retained.continuation.max_random_access_bytes
        );
        let small = AggregateBuilder::new(r"a+")
            .profile(rebar_profile())
            .unicode(false)
            .limits(aggregate_build_limits(&policy))
            .plan_selection(AggregatePlanSelection::ForceContinuation)
            .strategy(AggregateStrategy::ReverseSequentialRows)
            .build_count()
            .unwrap();
        assert_eq!(small.continuation_sweep_upper_bounds().unwrap(), None);
        assert_eq!(
            count_run_limits_with_policy(4_096, &small, &policy)
                .unwrap()
                .continuation
                .max_table_cells,
            0
        );

        let shape = ContinuationProgramShape::from(match eligible.build_report().build {
            AggregateBuildAccounting::Continuation(compile) => compile,
            _ => panic!("forced continuation returned another plan"),
        });
        let transplanted = fre::continuation_sweep_upper_bounds(shape.states + 1).unwrap();
        assert!(
            continuation_operation_limits_with_sweep(
                4_096,
                shape,
                Some(transplanted),
                AggregateOperation::Count,
                &policy,
            )
            .is_err()
        );
        let equal_state_width_underbound = fre::ContinuationSweepUpperBounds {
            minimum_match_bytes: Some(usize::MAX),
            ..sweep
        };
        assert!(
            continuation_operation_limits_with_sweep(
                4_096,
                shape,
                Some(equal_state_width_underbound),
                AggregateOperation::Count,
                &policy,
            )
            .is_err()
        );
        let equal_state_underbound = fre::ContinuationSweepUpperBounds {
            max_nonaccepting_run: Some(0),
            ..sweep
        };
        assert_ne!(
            equal_state_underbound.max_nonaccepting_run,
            shape.continuation_max_nonaccepting_run
        );
        assert!(
            continuation_operation_limits_with_sweep(
                4_096,
                shape,
                Some(equal_state_underbound),
                AggregateOperation::Count,
                &policy,
            )
            .is_err()
        );
        for operation in [AggregateOperation::Compile, AggregateOperation::Spans] {
            assert!(
                continuation_operation_limits_with_sweep(
                    4_096,
                    shape,
                    Some(sweep),
                    operation,
                    &policy,
                )
                .is_err()
            );
        }
        assert!(
            continuation_operation_limits_with_sweep(
                4_096,
                ContinuationProgramShape {
                    required_internal_anchors: 1,
                    required_internal_anchor_bytes: 4,
                    required_internal_anchor_optional_stages: 1,
                    required_internal_anchor_persistent_bytes: 64,
                    ..shape
                },
                Some(sweep),
                AggregateOperation::Count,
                &policy,
            )
            .is_err()
        );
    }

    #[test]
    fn persistent_sweep_diagnostics_are_explicit_incumbent_projections() {
        let pattern = r"(?:abcdefghijklmnopq|qrstuvwxyzabcdefg)+z";
        let haystack = b"abcdefghijklmnopqqrstuvwxyzabcdefgz--qrstuvwxyzabcdefgz";
        let policy = RunLimits::default();

        let count_regex = AggregateBuilder::new(pattern)
            .profile(rebar_profile())
            .unicode(false)
            .limits(aggregate_build_limits(&policy))
            .plan_selection(AggregatePlanSelection::ForceContinuation)
            .strategy(AggregateStrategy::ReverseSequentialRows)
            .build_count()
            .unwrap();
        assert!(
            count_regex
                .continuation_sweep_upper_bounds()
                .unwrap()
                .is_some()
        );
        let count_limits =
            count_run_limits_with_policy(haystack.len(), &count_regex, &policy).unwrap();
        let count = CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::Count,
            plan: "test-persistent-continuation-sweep",
            haystack_len: haystack.len(),
            inner: CurrentFreAggregateOperationInner::CountSingleDense(
                count_regex,
                count_limits,
                RefCell::new(AggregateCountWorkspace::new()),
            ),
        };
        let CurrentFreAggregateOperationInner::CountSingleDense(_, _, count_workspace) =
            &count.inner
        else {
            unreachable!()
        };
        assert_eq!(count_workspace.borrow().retained_continuation_bytes(), None);
        assert_eq!(count.execute(haystack).unwrap(), 2);
        assert!(
            count_workspace
                .borrow()
                .retained_continuation_bytes()
                .is_some_and(|bytes| bytes > 0)
        );
        let count_projection = count.execute_with_counters(haystack).unwrap();
        assert_eq!(count_projection.value(), 2);
        assert!(matches!(
            count_projection.receipt_status(),
            CurrentFreAggregateCounterReceiptStatus::IncumbentProjectionForUnreceiptedSweep
        ));
        assert_eq!(count_projection.continuation_receipt(), None);

        let span_regex = AggregateBuilder::new(pattern)
            .profile(rebar_profile())
            .unicode(false)
            .limits(aggregate_build_limits(&policy))
            .plan_selection(AggregatePlanSelection::ForceContinuation)
            .strategy(AggregateStrategy::ReverseSequentialRows)
            .build_span_sum()
            .unwrap();
        assert!(
            span_regex
                .continuation_sweep_upper_bounds()
                .unwrap()
                .is_some()
        );
        let span_limits =
            span_sum_run_limits_with_policy(haystack.len(), &span_regex, &policy).unwrap();
        let span = CurrentFreAggregateOperationLifecycle {
            model: CurrentFreAggregateOperationModel::SpanSum,
            plan: "test-persistent-continuation-sweep",
            haystack_len: haystack.len(),
            inner: CurrentFreAggregateOperationInner::SpanSumSingleDense(
                span_regex,
                span_limits,
                RefCell::new(AggregateSpanSumWorkspace::new()),
            ),
        };
        let CurrentFreAggregateOperationInner::SpanSumSingleDense(_, _, span_workspace) =
            &span.inner
        else {
            unreachable!()
        };
        assert_eq!(span_workspace.borrow().retained_continuation_bytes(), None);
        assert_eq!(span.execute(haystack).unwrap(), 53);
        assert!(
            span_workspace
                .borrow()
                .retained_continuation_bytes()
                .is_some_and(|bytes| bytes > 0)
        );
        let span_projection = span.execute_with_counters(haystack).unwrap();
        assert_eq!(span_projection.value(), 53);
        assert!(matches!(
            span_projection.receipt_status(),
            CurrentFreAggregateCounterReceiptStatus::IncumbentProjectionForUnreceiptedSweep
        ));
        assert_eq!(span_projection.continuation_receipt(), None);
    }

    #[test]
    fn continuation_required_literal_prefix_limits_are_fully_derived() {
        let run = RunLimits::default();
        let baseline_shape = conservative_continuation_shape(5).unwrap();
        let native_service_shape = ContinuationProgramShape {
            required_literal_sets: 2,
            required_literal_source_passes: 2,
            ..baseline_shape
        };
        let baseline = continuation_operation_limits(10, baseline_shape, &run).unwrap();
        let native_service = continuation_operation_limits(10, native_service_shape, &run).unwrap();
        // Two bounded native services each read the complete source. Their
        // membership comparison charge remains one per source byte per set.
        assert_eq!(
            native_service.max_sequential_bytes,
            baseline.max_sequential_bytes + 20
        );
        assert_eq!(native_service.max_work, baseline.max_work + 40);

        let span_baseline =
            continuation_spans_operation_limits(10, baseline_shape, Some(1), &run).unwrap();
        let span_native_service =
            continuation_spans_operation_limits(10, native_service_shape, Some(1), &run).unwrap();
        assert_eq!(
            span_native_service.max_sequential_bytes,
            span_baseline.max_sequential_bytes + 20
        );
        assert_eq!(span_native_service.max_work, span_baseline.max_work + 40);

        let fused_shape = ContinuationProgramShape {
            required_literal_source_passes: 1,
            ..native_service_shape
        };
        let fused = continuation_operation_limits(10, fused_shape, &run).unwrap();
        assert_eq!(
            fused.max_sequential_bytes,
            baseline.max_sequential_bytes + 10
        );
        assert_eq!(fused.max_work, baseline.max_work + 30);

        for incomplete in [
            ContinuationProgramShape {
                required_literal_sets: 0,
                required_literal_source_passes: 1,
                ..baseline_shape
            },
            ContinuationProgramShape {
                required_literal_sets: 2,
                required_literal_source_passes: 0,
                ..baseline_shape
            },
            ContinuationProgramShape {
                required_literal_sets: 2,
                required_literal_source_passes: 3,
                ..baseline_shape
            },
        ] {
            assert!(continuation_operation_limits(10, incomplete, &run).is_err());
            assert!(continuation_spans_operation_limits(10, incomplete, Some(1), &run).is_err());
        }
    }

    #[test]
    fn streaming_complete_span_limits_are_one_pass_and_output_free() {
        let run = RunLimits::default();
        let shape = conservative_continuation_shape(5).unwrap();
        let materialized = continuation_spans_operation_limits(64, shape, Some(1), &run).unwrap();
        let streaming =
            continuation_streaming_spans_operation_limits(64, shape, Some(1), &run).unwrap();

        assert!(materialized.max_output_bytes > 0);
        assert_eq!(streaming.max_output_bytes, 0);
        assert_eq!(streaming.max_boundaries, materialized.max_boundaries);
        assert_eq!(
            streaming.max_output_matches,
            materialized.max_output_matches
        );
        assert_eq!(streaming.max_match_events, materialized.max_match_events);
        assert_eq!(streaming.max_span_sum, materialized.max_span_sum);
        assert_eq!(
            streaming.max_random_access_bytes,
            materialized.max_random_access_bytes
        );
        assert_eq!(streaming.max_log_bytes, materialized.max_log_bytes);
        assert!(streaming.max_sequential_bytes < materialized.max_sequential_bytes);
        assert!(streaming.max_work < materialized.max_work);
        assert!(streaming.max_peak_bytes <= materialized.max_peak_bytes);
    }

    #[test]
    fn cached_streaming_span_limits_admit_amortized_frontier_cache() {
        let run = RunLimits::default();
        let input_bytes = 150_600;
        let boundaries = input_bytes + 1;
        let shape = conservative_continuation_shape(1_231).unwrap();
        let materialized =
            continuation_spans_operation_limits(input_bytes, shape, Some(1), &run).unwrap();
        let ordinary_streaming =
            continuation_streaming_spans_operation_limits(input_bytes, shape, Some(1), &run)
                .unwrap();
        let cached_streaming =
            continuation_cached_streaming_spans_operation_limits(input_bytes, shape, Some(1), &run)
                .unwrap();
        let cache = cached_frontier_limits(shape.states, boundaries, 1).unwrap();

        assert_eq!(
            ordinary_streaming.max_random_access_bytes,
            materialized.max_random_access_bytes
        );
        assert_eq!(cached_streaming.max_random_access_bytes, cache.random);
        assert_eq!(cached_streaming.max_scratch_bytes, cache.scratch);
        assert!(cached_streaming.max_random_access_bytes > materialized.max_random_access_bytes);
        assert_eq!(cached_streaming.max_log_bytes, materialized.max_log_bytes);
        assert!(cached_streaming.max_sequential_bytes < materialized.max_sequential_bytes);
        assert!(cached_streaming.max_peak_bytes >= ordinary_streaming.max_peak_bytes);
        assert!(cached_streaming.max_peak_bytes <= materialized.max_peak_bytes);
        assert_eq!(cached_streaming.max_output_bytes, 0);
    }

    #[test]
    fn aggregate_many_cached_span_visit_matches_materialized_endpoints() {
        let patterns = vec![
            format!("{}[ab][\\x00-\\xff]*?", "[ab]\\B".repeat(79)),
            "z".to_string(),
        ];
        let regex =
            aggregate_many_builder_with_limits(&patterns, false, false, &RunLimits::default())
                .build_spans()
                .expect("focused aggregate-many span plan");
        let haystack = vec![b'a'; 10_000];
        let materialized_limits =
            aggregate_many_run_limits(haystack.len(), regex.build_report(), &RunLimits::default())
                .expect("materialized adapter limits");
        let expected: Vec<_> = regex
            .spans(&haystack, materialized_limits)
            .expect("materialized spans")
            .iter()
            .collect();

        let streaming_limits = aggregate_many_streaming_run_limits(
            haystack.len(),
            regex.build_report(),
            &RunLimits::default(),
        )
        .expect("cached streaming adapter limits");
        let mut actual = Vec::new();
        let visited = regex
            .visit_spans(&haystack, streaming_limits, |matched| actual.push(matched))
            .expect("cached aggregate-many span visit");
        assert_eq!(actual, expected);
        assert_eq!(visited.len(), expected.len());
        assert_eq!(
            visited.span_sum(),
            expected
                .iter()
                .map(|matched| matched.end() - matched.start())
                .sum::<usize>()
        );
        let fre::AggregateManyExecutionDetails::Continuation { certificate, .. } =
            visited.details()
        else {
            panic!("aggregate-many span visit lost its continuation receipt");
        };
        assert_eq!(
            certificate.physical_route,
            fre::AggregateOperationPhysicalRoute::CachedFrontier
        );
        assert_eq!(
            certificate.prepublication_fallback,
            fre::AggregateOperationPrepublicationFallback::DenseThenCachedFrontier
        );
    }

    #[test]
    fn url_aggregate_operation_limits_are_exported_and_quota_capped() {
        let input_bytes = 4_100;
        let upper = fre::url_aggregate_reduce_upper_bounds(input_bytes)
            .expect("URL input-only upper bound");
        let derived = url_aggregate_operation_limits(input_bytes, &RunLimits::default())
            .expect("URL adapter limits");
        assert_eq!(derived.max_boundaries, upper.boundaries);
        assert_eq!(derived.max_table_cells, 0);
        assert_eq!(
            derived.max_random_access_bytes,
            upper.random_access_storage_bytes
        );
        assert_eq!(derived.max_scratch_bytes, upper.scratch_bytes);
        assert_eq!(derived.max_log_bytes, 0);
        assert_eq!(derived.max_sequential_bytes, upper.sequential_bytes);
        assert_eq!(derived.max_match_events, upper.match_events);
        assert_eq!(derived.max_output_matches, upper.output_matches);
        assert_eq!(derived.max_output_bytes, 0);
        assert_eq!(derived.max_span_sum, upper.span_sum);
        assert_eq!(derived.max_peak_bytes, upper.peak_bytes);
        assert_eq!(
            derived.max_work,
            RunLimits::default().fre_aggregate_operation_work
        );
        let visitor_upper = fre::url_aggregate_span_visit_upper_bounds(input_bytes)
            .expect("URL visitor input-only upper bound");
        let visitor = url_aggregate_span_visit_operation_limits(input_bytes, &RunLimits::default())
            .expect("URL visitor adapter limits");
        let mut expected_visitor = derived;
        expected_visitor.max_sequential_bytes = visitor_upper.sequential_bytes;
        assert_eq!(visitor, expected_visitor);
        assert_eq!(visitor.max_sequential_bytes, input_bytes * 5);

        let capped = url_aggregate_operation_limits(
            input_bytes,
            &RunLimits {
                reducer_steps: u64::try_from(upper.boundaries - 1).unwrap(),
                fre_aggregate_random_access_bytes: upper.random_access_storage_bytes - 1,
                fre_aggregate_scratch_bytes: upper.scratch_bytes - 2,
                fre_aggregate_sequential_bytes: upper.sequential_bytes - 3,
                fre_aggregate_peak_bytes: upper.peak_bytes - 4,
                fre_aggregate_operation_work: 17,
                ..RunLimits::default()
            },
        )
        .expect("URL named quotas cap independently");
        assert_eq!(
            capped.max_random_access_bytes,
            upper.random_access_storage_bytes - 1
        );
        assert_eq!(capped.max_scratch_bytes, upper.scratch_bytes - 2);
        assert_eq!(capped.max_sequential_bytes, upper.sequential_bytes - 3);
        assert_eq!(capped.max_peak_bytes, upper.peak_bytes - 4);
        assert_eq!(capped.max_match_events, upper.boundaries - 1);
        assert_eq!(capped.max_output_matches, upper.boundaries - 1);
        assert_eq!(capped.max_work, 17);
        assert_eq!(capped.max_boundaries, upper.boundaries);
        assert_eq!(capped.max_span_sum, upper.span_sum);
    }

    #[test]
    fn cached_storage_is_derived_only_when_fixed_initialization_fits_work() {
        let cache_shape = conservative_continuation_shape(65).unwrap();
        let cache_derived =
            continuation_operation_limits(1_000, cache_shape, &RunLimits::default()).unwrap();
        let cache_storage = cached_frontier_limits(65, 1_001, 1).unwrap();
        let cache_initialization = cached_frontier_initialization_work(65, 1_001).unwrap();
        assert!(cache_initialization <= cache_derived.max_work);
        assert_eq!(cache_derived.max_random_access_bytes, cache_storage.random);
        assert_eq!(cache_derived.max_scratch_bytes, cache_storage.scratch);
        assert_eq!(cache_derived.max_log_bytes, 9_009);
        assert_eq!(cache_derived.max_sequential_bytes, 18_018);
        assert_eq!(cache_derived.max_peak_bytes, cache_storage.peak);

        let cache_ineligible = continuation_operation_limits(
            1_000,
            cache_shape,
            &RunLimits {
                fre_aggregate_operation_work: cache_initialization - 1,
                ..RunLimits::default()
            },
        )
        .unwrap();
        assert_eq!(cache_ineligible.max_random_access_bytes, 1_049);
        assert_eq!(cache_ineligible.max_scratch_bytes, 1_049);
        assert_eq!(cache_ineligible.max_log_bytes, 9_009);
        assert_eq!(cache_ineligible.max_sequential_bytes, 18_018);
        assert_eq!(cache_ineligible.max_peak_bytes, 10_058);
    }

